CREATE OR REPLACE FUNCTION public.apply_student_admission_case_action(p_organization_id uuid, p_student_user_id uuid, p_request_id uuid, p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a uuid:=auth.uid();act text:=p_command->>'action';c public.uc_admission_cases;prior public.uc_admission_case_requests;scope jsonb;ref jsonb;reqid uuid;ctx uuid;event uuid:=gen_random_uuid();receipt jsonb;payload_digest text;source jsonb;sources jsonb:='[]';defs jsonb;d jsonb;q jsonb;reqs jsonb:='[]';review jsonb;identities jsonb;identity jsonb;new_rule uuid;digest text;reason text;eid uuid;rid uuid;rev bigint;BEGIN
 IF auth.role()IS DISTINCT FROM 'authenticated'OR a IS NULL OR p_request_id IS NULL THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
 PERFORM public.uc_admission_validate_action(p_command);payload_digest:=public.uc_program_hash(jsonb_build_object('organization_id',p_organization_id,'user_id',p_student_user_id,'command',p_command));
 IF act='initialize'THEN scope:=public.uc_admission_association(p_organization_id,p_student_user_id,(p_command->>'group_id')::uuid,(p_command->>'enrollment_id')::uuid);
 ELSE SELECT * INTO c FROM public.uc_admission_cases WHERE id=(p_command->>'case_id')::uuid AND organization_id=p_organization_id AND user_id=p_student_user_id;scope:=public.uc_admission_scope(c.id);END IF;
 IF scope IS NULL THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
 PERFORM public.uc_admission_lock(a,p_organization_id,p_student_user_id,(scope->>'group_id')::uuid,(scope->>'enrollment_id')::uuid,CASE WHEN act='assign_responsible'THEN(p_command->>'responsible_id')::uuid ELSE c.responsible_id END);
 PERFORM pg_advisory_xact_lock(hashtextextended('uc_admission_request:'||a::text||':'||p_request_id::text,0));
 IF act<>'initialize'THEN SELECT * INTO c FROM public.uc_admission_cases WHERE id=(p_command->>'case_id')::uuid;
  IF act IN('review_local_rules','review_requirement','review_evidence','record_decision')AND c.responsible_id IS DISTINCT FROM a THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
  IF act='review_local_rules'AND NOT public.uc_document_action_allowed(c.organization_id,'read',NULL,NULL)THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
  IF act='assign_responsible'AND NOT public.uc_admission_staff_allowed((p_command->>'responsible_id')::uuid,c.organization_id,c.user_id,c.group_id,c.enrollment_id,false)THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
 END IF;
 SELECT * INTO prior FROM public.uc_admission_case_requests WHERE actor_id=a AND request_id=p_request_id;
 IF prior.actor_id IS NOT NULL THEN IF prior.payload_digest<>payload_digest OR prior.organization_id<>p_organization_id OR prior.user_id<>p_student_user_id OR prior.kind<>act THEN PERFORM public.uc_admission_error('REVISION_CONFLICT');END IF;RETURN public.uc_admission_result(prior.case_id,a,prior.receipt,true);END IF;
 IF act='initialize'THEN
  ref:=public.uc_admission_program(p_organization_id,p_student_user_id,(scope->>'group_id')::uuid,(scope->>'enrollment_id')::uuid);IF ref IS NULL THEN PERFORM public.uc_admission_error('PREREQUISITE_MISSING');END IF;
  IF ref IS DISTINCT FROM p_command->'expected_program_ref'THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;
  IF EXISTS(SELECT 1 FROM public.uc_admission_cases WHERE organization_id=p_organization_id AND group_id=(scope->>'group_id')::uuid AND enrollment_id=(scope->>'enrollment_id')::uuid)THEN PERFORM public.uc_admission_error('REVISION_CONFLICT');END IF;
  INSERT INTO public.uc_admission_cases(organization_id,user_id,group_id,enrollment_id,course_id,program_ref,program_title,program_type,revision)SELECT p_organization_id,p_student_user_id,(scope->>'group_id')::uuid,(scope->>'enrollment_id')::uuid,(scope->>'course_id')::uuid,ref,public.uc_admission_trim(v.facts->>'full_title'),v.facts->>'program_type',1 FROM public.program_fact_versions v WHERE v.id=(ref->>'version_id')::uuid RETURNING * INTO c;
  ctx:=public.uc_admission_context(c.id,a,'mutation');
 ELSE
  SELECT * INTO c FROM public.uc_admission_cases WHERE id=c.id FOR UPDATE;
  IF c.revision<>(p_command->>'expected_revision')::bigint THEN PERFORM public.uc_admission_error('REVISION_CONFLICT');END IF;
  IF c.revision>=9007199254740991 THEN PERFORM public.uc_admission_error('LIMIT_REACHED');END IF;
  IF c.program_ref IS DISTINCT FROM p_command->'expected_program_ref'OR c.program_ref IS DISTINCT FROM public.uc_admission_program(c.organization_id,c.user_id,c.group_id,c.enrollment_id)THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;
  IF act IN('review_local_rules','review_requirement','review_evidence','record_decision')AND c.responsible_id IS DISTINCT FROM a THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
  ctx:=public.uc_admission_context(c.id,a,'mutation');
  UPDATE public.uc_admission_cases SET revision=revision+1,updated_at=clock_timestamp()WHERE id=c.id RETURNING * INTO c;
  reason:=coalesce(p_command->>'reason',p_command->>'review_reason');
  IF act='assign_responsible'THEN
   IF NOT public.uc_admission_staff_allowed((p_command->>'responsible_id')::uuid,c.organization_id,c.user_id,c.group_id,c.enrollment_id,false)THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
   UPDATE public.uc_admission_cases SET responsible_id=(p_command->>'responsible_id')::uuid WHERE id=c.id;
  ELSIF act='review_local_rules'THEN
   IF NOT public.uc_document_action_allowed(c.organization_id,'read',NULL,NULL)THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
   IF jsonb_typeof(p_command->'sources')IS DISTINCT FROM 'array'OR jsonb_array_length(p_command->'sources')NOT BETWEEN 1 AND 3 OR jsonb_typeof(p_command->'requirements')IS DISTINCT FROM 'array'OR jsonb_array_length(p_command->'requirements')NOT BETWEEN 3 AND 50 THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
   FOR source IN SELECT x FROM jsonb_array_elements(p_command->'sources')x LOOP
    IF NOT public.uc_admission_shape(source,ARRAY['document_id','version_id','review_id'])OR NOT public.uc_admission_uuid(source->'document_id')OR NOT public.uc_admission_uuid(source->'version_id')OR NOT public.uc_admission_uuid(source->'review_id')THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
    PERFORM public.uc_admission_lock_rules(jsonb_build_array(source));d:=public.uc_admission_local_source(c.organization_id,source);IF d IS NULL THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;sources:=sources||jsonb_build_array(d);END LOOP;
   IF(SELECT count(DISTINCT x->>'document_id')FROM jsonb_array_elements(p_command->'sources')x)<>jsonb_array_length(sources)THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
   defs:=p_command->'requirements';IF(SELECT count(DISTINCT x->>'key')FROM jsonb_array_elements(defs)x)<>jsonb_array_length(defs)OR EXISTS(SELECT 1 FROM unnest(ARRAY['education_basis','application','contract_or_funding'])k WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(defs)x WHERE x->>'kind'=k))THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
   FOR d IN SELECT x FROM jsonb_array_elements(defs)x LOOP
    IF NOT public.uc_admission_shape(d,ARRAY['key','kind','staff_label','source_version_ids','provision','exception_policy'])OR coalesce(jsonb_typeof(d->'key')='string'AND d->>'key'~'^[a-z0-9_]{1,64}$'AND d->>'kind'IN('education_basis','application','contract_or_funding','other_reviewed')AND d->>'exception_policy'IN('not_defined','local_reasoned_exception'),false)=false OR NOT public.uc_admission_text(d->'staff_label',160)OR NOT public.uc_admission_text(d->'provision',1000)OR NOT public.uc_admission_ids(d->'source_version_ids',1,3)THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(d->'source_version_ids')v WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sources)s WHERE s->'version_id'=v))THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;END LOOP;
   new_rule:=gen_random_uuid();digest:=public.uc_program_hash(jsonb_build_object('program_ref',c.program_ref,'source_snapshots',sources,'definitions',defs));identities:=coalesce(c.reviews->'identities','{}');
   FOR d IN SELECT x FROM jsonb_array_elements(defs)x LOOP
    identity:=identities->(d->>'key');reqid:=coalesce((identity->>'id')::uuid,gen_random_uuid());rev:=coalesce((identity->>'revision')::bigint,0)+1;
    IF rev>9007199254740991 THEN PERFORM public.uc_admission_error('LIMIT_REACHED');END IF;identities:=identities||jsonb_build_object(d->>'key',jsonb_build_object('id',reqid,'revision',rev));
    reqs:=reqs||jsonb_build_array(jsonb_build_object('id',reqid,'revision',rev,'rule_id',gen_random_uuid(),'rule_set_id',new_rule,'rule_set_digest',digest,'label',d->'staff_label','applicability','unknown','review_event_id',NULL,'evidence_version_ids','[]'::jsonb,'current_state','unknown','public_next_action','Обратитесь к ответственному сотруднику'));END LOOP;
   source:=public.uc_admission_authority(c.id,a);INSERT INTO public.uc_admission_rule_sets(id,case_id,organization_id,user_id,program_ref,digest,sources,source_snapshots,definitions,reviewer_id,authority_hash,authority_snapshot,review_reason)VALUES(new_rule,c.id,c.organization_id,c.user_id,c.program_ref,digest,p_command->'sources',sources,defs,a,public.uc_program_hash(source),source,reason);
   UPDATE public.uc_admission_cases SET rule_set_id=new_rule,requirements=reqs,reviews=jsonb_build_object('identities',identities,'requirements','{}'::jsonb,'evidence','{}'::jsonb)WHERE id=c.id;
  ELSIF act IN('review_requirement','review_evidence')THEN
   SELECT x INTO q FROM jsonb_array_elements(c.requirements)x WHERE x->>'id'=p_command->>'requirement_id';IF q IS NULL OR(q->>'revision')::bigint<>(p_command->>'expected_requirement_revision')::bigint THEN PERFORM public.uc_admission_error('REVISION_CONFLICT');END IF;
   IF NOT public.uc_admission_rules_current(c.id)THEN PERFORM public.uc_admission_error('REVIEW_REQUIRED');END IF;
   IF act='review_requirement'THEN
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_command->'evidence_version_ids')x WHERE NOT EXISTS(SELECT 1 FROM public.uc_admission_case_evidence e WHERE e.id=(x#>>'{}')::uuid AND e.case_id=c.id AND e.requirement_id=(q->>'id')::uuid AND NOT EXISTS(SELECT 1 FROM public.uc_admission_case_evidence n WHERE n.case_id=c.id AND n.supersedes_id=e.id)))THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;
    IF p_command->'exception'<>'null'::jsonb THEN
     IF p_command->>'applicability'<>'applicable'OR p_command->'exception'->>'rule_id'<>q->>'rule_id'OR NOT EXISTS(SELECT 1 FROM public.uc_admission_rule_sets rs,jsonb_array_elements(rs.definitions)d WHERE rs.id=c.rule_set_id AND d->>'exception_policy'='local_reasoned_exception'AND c.reviews->'identities'->(d->>'key')->>'id'=q->>'id')OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_command->'exception'->'evidence_version_ids')x WHERE NOT p_command->'evidence_version_ids'@>jsonb_build_array(x))THEN PERFORM public.uc_admission_error('REVIEW_REQUIRED');END IF;END IF;
    SELECT coalesce(jsonb_agg(CASE WHEN x->>'id'=q->>'id'THEN x||jsonb_build_object('applicability',p_command->'applicability','review_event_id',event)ELSE x END),'[]')INTO reqs FROM jsonb_array_elements(c.requirements)x;
    review:=jsonb_build_object('actor_id',a,'reason',reason,'exception',p_command->'exception','event_id',event,'requirement_revision',q->'revision');
    UPDATE public.uc_admission_cases SET requirements=reqs,reviews=jsonb_set(reviews,ARRAY['requirements',q->>'id'],review,true)WHERE id=c.id;
   ELSE
    eid:=(p_command->>'evidence_version_id')::uuid;
    IF NOT EXISTS(SELECT 1 FROM public.uc_admission_case_evidence e WHERE e.id=eid AND e.case_id=c.id AND e.requirement_id=(q->>'id')::uuid AND e.byte_sha256=p_command->>'byte_sha256'AND NOT EXISTS(SELECT 1 FROM public.uc_admission_case_evidence n WHERE n.case_id=c.id AND n.supersedes_id=e.id))OR public.uc_admission_evidence_dto(eid,a)->>'availability'<>'available'THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;
    review:=jsonb_build_object('actor_id',a,'reason',reason,'event_id',event,'outcome',p_command->'outcome','requirement_revision',q->'revision');UPDATE public.uc_admission_cases SET reviews=jsonb_set(reviews,ARRAY['evidence',eid::text],review,true)WHERE id=c.id;
   END IF;
  ELSIF act='record_decision'THEN
   PERFORM public.uc_admission_lock_rules((SELECT rs.sources FROM public.uc_admission_rule_sets rs WHERE rs.id=c.rule_set_id));PERFORM public.uc_admission_refresh(c.id);SELECT * INTO c FROM public.uc_admission_cases WHERE id=c.id;
   IF c.rule_set_id IS DISTINCT FROM(p_command->>'rule_set_id')::uuid OR(SELECT rs.digest FROM public.uc_admission_rule_sets rs WHERE rs.id=c.rule_set_id)IS DISTINCT FROM p_command->>'rule_set_digest'OR public.uc_admission_requirements_digest(c.id)IS DISTINCT FROM p_command->>'requirements_digest'THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;
   IF NOT public.uc_admission_rules_current(c.id)THEN PERFORM public.uc_admission_error('REVIEW_REQUIRED');END IF;
   IF p_command->>'outcome'='admitted'AND(jsonb_array_length(c.requirements)<3 OR EXISTS(SELECT 1 FROM jsonb_array_elements(c.requirements)x WHERE x->>'applicability'='unknown'OR x->>'current_state'NOT IN('satisfied','exception_recorded')))THEN PERFORM public.uc_admission_error('REVIEW_REQUIRED');END IF;
   SELECT coalesce(jsonb_agg(e.id ORDER BY e.id),'[]')INTO d FROM public.uc_admission_case_evidence e WHERE e.case_id=c.id AND NOT EXISTS(SELECT 1 FROM public.uc_admission_case_evidence n WHERE n.case_id=c.id AND n.supersedes_id=e.id);
   IF public.uc_program_hash(d)<>public.uc_program_hash((SELECT coalesce(jsonb_agg(x ORDER BY x),'[]')FROM jsonb_array_elements(p_command->'evidence_version_ids')x))THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;
   UPDATE public.uc_admission_cases SET decision=jsonb_build_object('event_id',event,'case_revision',revision,'outcome',p_command->'outcome','recorded_at',clock_timestamp(),'responsible_id',a,'reason',reason,'program_ref',program_ref,'rule_set_id',rule_set_id,'requirements_digest',p_command->'requirements_digest','evidence_version_ids',p_command->'evidence_version_ids','authority_snapshot_hash',public.uc_program_hash(jsonb_build_array(a,public.uc_admission_scope(c.id),true)),'later_review_required',false)WHERE id=c.id;
  END IF;
 END IF;
 PERFORM public.uc_admission_refresh(c.id);receipt:=public.uc_admission_event(c.id,a,event,act,p_request_id,payload_digest,reason);
 DELETE FROM public.uc_admission_case_requests WHERE actor_id=a AND request_id=ctx AND kind='_context';RETURN public.uc_admission_result(c.id,a,receipt,false);
END;$function$

CREATE OR REPLACE FUNCTION public.auto_create_education_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_course public.courses%ROWTYPE;
  v_program_source public.group_program_enrollment_snapshots;
  v_association_count integer;
  v_full_name text;
  v_birth_date date;
  v_group_id uuid;
  v_doc_type text;
  v_doc_n integer;
  v_reg_n integer;
  v_max_doc integer;
  v_max_reg integer;
  v_year integer;
BEGIN
  IF NEW.status IS DISTINCT FROM 'completed'
     OR (TG_OP = 'UPDATE' AND OLD.status = 'completed') THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_course FROM public.courses WHERE id = NEW.course_id;
  IF NOT FOUND THEN RETURN NEW; END IF;
  -- Completion stays successful when provenance or issuance authority is unknown.
  -- Multiple effective associations require explicit group selection; never pick the first.
  SELECT count(*) INTO v_association_count FROM public.student_group_memberships_effective m
  JOIN public.student_groups g ON g.id=m.group_id AND g.organization_id=m.organization_id
  WHERE m.user_id=NEW.user_id AND m.organization_id=v_course.organization_id AND g.course_id=NEW.course_id;
  IF v_association_count<>1 THEN RETURN NEW; END IF;
  SELECT m.group_id INTO v_group_id FROM public.student_group_memberships_effective m JOIN public.student_groups g ON g.id=m.group_id AND g.organization_id=m.organization_id
  WHERE m.user_id=NEW.user_id AND m.organization_id=v_course.organization_id AND g.course_id=NEW.course_id;
  IF NOT coalesce(public.uc_document_has_action(v_course.organization_id,'issue') AND public.uc_document_record_scope(v_course.organization_id,v_group_id,NEW.id,NEW.user_id,NEW.course_id),false) THEN RETURN NEW; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_course.organization_id::text, 0));
  v_program_source:=public.uc_program_issuance_source(v_course.organization_id,v_group_id,NEW.id,NEW.user_id,NEW.course_id);
  v_course.title:=v_program_source.program_snapshot->'facts'->>'full_title';
  v_course.frdo_qualification_name:=coalesce(v_program_source.program_snapshot->'facts'->>'qualification',v_program_source.program_snapshot->'facts'->>'profession');
  v_doc_type := CASE v_program_source.program_snapshot->'facts'->>'program_type'
    WHEN 'dpo_upskilling' THEN 'certificate'
    WHEN 'dpo_retraining' THEN 'diploma'
    WHEN 'professional_training' THEN 'qualification'
    ELSE NULL
  END;
  IF v_doc_type IS NULL THEN RETURN NEW; END IF;

  IF EXISTS (
    SELECT 1 FROM public.education_document_records edr
    WHERE edr.enrollment_id = NEW.id
      AND lower(btrim(edr.document_status)) IN ('original', 'оригинал')
      AND edr.deleted_at IS NULL
  ) THEN RETURN NEW; END IF;

  SELECT NULLIF(BTRIM(p.full_name), '')
  INTO v_full_name
  FROM public.profiles p
  WHERE p.user_id = NEW.user_id AND p.organization_id = v_course.organization_id
  LIMIT 1;

  SELECT sfd.birth_date INTO v_birth_date
  FROM public.student_frdo_data sfd
  WHERE sfd.user_id = NEW.user_id AND sfd.organization_id = v_course.organization_id
  LIMIT 1;
  IF v_full_name IS NULL OR v_birth_date IS NULL THEN RETURN NEW; END IF;

  v_year := EXTRACT(YEAR FROM CURRENT_DATE)::integer;
  SELECT COALESCE(MAX((substring(edr.document_number FROM '([0-9]+)$'))::integer), 0)
  INTO v_max_doc
  FROM public.education_document_records edr
  WHERE edr.organization_id = v_course.organization_id
    AND EXTRACT(YEAR FROM edr.issue_date) = v_year AND edr.deleted_at IS NULL;

  INSERT INTO public.document_number_sequences (organization_id, doc_type, year, last_number)
  VALUES (v_course.organization_id, 'edu_doc', v_year, v_max_doc + 1)
  ON CONFLICT (organization_id, doc_type, year)
  DO UPDATE SET last_number = GREATEST(document_number_sequences.last_number + 1, v_max_doc + 1), updated_at = now()
  RETURNING last_number INTO v_doc_n;

  SELECT COALESCE(MAX((substring(edr.reg_number FROM '([0-9]+)$'))::integer), 0)
  INTO v_max_reg
  FROM public.education_document_records edr
  WHERE edr.organization_id = v_course.organization_id
    AND EXTRACT(YEAR FROM edr.issue_date) = v_year AND edr.deleted_at IS NULL;

  INSERT INTO public.document_number_sequences (organization_id, doc_type, year, last_number)
  VALUES (v_course.organization_id, 'edu_reg', v_year, v_max_reg + 1)
  ON CONFLICT (organization_id, doc_type, year)
  DO UPDATE SET last_number = GREATEST(document_number_sequences.last_number + 1, v_max_reg + 1), updated_at = now()
  RETURNING last_number INTO v_reg_n;

  INSERT INTO public.education_document_records (
    organization_id, user_id, course_id, group_id, enrollment_id,
    full_name, birth_date, document_type, document_number, reg_number,
    issue_date, specialty_name, qualification_name, document_status, delivery_method
  ) VALUES (
    v_course.organization_id, NEW.user_id, NEW.course_id, v_group_id, NEW.id,
    v_full_name, v_birth_date, v_doc_type,
    v_year || '/' || LPAD(v_doc_n::text, 6, '0'),
    'ДОК-' || v_year || '/' || LPAD(v_reg_n::text, 4, '0'),
    CURRENT_DATE, v_course.title, v_course.frdo_qualification_name, 'original', 'personal'
  );
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'education document was not auto-created for enrollment %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.issue_education_document_batch(p_organization_id uuid, p_group_id uuid, p_course_id uuid, p_items jsonb)
 RETURNS SETOF education_document_records
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item jsonb;
  v_user_id uuid;
  v_enrollment_id uuid;
  v_doc_type text;
  v_issue_date date;
  v_year int;
  v_doc_n int;
  v_reg_n int;
  v_max_doc int;
  v_max_reg int;
  v_doc_number text;
  v_reg_number text;
  v_new_id uuid;
  v_existing_id uuid;
  v_group_course_id uuid;
  v_ids uuid[] := '{}';
  v_items_count int;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Auth required'; END IF;
  IF p_organization_id IS NULL THEN RAISE EXCEPTION 'organization_id is required'; END IF;
  IF p_course_id IS NULL THEN RAISE EXCEPTION 'exact course_id is required'; END IF;
  IF NOT public.uc_document_has_action(p_organization_id,'issue') THEN
    RAISE EXCEPTION 'not authorized for this organization';
  END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'items must be a non-empty array';
  END IF;
  v_items_count := jsonb_array_length(p_items);
  IF v_items_count = 0 THEN RAISE EXCEPTION 'items must be a non-empty array'; END IF;
  IF v_items_count > 500 THEN RAISE EXCEPTION 'items exceed max batch size (500)'; END IF;

  IF NOT EXISTS (SELECT 1 FROM public.courses c WHERE c.id = p_course_id AND c.organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'course % does not belong to organization', p_course_id;
  END IF;
  IF p_group_id IS NOT NULL THEN
    SELECT g.course_id INTO v_group_course_id FROM public.student_groups g
    WHERE g.id = p_group_id AND g.organization_id = p_organization_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'group % does not belong to organization', p_group_id; END IF;
    IF v_group_course_id IS NULL OR v_group_course_id <> p_course_id THEN
      RAISE EXCEPTION 'group % is not linked to exact course %', p_group_id, p_course_id;
    END IF;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_organization_id::text, 0));
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_user_id := NULLIF(v_item->>'user_id', '')::uuid;
    v_enrollment_id := NULLIF(v_item->>'enrollment_id', '')::uuid;
    IF NOT public.uc_document_action_allowed(p_organization_id,'issue',p_group_id,v_enrollment_id) THEN RAISE EXCEPTION 'Issuance scope denied' USING ERRCODE='42501'; END IF;
    v_doc_type := NULLIF(btrim(v_item->>'document_type'), '');
    IF v_user_id IS NULL THEN RAISE EXCEPTION 'user_id is required for every item'; END IF;
    IF v_enrollment_id IS NULL THEN RAISE EXCEPTION 'enrollment_id is required for every item'; END IF;
    IF v_doc_type NOT IN ('certificate', 'diploma', 'qualification') THEN
      RAISE EXCEPTION 'document_type must be certificate, diploma or qualification';
    END IF;
    IF NULLIF(v_item->>'issue_date', '') IS NULL THEN RAISE EXCEPTION 'issue_date is required for every item'; END IF;
    v_issue_date := (v_item->>'issue_date')::date;
    v_year := EXTRACT(YEAR FROM v_issue_date)::int;

    IF NOT EXISTS (
      SELECT 1 FROM public.profiles pr
      WHERE pr.user_id = v_user_id AND pr.organization_id = p_organization_id
        AND (p_group_id IS NULL OR EXISTS (SELECT 1 FROM public.student_group_memberships_effective m WHERE m.organization_id = pr.organization_id AND m.user_id = pr.user_id AND m.group_id = p_group_id))
    ) THEN RAISE EXCEPTION 'student % is not a member of the specified organization/group', v_user_id; END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public.enrollments e JOIN public.courses c ON c.id = e.course_id
      WHERE e.id = v_enrollment_id AND e.user_id = v_user_id AND e.course_id = p_course_id
        AND c.organization_id = p_organization_id
    ) THEN
      RAISE EXCEPTION 'enrollment % does not belong to student %/exact course %', v_enrollment_id, v_user_id, p_course_id;
    END IF;

    -- One enrollment has one original education document. Re-export returns it.
    SELECT r.id INTO v_existing_id
    FROM public.education_document_records r
    WHERE r.organization_id = p_organization_id AND r.enrollment_id = v_enrollment_id
      AND lower(btrim(r.document_status)) IN ('original', 'оригинал') AND r.deleted_at IS NULL
    ORDER BY r.created_at, r.id LIMIT 1;
    IF v_existing_id IS NOT NULL THEN
      IF EXISTS(SELECT 1 FROM public.education_document_program_sources ps WHERE ps.record_id=v_existing_id
       AND (ps.snapshot->>'group_id')::uuid IS DISTINCT FROM p_group_id) THEN
       RAISE EXCEPTION 'original_document_belongs_to_other_program_association' USING ERRCODE='22023'; END IF;
      v_ids := array_append(v_ids, v_existing_id); CONTINUE;
    END IF;

    SELECT COALESCE(MAX((substring(r.document_number FROM '([0-9]+)$'))::int), 0) INTO v_max_doc
    FROM public.education_document_records r
    WHERE r.organization_id = p_organization_id AND EXTRACT(YEAR FROM r.issue_date) = v_year AND r.deleted_at IS NULL;
    INSERT INTO public.document_number_sequences (organization_id, doc_type, year, last_number)
    VALUES (p_organization_id, 'edu_doc', v_year, v_max_doc + 1)
    ON CONFLICT (organization_id, doc_type, year)
    DO UPDATE SET last_number = GREATEST(document_number_sequences.last_number + 1, v_max_doc + 1), updated_at = now()
    RETURNING last_number INTO v_doc_n;

    SELECT COALESCE(MAX((substring(r.reg_number FROM '([0-9]+)$'))::int), 0) INTO v_max_reg
    FROM public.education_document_records r
    WHERE r.organization_id = p_organization_id AND EXTRACT(YEAR FROM r.issue_date) = v_year AND r.deleted_at IS NULL;
    INSERT INTO public.document_number_sequences (organization_id, doc_type, year, last_number)
    VALUES (p_organization_id, 'edu_reg', v_year, v_max_reg + 1)
    ON CONFLICT (organization_id, doc_type, year)
    DO UPDATE SET last_number = GREATEST(document_number_sequences.last_number + 1, v_max_reg + 1), updated_at = now()
    RETURNING last_number INTO v_reg_n;

    v_doc_number := v_year::text || '/' || lpad(v_doc_n::text, 6, '0');
    v_reg_number := 'ДОК-' || v_year::text || '/' || lpad(v_reg_n::text, 4, '0');
    INSERT INTO public.education_document_records (
      organization_id, user_id, course_id, group_id, enrollment_id,
      reg_number, document_number, document_series, document_type,
      full_name, birth_date, issue_date, specialty_name, qualification_name,
      document_status, delivery_method, education_result, notes
    ) VALUES (
      p_organization_id, v_user_id, p_course_id, p_group_id, v_enrollment_id,
      v_reg_number, v_doc_number, NULLIF(v_item->>'document_series', ''), v_doc_type,
      COALESCE(NULLIF(v_item->>'full_name', ''), ''), NULLIF(v_item->>'birth_date', '')::date,
      v_issue_date, COALESCE(NULLIF(v_item->>'specialty_name', ''), ''),
      NULLIF(v_item->>'qualification_name', ''), COALESCE(NULLIF(v_item->>'document_status', ''), 'original'),
      COALESCE(NULLIF(v_item->>'delivery_method', ''), 'personal'),
      NULLIF(v_item->>'education_result', ''), NULLIF(v_item->>'notes', '')
    ) RETURNING id INTO v_new_id;
    v_ids := array_append(v_ids, v_new_id);
  END LOOP;

  RETURN QUERY SELECT * FROM public.education_document_records r
  WHERE r.id = ANY(v_ids) ORDER BY array_position(v_ids, r.id);
END;
$function$

CREATE OR REPLACE FUNCTION public.read_student_admission_case(p_organization_id uuid, p_student_user_id uuid, p_query jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a uuid:=auth.uid();mode text:=p_query->>'mode';c public.uc_admission_cases;scope jsonb;pr jsonb;pre jsonb;items jsonb:='[]';row record;candidate jsonb;has_more boolean:=false;next_id uuid;lim integer;after_id uuid;kind text;ceiling bigint;before_rev bigint;counted integer:=0;staff boolean;BEGIN
 IF auth.role()IS DISTINCT FROM 'authenticated'OR NOT public.uc_admission_actor_allowed(a,false)OR NOT public.uc_identification_target_allowed(p_organization_id,p_student_user_id,true)THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
 IF mode='case'THEN
  IF NOT public.uc_admission_shape(p_query,ARRAY['mode','group_id','enrollment_id'])OR NOT public.uc_admission_uuid(p_query->'group_id')OR NOT public.uc_admission_uuid(p_query->'enrollment_id')THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
  scope:=public.uc_admission_association(p_organization_id,p_student_user_id,(p_query->>'group_id')::uuid,(p_query->>'enrollment_id')::uuid);
  IF scope IS NULL OR NOT public.uc_admission_can_read(a,p_organization_id,p_student_user_id,(p_query->>'group_id')::uuid,(p_query->>'enrollment_id')::uuid)THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
  SELECT * INTO c FROM public.uc_admission_cases WHERE organization_id=p_organization_id AND user_id=p_student_user_id AND group_id=(p_query->>'group_id')::uuid AND enrollment_id=(p_query->>'enrollment_id')::uuid;
  pr:=public.uc_admission_program(p_organization_id,p_student_user_id,(p_query->>'group_id')::uuid,(p_query->>'enrollment_id')::uuid);pre:=public.uc_admission_prerequisites(p_organization_id,p_student_user_id,(p_query->>'group_id')::uuid,(p_query->>'enrollment_id')::uuid,c.id IS NOT NULL AND c.rule_set_id IS NULL);
  IF a=p_student_user_id THEN RETURN jsonb_build_object('schema_version',1,'mode','case','projection','learner','scope',scope,'state',CASE WHEN c.id IS NOT NULL THEN public.uc_admission_state(c.id,a,true)END,'prerequisites',pre);END IF;
  RETURN jsonb_build_object('schema_version',1,'mode','case','projection','staff','scope',scope,'program_ref',pr,'program_title',(SELECT public.uc_admission_trim(facts->>'full_title')FROM public.program_fact_versions WHERE id=(pr->>'version_id')::uuid),'state',CASE WHEN c.id IS NOT NULL THEN public.uc_admission_state(c.id,a,false)END,'prerequisites',pre,'capabilities',public.uc_admission_capabilities(a,p_organization_id,p_student_user_id,(p_query->>'group_id')::uuid,(p_query->>'enrollment_id')::uuid,c.id));
 END IF;
 IF mode='history'THEN
  IF NOT public.uc_admission_shape(p_query,ARRAY['mode','case_id','ceiling_revision','before_revision','limit'])THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
 ELSE
  IF NOT public.uc_admission_shape(p_query,CASE mode WHEN 'associations'THEN ARRAY['mode','after_id','limit']WHEN 'candidates'THEN ARRAY['mode','case_id','kind','after_id','limit']WHEN 'options'THEN ARRAY['mode','case_id','kind','after_id','limit']ELSE ARRAY[]::text[]END)THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
 END IF;
 IF jsonb_typeof(p_query->'limit')IS DISTINCT FROM 'number'OR p_query->>'limit'!~'^[0-9]{1,2}$'OR(p_query->>'limit')::integer NOT BETWEEN 1 AND 50 THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;lim:=(p_query->>'limit')::integer;
 IF mode<>'history'THEN IF p_query->'after_id'<>'null'::jsonb AND NOT public.uc_admission_uuid(p_query->'after_id')THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;after_id:=(p_query->>'after_id')::uuid;END IF;
 IF mode='associations'THEN
  staff:=public.has_role(a,'admin'::public.app_role)OR public.is_org_owner(a,p_organization_id)OR EXISTS(SELECT 1 FROM public.org_staff s WHERE s.user_id=a AND s.organization_id=p_organization_id AND s.role<>'teacher'AND(s.expires_at IS NULL OR s.expires_at>now())AND public.has_org_staff_permission(a,p_organization_id,'students.read')AND public.has_org_staff_permission(a,p_organization_id,'documents.read'));
  IF a<>p_student_user_id AND NOT staff AND NOT EXISTS(SELECT 1 FROM public.student_groups g JOIN public.enrollments e ON e.course_id=g.course_id AND e.user_id=p_student_user_id WHERE g.organization_id=p_organization_id AND public.uc_admission_staff_allowed(a,p_organization_id,p_student_user_id,g.id,e.id,false))THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
  FOR row IN SELECT g.id group_id,e.id enrollment_id,coalesce(nullif(public.uc_admission_trim(left(g.name,160)),''),'Группа без названия')group_label FROM public.student_groups g JOIN public.enrollments e ON e.course_id=g.course_id AND e.user_id=p_student_user_id WHERE g.organization_id=p_organization_id AND(after_id IS NULL OR g.id>after_id)AND public.uc_admission_can_read(a,p_organization_id,p_student_user_id,g.id,e.id)ORDER BY g.id LIMIT lim+1 LOOP
   counted:=counted+1;IF counted>lim THEN has_more:=true;EXIT;END IF;
   scope:=public.uc_admission_association(p_organization_id,p_student_user_id,row.group_id,row.enrollment_id);
   items:=items||jsonb_build_array(jsonb_build_object('scope',scope,'group_label',row.group_label,'case_id',(SELECT id FROM public.uc_admission_cases WHERE organization_id=p_organization_id AND group_id=row.group_id AND enrollment_id=row.enrollment_id),'prerequisites',public.uc_admission_prerequisites(p_organization_id,p_student_user_id,row.group_id,row.enrollment_id,false)));next_id:=row.group_id;END LOOP;
  pre:='[]';IF counted=0 AND after_id IS NULL THEN pre:=jsonb_build_array(jsonb_build_object('code',CASE WHEN EXISTS(SELECT 1 FROM public.enrollments e JOIN public.courses co ON co.id=e.course_id WHERE e.user_id=p_student_user_id AND co.organization_id=p_organization_id)THEN 'missing_group'ELSE 'missing_enrollment'END,'public_label','Выберите подтверждённую учебную связь','next_action','select_exact_association','persisted',false));END IF;
  RETURN jsonb_build_object('schema_version',1,'mode',mode,'organization_id',p_organization_id,'user_id',p_student_user_id,'items',items,'prerequisites',pre,'has_more',has_more,'next_after_id',CASE WHEN has_more THEN next_id END);
 END IF;
 IF NOT public.uc_admission_uuid(p_query->'case_id')THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
 SELECT * INTO c FROM public.uc_admission_cases WHERE id=(p_query->>'case_id')::uuid AND organization_id=p_organization_id AND user_id=p_student_user_id;
 IF c.id IS NULL OR NOT public.uc_admission_staff_allowed(a,c.organization_id,c.user_id,c.group_id,c.enrollment_id,false)THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
 IF mode='history'THEN
  IF(p_query->'ceiling_revision'<>'null'::jsonb AND(p_query->>'ceiling_revision'!~'^[1-9][0-9]{0,15}$'OR(p_query->>'ceiling_revision')::numeric>9007199254740991))OR(p_query->'before_revision'<>'null'::jsonb AND(p_query->>'before_revision'!~'^[1-9][0-9]{0,15}$'OR(p_query->>'before_revision')::numeric>9007199254740991))THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
  ceiling:=coalesce((p_query->>'ceiling_revision')::bigint,c.revision);before_rev:=(p_query->>'before_revision')::bigint;IF ceiling>c.revision OR(before_rev IS NOT NULL AND before_rev>ceiling+1)THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
  FOR row IN SELECT * FROM public.uc_admission_case_events WHERE case_id=c.id AND case_revision<=ceiling AND(before_rev IS NULL OR case_revision<before_rev)ORDER BY case_revision DESC LIMIT lim+1 LOOP counted:=counted+1;IF counted>lim THEN has_more:=true;EXIT;END IF;items:=items||jsonb_build_array(jsonb_build_object('id',row.id,'case_id',row.case_id,'case_revision',row.case_revision,'kind',row.kind,'recorded_at',row.recorded_at,'actor_id',row.actor_id,'payload',public.uc_admission_history_payload(row.payload,a)));before_rev:=row.case_revision;END LOOP;
  RETURN jsonb_build_object('schema_version',1,'mode',mode,'case_id',c.id,'ceiling_revision',ceiling,'items',items,'has_more',has_more,'next_before_revision',CASE WHEN has_more THEN before_rev END);
 ELSIF mode='candidates'THEN
  kind:=p_query->>'kind';IF kind NOT IN('identity_document','enrollment_document','organization_document_version','contract_artifact')THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
  IF kind='organization_document_version'AND NOT public.uc_document_action_allowed(c.organization_id,'read',NULL,NULL)THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
  FOR row IN SELECT * FROM(
   SELECT d.id,NULL::uuid version_id FROM public.student_identity_documents d WHERE kind='identity_document'AND d.user_id=c.user_id AND d.organization_id=c.organization_id
   UNION ALL SELECT d.id,NULL::uuid FROM public.student_documents d WHERE kind='enrollment_document'AND d.enrollment_id=c.enrollment_id
   UNION ALL SELECT d.id,d.current_version_id FROM public.org_documents d WHERE kind='organization_document_version'AND d.organization_id=c.organization_id AND public.uc_program_file_proof(c.organization_id,d.current_version_id)
   UNION ALL SELECT d.id,NULL::uuid FROM public.org_contracts d WHERE kind='contract_artifact'AND d.organization_id=c.organization_id AND d.student_user_id=c.user_id
  )q WHERE after_id IS NULL OR id>after_id ORDER BY id LIMIT lim+1 LOOP counted:=counted+1;IF counted>lim THEN has_more:=true;EXIT;END IF;candidate:=public.uc_admission_candidate(c.id,kind,row.id,row.version_id);IF candidate IS NULL THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;items:=items||jsonb_build_array(candidate->'candidate');next_id:=row.id;END LOOP;
  RETURN jsonb_build_object('schema_version',1,'mode',mode,'case_id',c.id,'case_revision',c.revision,'items',items,'has_more',has_more,'next_after_id',CASE WHEN has_more THEN next_id END);
 ELSIF mode='options'THEN
  kind:=p_query->>'kind';IF kind NOT IN('responsibles','local_acts')THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
  IF kind='responsibles'THEN
   FOR row IN SELECT q.user_id,coalesce(nullif(public.uc_admission_trim(left(s.display_name,160)),''),nullif(public.uc_admission_trim(left(p.full_name,160)),''),'Сотрудник')display_name FROM(SELECT user_id FROM public.org_staff WHERE organization_id=c.organization_id UNION SELECT user_id FROM public.profiles WHERE organization_id=c.organization_id UNION SELECT a)q LEFT JOIN public.org_staff s ON s.user_id=q.user_id AND s.organization_id=c.organization_id LEFT JOIN public.profiles p ON p.user_id=q.user_id WHERE(after_id IS NULL OR q.user_id>after_id)AND public.uc_admission_staff_allowed(q.user_id,c.organization_id,c.user_id,c.group_id,c.enrollment_id,true)AND public.uc_admission_staff_allowed(q.user_id,c.organization_id,c.user_id,c.group_id,c.enrollment_id,false)ORDER BY q.user_id LIMIT lim+1 LOOP counted:=counted+1;IF counted>lim THEN has_more:=true;EXIT;END IF;items:=items||jsonb_build_array(jsonb_build_object('user_id',row.user_id,'display_name',row.display_name));next_id:=row.user_id;END LOOP;
  ELSE
   IF NOT public.uc_document_action_allowed(c.organization_id,'read',NULL,NULL)THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
   FOR row IN SELECT d.id,d.current_version_id,r.id review_id FROM public.org_documents d JOIN public.org_document_reviews r ON r.document_id=d.id AND r.version_id=d.current_version_id AND r.organization_id=d.organization_id WHERE d.organization_id=c.organization_id AND d.type IN('admission_rules','edu_relations','paid_services')AND(after_id IS NULL OR d.id>after_id)AND public.uc_admission_local_source(c.organization_id,jsonb_build_object('document_id',d.id,'version_id',d.current_version_id,'review_id',r.id))IS NOT NULL ORDER BY d.id LIMIT lim+1 LOOP counted:=counted+1;IF counted>lim THEN has_more:=true;EXIT;END IF;candidate:=public.uc_admission_local_source(c.organization_id,jsonb_build_object('document_id',row.id,'version_id',row.current_version_id,'review_id',row.review_id));items:=items||jsonb_build_array(candidate-'version_metadata');next_id:=row.id;END LOOP;
  END IF;
  RETURN jsonb_build_object('schema_version',1,'mode',mode,'case_id',c.id,'case_revision',c.revision,'kind',kind,'items',items,'has_more',has_more,'next_after_id',CASE WHEN has_more THEN next_id END);
 END IF;PERFORM public.uc_admission_error('INVALID_INPUT');RETURN NULL;END;$function$

CREATE OR REPLACE FUNCTION public.uc_admission_event(p_case uuid, p_actor uuid, p_event uuid, p_kind text, p_request uuid, p_payload_digest text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.uc_admission_cases;r public.uc_admission_rule_sets;payload jsonb;receipt jsonb;all_evidence jsonb;authority jsonb;BEGIN SELECT * INTO STRICT c FROM public.uc_admission_cases WHERE id=p_case;SELECT * INTO r FROM public.uc_admission_rule_sets WHERE id=c.rule_set_id;authority:=public.uc_admission_authority(c.id,p_actor);
 IF p_kind='record_decision'THEN UPDATE public.uc_admission_cases SET decision=jsonb_set(decision,'{authority_snapshot_hash}',to_jsonb(public.uc_program_hash(authority)))WHERE id=c.id RETURNING * INTO c;END IF;
 SELECT coalesce(jsonb_agg(e.id ORDER BY e.id),'[]')INTO all_evidence FROM public.uc_admission_case_evidence e WHERE e.case_id=c.id AND NOT EXISTS(SELECT 1 FROM public.uc_admission_case_evidence n WHERE n.supersedes_id=e.id AND n.case_id=c.id);
 payload:=jsonb_build_object('reason',p_reason,'program_ref',c.program_ref,'responsible_id',c.responsible_id,'rule_set_id',c.rule_set_id,'rule_set_digest',r.digest,'requirements_digest',public.uc_admission_requirements_digest(c.id),'requirements',c.requirements,'evidence_version_ids',all_evidence,'evidence',public.uc_admission_current_evidence(c.id,p_actor),'tasks',c.tasks,'decision',c.decision,'local_sources',coalesce(r.sources,'[]'),'local_requirements',coalesce(r.definitions,'[]'));
 INSERT INTO public.uc_admission_case_events(id,case_id,organization_id,user_id,case_revision,kind,actor_id,authority_hash,authority_snapshot,payload)VALUES(p_event,c.id,c.organization_id,c.user_id,c.revision,p_kind,p_actor,public.uc_program_hash(authority),authority,payload);
 receipt:=jsonb_build_object('schema_version',1,'request_id',p_request,'case_id',c.id,'revision',c.revision,'event_id',p_event,'kind',p_kind,'payload_digest',p_payload_digest);
 INSERT INTO public.uc_admission_case_requests(actor_id,request_id,case_id,organization_id,user_id,kind,payload_digest,receipt)VALUES(p_actor,p_request,c.id,c.organization_id,c.user_id,p_kind,p_payload_digest,receipt);RETURN receipt;END;$function$

CREATE OR REPLACE FUNCTION public.uc_admission_validate_action(p_command jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE action text:=p_command->>'action';keys text[];k text;x jsonb;BEGIN
 keys:=CASE action WHEN 'initialize'THEN ARRAY['action','group_id','enrollment_id','expected_program_ref','expected_revision']WHEN 'assign_responsible'THEN ARRAY['action','case_id','expected_revision','expected_program_ref','responsible_id','reason']WHEN 'review_local_rules'THEN ARRAY['action','case_id','expected_revision','expected_program_ref','sources','requirements','review_reason']WHEN 'review_requirement'THEN ARRAY['action','case_id','expected_revision','expected_program_ref','requirement_id','expected_requirement_revision','applicability','evidence_version_ids','reason','exception']WHEN 'review_evidence'THEN ARRAY['action','case_id','expected_revision','expected_program_ref','requirement_id','expected_requirement_revision','evidence_version_id','byte_sha256','outcome','reason']WHEN 'record_decision'THEN ARRAY['action','case_id','expected_revision','expected_program_ref','rule_set_id','rule_set_digest','requirements_digest','evidence_version_ids','outcome','reason']ELSE NULL END;
 IF keys IS NULL OR NOT public.uc_admission_shape(p_command,keys)OR NOT public.uc_admission_ref_valid(p_command->'expected_program_ref')OR jsonb_typeof(p_command->'expected_revision')IS DISTINCT FROM 'number'OR p_command->>'expected_revision'!~'^[0-9]{1,16}$'OR(p_command->>'expected_revision')::numeric>9007199254740991 OR(action='initialize')IS DISTINCT FROM(p_command->>'expected_revision'='0')THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
 FOREACH k IN ARRAY keys LOOP IF k~'_id$'AND NOT public.uc_admission_uuid(p_command->k)THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;END LOOP;
 IF p_command?'reason'AND NOT public.uc_admission_text(p_command->'reason')OR p_command?'review_reason'AND NOT public.uc_admission_text(p_command->'review_reason')OR p_command?'expected_requirement_revision'AND(jsonb_typeof(p_command->'expected_requirement_revision')IS DISTINCT FROM 'number'OR p_command->>'expected_requirement_revision'!~'^[1-9][0-9]{0,15}$'OR(p_command->>'expected_requirement_revision')::numeric>9007199254740991)OR p_command?'evidence_version_ids'AND NOT public.uc_admission_ids(p_command->'evidence_version_ids')THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
 IF action='review_requirement'THEN
  IF coalesce(p_command->>'applicability'IN('unknown','applicable','not_applicable'),false)=false THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
  x:=p_command->'exception';IF x<>'null'::jsonb AND(NOT public.uc_admission_shape(x,ARRAY['rule_id','reason','evidence_version_ids'])OR NOT public.uc_admission_uuid(x->'rule_id')OR NOT public.uc_admission_text(x->'reason')OR NOT public.uc_admission_ids(x->'evidence_version_ids',1))THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
 ELSIF action='review_evidence'AND coalesce(p_command->>'outcome'IN('accepted','rejected')AND jsonb_typeof(p_command->'byte_sha256')='string'AND p_command->>'byte_sha256'~'^[a-f0-9]{64}$',false)=false OR action='record_decision'AND coalesce(p_command->>'outcome'IN('needs_information','admitted','not_admitted')AND jsonb_typeof(p_command->'rule_set_digest')='string'AND jsonb_typeof(p_command->'requirements_digest')='string'AND p_command->>'rule_set_digest'~'^[a-f0-9]{64}$'AND p_command->>'requirements_digest'~'^[a-f0-9]{64}$',false)=false THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
END;$function$

CREATE OR REPLACE FUNCTION public.uc_program_issuance_source(p_org uuid, p_group uuid, p_enrollment uuid, p_user uuid, p_course uuid)
 RETURNS group_program_enrollment_snapshots
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.group_program_enrollment_snapshots;b public.group_program_bindings;
BEGIN
 IF p_group IS NULL OR p_enrollment IS NULL OR NOT coalesce(public.uc_document_has_action(p_org,'issue') AND public.uc_document_record_scope(p_org,p_group,p_enrollment,p_user,p_course),false)
 THEN RAISE EXCEPTION 'exact_program_issuance_scope_required' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('uc_program_roster:'||p_group::text,0));
 PERFORM 1 FROM public.student_groups WHERE id=p_group AND organization_id=p_org AND course_id=p_course FOR SHARE;
 SELECT * INTO b FROM public.group_program_bindings WHERE group_id=p_group AND organization_id=p_org AND course_id=p_course FOR SHARE;
 SELECT * INTO s FROM public.group_program_enrollment_snapshots WHERE group_id=p_group AND enrollment_id=p_enrollment AND organization_id=p_org AND user_id=p_user AND course_id=p_course
 AND binding_id=b.id AND binding_revision=b.revision AND version_id=b.version_id AND snapshot_hash=b.snapshot_hash;
 IF NOT FOUND OR NOT public.uc_program_file_proof(p_org,(s.program_snapshot->>'file_version_id')::uuid)
 THEN RAISE EXCEPTION 'confirmed_program_issuance_snapshot_required' USING ERRCODE='22023'; END IF;
 RETURN s;
END;$function$

CREATE OR REPLACE FUNCTION public.account_deletion_erase_data(p_request_id uuid, p_receipt_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'storage'
AS $function$
DECLARE j public.account_deletion_jobs%ROWTYPE; u uuid; r record; v_org uuid; current_snapshot jsonb;
BEGIN
 SELECT * INTO j FROM public.account_deletion_jobs WHERE id=p_request_id AND receipt_hash=p_receipt_hash FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('code','INVALID_RECEIPT'); END IF;
 IF j.consent_version IS DISTINCT FROM 'full-personal-data-v1' THEN RETURN jsonb_build_object('code','CONSENT_REQUIRED'); END IF;
 IF j.state='deleted' THEN RETURN jsonb_build_object('erased',true); END IF;
 IF j.state<>'cleanup_pending' THEN RETURN jsonb_build_object('code','NOT_CONFIRMED'); END IF;
 u:=j.user_id;
 PERFORM pg_advisory_xact_lock(hashtextextended(u::text,42007));
 IF jsonb_array_length(public.account_deletion_files(u))>0 OR EXISTS(SELECT 1 FROM storage.objects o JOIN jsonb_array_elements(j.files) f ON f->>'bucket'=o.bucket_id AND f->>'path'=o.name) THEN RETURN jsonb_build_object('code','DELETION_UNAVAILABLE'); END IF;
 current_snapshot:=public.account_deletion_snapshot(u);
 IF jsonb_array_length(current_snapshot->'blockers')>0 THEN RETURN jsonb_build_object('code','PLAN_CHANGED'); END IF;
 -- Delete the enrollment before lesson progress: the live progress trigger
 -- then has no enrollment to reset. CSZ/issued/shared cases failed in preview.
 PERFORM set_config('sintagma.account_deletion_erase_user',u::text,true);
 PERFORM public.uc_erase_group_education_facts(u);
 PERFORM public.uc_erase_admission_cases(u);
 PERFORM public.uc_erase_identification_data(u);
 DELETE FROM public.audit_logs WHERE entity_id=u::text OR (entity_type='enrollment' AND entity_id IN(SELECT id::text FROM public.enrollments WHERE user_id=u));
 UPDATE public.audit_logs SET user_id='00000000-0000-0000-0000-000000000000',user_name=NULL,ip_address=NULL,user_agent=NULL WHERE user_id=u;
 UPDATE public.role_audit_log SET performed_by=NULL,performed_by_name=NULL,details=CASE WHEN details->>'from_user_id'=u::text THEN details-'from_user_id' ELSE details END WHERE performed_by=u AND target_user_id IS DISTINCT FROM u;
 UPDATE public.student_deletion_log SET deleted_by=NULL,deleted_by_name=NULL,deleted_by_email=NULL WHERE deleted_by=u AND student_id IS DISTINCT FROM u;
 DELETE FROM public.final_test_photo_challenges WHERE user_id=u;
 DELETE FROM public.test_attempts WHERE user_id=u;
 DELETE FROM public.test_attempt_start_requests WHERE user_id=u;
 DELETE FROM public.test_attempt_sessions WHERE user_id=u;
 DELETE FROM public.homework_submissions WHERE student_id=u;
 DELETE FROM public.journal_entries WHERE user_id=u;
 DELETE FROM public.group_class_journal_marks WHERE user_id=u;
 DELETE FROM public.training_plans WHERE user_id=u;
 DELETE FROM public.student_group_memberships WHERE user_id=u;
 DELETE FROM public.student_roster_removals WHERE user_id=u;
 DELETE FROM public.enrollments WHERE user_id=u;
 DELETE FROM public.lesson_progress WHERE user_id=u;
 -- on_enrollment_delete inserts an event; remove it after that trigger.
 DELETE FROM public.enrollment_history WHERE user_id=u;
 DELETE FROM public.organization_monthly_student_assignments WHERE user_id=u;
 DELETE FROM public.organization_monthly_training_completions WHERE user_id=u;
 DELETE FROM public.student_deletion_log WHERE student_id=u;
 DELETE FROM public.support_messages WHERE conversation_id IN (SELECT id FROM public.support_conversations WHERE user_id=u) OR sender_user_id=u;
 DELETE FROM public.support_conversations WHERE user_id=u;
 DELETE FROM public.document_signatures WHERE (sender_user_id=u OR recipient_user_id=u) AND signed_at IS NULL AND sender_signed_at IS NULL AND status<>'signed';
 DELETE FROM public.consent_documents WHERE student_user_id=u;
 DELETE FROM public.org_contracts WHERE student_user_id=u AND approved_at IS NULL AND signed_at IS NULL AND status IN ('draft','cancelled');
 FOR r IN SELECT * FROM (VALUES
  ('admin_org_messages','sender_user_id'),
  ('admin_staff','user_id'),
  ('ai_prompt_templates','user_id'),
  ('ai_tutor_sessions','user_id'),
  ('ai_usage_log','user_id'),
  ('call_log_listens','listener_user_id'),
  ('chat_group_members','user_id'),
  ('chat_group_messages','sender_user_id'),
  ('chat_messages','user_id'),
  ('chat_notification_settings','user_id'),
  ('client_error_logs','user_id'),
  ('company_staff','user_id'),
  ('course_access_log','user_id'),
  ('course_reminders','user_id'),
  ('course_requests','user_id'),
  ('course_review_grants','user_id'),
  ('data_subject_requests','user_id'),
  ('exolve_sip_accounts','user_id'),
  ('final_test_photo_challenges','user_id'),
  ('module_access_overrides','user_id'),
  ('notification_preferences','user_id'),
  ('org_general_messages','sender_user_id'),
  ('org_notifications','user_id'),
  ('org_staff','user_id'),
  ('org_student_messages','sender_user_id'),
  ('org_student_messages','student_user_id'),
  ('organization_offer_acceptances','user_id'),
  ('partner_applications','user_id'),
  ('pending_enrollments','user_id'),
  ('pep_agreements','user_id'),
  ('pipeline_runs','user_id'),
  ('registration_attempts','user_id'),
  ('student_consents','user_id'),
  ('student_frdo_data','user_id'),
  ('student_identity_documents','user_id'),
  ('student_login_history','user_id'),
  ('student_login_tokens','user_id'),
  ('student_notifications','user_id'),
  ('support_requests','user_id'),
  ('testimonials','user_id'),
  ('user_achievements','user_id'),
  ('video_identifications','user_id'),
  ('webinar_participants','user_id')
 ) x(t,c) LOOP
  EXECUTE format('DELETE FROM public.%I WHERE %I=$1',r.t,r.c) USING u;
 END LOOP;
 -- Nullable author references are attribution, not ownership of client data.
 FOR r IN SELECT * FROM (VALUES
  ('admin_generated_documents','created_by'),
  ('ai_settings','updated_by'),
  ('app_settings','updated_by'),
  ('company_documents','uploaded_by'),
  ('consent_documents','created_by'),
  ('course_review_grants','revoked_by'),
  ('enrollment_history','performed_by'),
  ('exolve_sip_accounts','created_by'),
  ('landing_content','updated_by'),
  ('marketplace_settings','updated_by'),
  ('organization_comments','created_by'),
  ('organization_reminders','created_by'),
  ('platform_announcements','created_by'),
  ('sales_tasks','assigned_user_id'),
  ('skillspace_import_jobs','created_by'),
  ('staff_invitations','accepted_user_id'),
  ('student_login_tokens','created_by'),
  ('video_identifications','verified_by')
 ) x(t,c) LOOP
  EXECUTE format('UPDATE public.%I SET %I=NULL WHERE %I=$1',r.t,r.c,r.c) USING u;
 END LOOP;
 DELETE FROM public.user_roles WHERE user_id=u;
 DELETE FROM public.profiles WHERE user_id=u;
 -- org_staff DELETE creates a role-audit event: clear it after all staff/profile
 -- triggers; never leave the target UUID hidden in its own account history.
 DELETE FROM public.role_audit_log WHERE target_user_id=u;
 DELETE FROM public.audit_logs WHERE entity_id=u::text;
 IF (j.snapshot->>'emptyOrganization')::boolean THEN
  v_org:=(j.snapshot->>'organizationId')::uuid;
  -- Recheck under the organization lock; a concurrent invitation/registration
  -- must never be swept into this operation.
  PERFORM 1 FROM public.organizations WHERE id=v_org FOR UPDATE;
  IF EXISTS(SELECT 1 FROM public.profiles WHERE organization_id=v_org AND user_id<>u) OR EXISTS(SELECT 1 FROM public.org_staff WHERE organization_id=v_org) THEN RAISE EXCEPTION 'Organization changed during deletion'; END IF;
  DELETE FROM public.organizations WHERE id=v_org;
 END IF;
 DELETE FROM public.uc_identification_write_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND kind IN('subject_erase','reviewer_erase') AND user_id=u;
 PERFORM public.uc_learning_erase_user(u);
 PERFORM public.uc_custom_journal_erase_user(u);
 PERFORM public.uc_session_erase_user(u);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(public.account_deletion_personal_row_counts(u)) n WHERE (n->>'count')::bigint>0) THEN RAISE EXCEPTION 'Personal data erasure is incomplete'; END IF;
 UPDATE public.account_deletion_jobs SET data_erased=true WHERE id=j.id;
 RETURN jsonb_build_object('erased',true);
END;$function$

CREATE OR REPLACE FUNCTION public.uc_document_row_action_allowed(p_table text, p_row jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_org uuid; v_enrollment uuid; v_group uuid; v_user uuid; v_action text:='write';
BEGIN
 v_org:=nullif(p_row->>'organization_id','')::uuid;
 v_enrollment:=nullif(p_row->>'enrollment_id','')::uuid;
 v_group:=nullif(p_row->>'group_id','')::uuid;
 v_user:=nullif(p_row->>'user_id','')::uuid;
 IF p_table IN ('education_document_records','document_issuance_log') THEN v_action:='issue';
 ELSIF p_table='group_documents' AND p_row->>'doc_status'='final' AND p_row->>'doc_type' IN ('enrollment_order','expulsion_order') THEN v_action:='issue'; END IF;
 IF p_table='company_documents' THEN SELECT organization_id INTO v_org FROM public.companies WHERE id=(p_row->>'company_id')::uuid;
 ELSIF p_table='org_contracts' THEN
  RETURN public.uc_document_has_action(v_org,'write') AND public.uc_document_contract_scope(v_org,
   nullif(p_row->>'student_group_id','')::uuid,nullif(p_row->>'student_user_id','')::uuid,nullif(p_row->>'company_id','')::uuid,p_row->'students');
 ELSIF p_table='program_training_plans' THEN SELECT organization_id INTO v_org FROM public.courses WHERE id=(p_row->>'course_id')::uuid;
 ELSIF p_table='student_documents' THEN SELECT c.organization_id INTO v_org FROM public.enrollments e JOIN public.courses c ON c.id=e.course_id WHERE e.id=v_enrollment;
 ELSIF p_table='student_identity_documents' THEN
  RETURN public.account_deletion_access_allowed() AND (
   v_user=auth.uid() AND public.uc_document_student_in_org(v_user,v_org)
   OR public.uc_document_has_action(v_org,'write') AND public.uc_document_student_scope_allowed(v_org,v_user));
 END IF;
 IF p_table IN ('education_document_records','document_issuance_log') THEN
  RETURN public.uc_document_has_action(v_org,'issue') AND public.uc_document_record_scope(v_org,v_group,v_enrollment,v_user,nullif(p_row->>'course_id','')::uuid);
 ELSIF p_table='group_documents' THEN
  RETURN public.uc_document_has_action(v_org,v_action) AND public.uc_document_record_scope(v_org,v_group,NULL,nullif(p_row->>'student_user_id','')::uuid,NULL);
 END IF;
 RETURN public.uc_document_action_allowed(v_org,v_action,v_group,v_enrollment);
END;$function$

CREATE OR REPLACE FUNCTION public.uc_guard_document_actions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF TG_TABLE_NAME='group_documents' AND TG_OP='UPDATE' AND
  (to_jsonb(NEW)-ARRAY['is_current','updated_at'])=(to_jsonb(OLD)-ARRAY['is_current','updated_at']) THEN
  IF NOT public.uc_document_action_allowed(OLD.organization_id,'write',OLD.group_id,NULL) THEN
   RAISE EXCEPTION 'Document version scope denied' USING ERRCODE='42501'; END IF;
  RETURN NEW;
 END IF;
 IF TG_OP IN ('UPDATE','DELETE') AND NOT public.uc_document_row_action_allowed(TG_TABLE_NAME,to_jsonb(OLD)) THEN
  RAISE EXCEPTION 'Document action or group scope denied' USING ERRCODE='42501'; END IF;
 IF TG_OP IN ('INSERT','UPDATE') AND NOT public.uc_document_row_action_allowed(TG_TABLE_NAME,to_jsonb(NEW)) THEN
  RAISE EXCEPTION 'Document action or group scope denied' USING ERRCODE='42501'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END;$function$

CREATE OR REPLACE FUNCTION public.uc_guard_program_issuance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.group_program_enrollment_snapshots;f jsonb;t text;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF public.uc_program_issuance_lifecycle(to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW; END IF;
  IF EXISTS(SELECT 1 FROM public.education_document_program_sources WHERE record_id=OLD.id) THEN RAISE EXCEPTION 'issued_program_source_is_immutable' USING ERRCODE='42501'; END IF;
 END IF;
 s:=public.uc_program_issuance_source(NEW.organization_id,NEW.group_id,NEW.enrollment_id,NEW.user_id,NEW.course_id);
 f:=s.program_snapshot->'facts';t:=CASE f->>'program_type' WHEN 'dpo_upskilling' THEN 'certificate' WHEN 'dpo_retraining' THEN 'diploma' WHEN 'professional_training' THEN 'qualification' END;
 IF t IS NULL OR NEW.document_type IS DISTINCT FROM t THEN RAISE EXCEPTION 'education_document_type_program_mismatch' USING ERRCODE='22023'; END IF;
 -- These fields are server-derived; neither a live course title nor a caller's export row is authoritative.
 NEW.specialty_name:=f->>'full_title';NEW.qualification_name:=coalesce(f->>'qualification',f->>'profession');
 RETURN NEW;
END;$function$

CREATE OR REPLACE FUNCTION public.uc_record_program_issuance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.group_program_enrollment_snapshots;
BEGIN
 IF TG_OP='UPDATE' AND public.uc_program_issuance_lifecycle(to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW; END IF;
 s:=public.uc_program_issuance_source(NEW.organization_id,NEW.group_id,NEW.enrollment_id,NEW.user_id,NEW.course_id);
 INSERT INTO public.education_document_program_sources(record_id,organization_id,enrollment_snapshot_id,snapshot,recorded_by)
 VALUES(NEW.id,NEW.organization_id,s.id,to_jsonb(s),auth.uid());RETURN NEW;
END;$function$

CREATE OR REPLACE FUNCTION public.uc_scoped_journal_erase_user(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('sintagma.account_deletion_erase_user',true) IS DISTINCT FROM p_user::text OR NOT EXISTS(SELECT 1 FROM public.account_deletion_revocations rev WHERE rev.user_id=p_user) THEN PERFORM public.uc_custom_journal_error('ACCESS_DENIED');END IF;
 PERFORM public.uc_copy_registry_erase_user(p_user);
 PERFORM public.uc_document_registry_erase_user(p_user);
 -- Every copied personal export is invalidated, never silently re-rendered under an old hash.
 DELETE FROM public.uc_scoped_journal_exports e WHERE e.recorded_by=p_user OR p_user=ANY(e.participant_ids);
 DELETE FROM public.uc_scoped_journal_requests request_row WHERE request_row.actor_id=p_user OR p_user=ANY(request_row.participant_ids);
 DELETE FROM public.uc_scoped_journal_history h WHERE h.subject_user_id=p_user;
 DELETE FROM public.uc_scoped_journal_records r WHERE r.subject_user_id=p_user;
 -- Conservatively redact an entire attributed copy, including nonpersonal-author text.
 -- No universal discovery of undeclared third-party personal data in free text is claimed.
 UPDATE public.uc_scoped_journal_history SET recorded_by=NULL,subject_user_id=NULL,subject_label=NULL,field_values='{}',source='{"kind":"none"}',reason='',participant_ids='{}',redacted=true
  WHERE recorded_by=p_user OR p_user=ANY(participant_ids);
 UPDATE public.uc_scoped_journal_records SET recorded_by=NULL,created_by=NULL,subject_user_id=NULL,subject_label=NULL,field_values='{}',source='{"kind":"none"}',participant_ids='{}',redacted=true
  WHERE recorded_by=p_user OR created_by=p_user OR p_user=ANY(participant_ids);
 UPDATE public.uc_scoped_journal_contexts SET created_by=NULL WHERE created_by=p_user;
 IF public.uc_scoped_journal_personal_counts(p_user)<>'[]'::jsonb THEN PERFORM public.uc_custom_journal_error('DEPENDENCY_UNAVAILABLE');END IF;
END;$function$

CREATE OR REPLACE FUNCTION public.uc_admission_derive(p_case uuid, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.uc_admission_cases;q jsonb;reqs jsonb:='[]';derived_tasks jsonb:='[]';eids jsonb;ev jsonb;state text;kind text;k text;tid uuid;reason text;BEGIN SELECT * INTO STRICT c FROM public.uc_admission_cases WHERE id=p_case;
 FOR q IN SELECT x FROM jsonb_array_elements(c.requirements)x LOOP
  SELECT coalesce(jsonb_agg(e.id ORDER BY e.id),'[]')INTO eids FROM public.uc_admission_case_evidence e WHERE e.case_id=c.id AND e.requirement_id=(q->>'id')::uuid AND NOT EXISTS(SELECT 1 FROM public.uc_admission_case_evidence n WHERE n.case_id=c.id AND n.supersedes_id=e.id);
  state:=CASE q->>'applicability'WHEN 'unknown'THEN 'unknown'WHEN 'not_applicable'THEN 'satisfied'ELSE 'missing'END;
  IF q->>'applicability'='applicable'AND jsonb_array_length(eids)>0 THEN
   state:='satisfied';FOR ev IN SELECT public.uc_admission_evidence_dto((x#>>'{}')::uuid,p_actor)FROM jsonb_array_elements(eids)x LOOP
    IF ev->>'availability'<>'available'THEN state:='unreadable';EXIT;ELSIF ev->>'review'<>'accepted'THEN state:='unreviewed';END IF;END LOOP;
  END IF;
  IF q->>'applicability'='applicable'AND c.reviews->'requirements'->(q->>'id')->'exception'IS NOT NULL AND c.reviews->'requirements'->(q->>'id')->'exception'<>'null'::jsonb THEN
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c.reviews->'requirements'->(q->>'id')->'exception'->'evidence_version_ids')x WHERE public.uc_admission_evidence_dto((x#>>'{}')::uuid,p_actor)->>'review'<>'accepted'OR public.uc_admission_evidence_dto((x#>>'{}')::uuid,p_actor)->>'availability'<>'available')THEN state:='exception_recorded';ELSE state:='exception_pending';END IF;
  END IF;
  q:=q||jsonb_build_object('evidence_version_ids',eids,'current_state',state,'public_next_action',CASE WHEN state IN('satisfied','exception_recorded')THEN NULL WHEN state='missing'THEN 'Добавьте читаемые сведения'ELSE 'Обратитесь к ответственному сотруднику'END);reqs:=reqs||jsonb_build_array(q);
  IF state NOT IN('satisfied','exception_recorded')THEN
   kind:=CASE state WHEN 'unknown'THEN 'review_applicability'WHEN 'missing'THEN 'supply_evidence'WHEN 'unreadable'THEN 'recheck_source'WHEN 'exception_pending'THEN 'review_exception'ELSE 'review_evidence'END;
   k:=public.uc_program_hash(jsonb_build_array(c.id,q->'id',q->'revision',q->'rule_set_digest',eids,kind));
   SELECT(t->>'id')::uuid INTO tid FROM jsonb_array_elements(c.tasks)t WHERE t->>'key'=k;
   derived_tasks:=derived_tasks||jsonb_build_array(jsonb_build_object('id',coalesce(tid,(substr(k,1,8)||'-'||substr(k,9,4)||'-'||substr(k,13,4)||'-'||substr(k,17,4)||'-'||substr(k,21,12))::uuid),'key',k,'requirement_id',q->'id','kind',kind,'status','open','assignee_id',c.responsible_id,'public_label',CASE kind WHEN 'supply_evidence'THEN 'Добавьте сведения в документы ученика'WHEN 'review_applicability'THEN 'Требуется проверка применимости'ELSE 'Требуется проверка ответственным'END,'deadline',jsonb_build_object('kind','not_set','date',NULL,'rule_id',NULL),'reason',NULL));
  END IF;
 END LOOP;
 IF c.program_ref IS DISTINCT FROM public.uc_admission_program(c.organization_id,c.user_id,c.group_id,c.enrollment_id)OR(c.rule_set_id IS NOT NULL AND NOT coalesce(public.uc_admission_rules_current(c.id),false))THEN
  kind:=CASE WHEN c.program_ref IS DISTINCT FROM public.uc_admission_program(c.organization_id,c.user_id,c.group_id,c.enrollment_id)THEN 'recheck_programme'ELSE 'recheck_source'END;
  k:=public.uc_program_hash(jsonb_build_array(c.id,c.program_ref,c.rule_set_id,kind));
  derived_tasks:=derived_tasks||jsonb_build_array(jsonb_build_object('id',(substr(k,1,8)||'-'||substr(k,9,4)||'-'||substr(k,13,4)||'-'||substr(k,17,4)||'-'||substr(k,21,12))::uuid,'key',k,'requirement_id',NULL,'kind',kind,'status','open','assignee_id',c.responsible_id,'public_label','Требуется повторная проверка источника','deadline',jsonb_build_object('kind','not_set','date',NULL,'rule_id',NULL),'reason',NULL));
 END IF;
 IF jsonb_array_length(reqs)>50 OR jsonb_array_length(derived_tasks)>50 OR jsonb_array_length(public.uc_admission_current_evidence(c.id,p_actor))>100 THEN PERFORM public.uc_admission_error('LIMIT_REACHED');END IF;
 RETURN jsonb_build_object('requirements',reqs,'tasks',derived_tasks);
END;$function$

CREATE OR REPLACE FUNCTION public.uc_admission_lock(p_actor uuid, p_org uuid, p_user uuid, p_group uuid, p_enrollment uuid, p_responsible uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE u uuid;BEGIN
 IF current_setting('transaction_isolation')<>'read committed'THEN RAISE EXCEPTION 'ADMISSION_READ_COMMITTED_REQUIRED' USING ERRCODE='25000';END IF;
 FOR u IN SELECT DISTINCT x FROM unnest(ARRAY[p_actor,p_user,p_responsible])x WHERE x IS NOT NULL ORDER BY x LOOP PERFORM pg_advisory_xact_lock(hashtextextended(u::text,42007));END LOOP;
 IF NOT public.uc_admission_staff_allowed(p_actor,p_org,p_user,p_group,p_enrollment,true)OR NOT public.uc_admission_staff_allowed(p_actor,p_org,p_user,p_group,p_enrollment,false)THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_org::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('uc_program_roster:'||p_group::text,0));
 -- Current scope and revocation after both fences, before shared row locks.
 IF NOT public.uc_admission_staff_allowed(p_actor,p_org,p_user,p_group,p_enrollment,true)OR NOT public.uc_admission_staff_allowed(p_actor,p_org,p_user,p_group,p_enrollment,false)OR(p_responsible IS NOT NULL AND NOT public.uc_admission_staff_allowed(p_responsible,p_org,p_user,p_group,p_enrollment,true))THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
END;$function$

CREATE OR REPLACE FUNCTION public.uc_admission_state(p_case uuid, p_actor uuid, p_learner boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.uc_admission_cases;d jsonb;tasks jsonb;changed boolean;derived jsonb;BEGIN SELECT * INTO c FROM public.uc_admission_cases WHERE id=p_case;
 IF c.id IS NULL OR NOT public.uc_admission_can_read(p_actor,c.organization_id,c.user_id,c.group_id,c.enrollment_id)THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
 derived:=public.uc_admission_derive(c.id,p_actor);changed:=c.program_ref IS DISTINCT FROM public.uc_admission_program(c.organization_id,c.user_id,c.group_id,c.enrollment_id)OR NOT coalesce(public.uc_admission_rules_current(c.id),false)OR derived->'requirements'IS DISTINCT FROM c.requirements;
 d:=c.decision;IF d IS NOT NULL THEN d:=jsonb_set(d,'{later_review_required}',to_jsonb(changed OR coalesce((d->>'case_revision')::bigint<c.revision,false)));END IF;
 IF p_learner THEN
 IF p_actor<>c.user_id THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',t->'id','public_label',t->'public_label','next_action',CASE WHEN t->>'kind'='supply_evidence'THEN 'upload_own_attachment'ELSE 'contact_staff'END,'status',t->'status')),'[]')INTO tasks FROM jsonb_array_elements(derived->'tasks')t;
 RETURN jsonb_build_object('id',c.id,'scope',public.uc_admission_scope(c.id),'revision',c.revision,'program_title',c.program_title,'outcome',coalesce(d->>'outcome','not_reviewed'),'outcome_recorded_at',d->'recorded_at','later_review_required',d IS NOT NULL AND(d->>'later_review_required')::boolean,'tasks',tasks);END IF;
 IF NOT public.uc_admission_staff_allowed(p_actor,c.organization_id,c.user_id,c.group_id,c.enrollment_id,false)THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
 RETURN jsonb_build_object('id',c.id,'scope',public.uc_admission_scope(c.id),'revision',c.revision,'program_ref',c.program_ref,'program_title',c.program_title,'program_type',c.program_type,'responsible_id',c.responsible_id,'rule_set_id',c.rule_set_id,'requirements',derived->'requirements',
 'evidence',public.uc_admission_current_evidence(c.id,p_actor),'tasks',derived->'tasks','decision',d,'prerequisites',public.uc_admission_prerequisites(c.organization_id,c.user_id,c.group_id,c.enrollment_id,NOT coalesce(public.uc_admission_rules_current(c.id),false)),
 'capabilities',public.uc_admission_capabilities(p_actor,c.organization_id,c.user_id,c.group_id,c.enrollment_id,c.id),'rule_set_digest',(SELECT digest FROM public.uc_admission_rule_sets WHERE id=c.rule_set_id),'requirements_digest',public.uc_program_hash(jsonb_build_object('requirements',derived->'requirements','rule_set_id',c.rule_set_id,'program_ref',c.program_ref)));END;$function$

CREATE OR REPLACE FUNCTION public.uc_document_record_scope(p_org uuid, p_group uuid, p_enrollment uuid, p_user uuid, p_course uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF p_enrollment IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.enrollments e JOIN public.courses c ON c.id=e.course_id
  WHERE e.id=p_enrollment AND c.organization_id=p_org AND (p_user IS NULL OR e.user_id=p_user) AND (p_course IS NULL OR e.course_id=p_course)) THEN RETURN false; END IF;
 IF p_course IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.courses c WHERE c.id=p_course AND c.organization_id=p_org) THEN RETURN false; END IF;
 IF p_group IS NOT NULL AND p_course IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.student_groups g WHERE g.id=p_group AND g.organization_id=p_org AND g.course_id=p_course) THEN RETURN false; END IF;
 IF p_group IS NOT NULL AND p_user IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.student_group_memberships_effective m
  WHERE m.organization_id=p_org AND m.group_id=p_group AND m.user_id=p_user) THEN RETURN false; END IF;
 RETURN public.uc_document_scope_allowed(p_org,p_group,p_enrollment);
END;$function$

CREATE OR REPLACE FUNCTION public.uc_document_scope_allowed(p_org uuid, p_group uuid DEFAULT NULL::uuid, p_enrollment uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_user uuid;v_course uuid;v_group_course uuid;
BEGIN
 IF auth.uid() IS NULL OR NOT public.account_deletion_access_allowed() OR p_org IS NULL
 OR NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=p_org) THEN RETURN false; END IF;
 IF p_group IS NOT NULL THEN
  SELECT course_id INTO v_group_course FROM public.student_groups WHERE id=p_group AND organization_id=p_org;
  IF NOT FOUND THEN RETURN false; END IF;
  IF v_group_course IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.courses c WHERE c.id=v_group_course AND c.organization_id=p_org) THEN RETURN false; END IF;
 END IF;
 IF p_enrollment IS NOT NULL THEN
  SELECT e.user_id,e.course_id INTO v_user,v_course FROM public.enrollments e JOIN public.courses c ON c.id=e.course_id
   WHERE e.id=p_enrollment AND c.organization_id=p_org;
  IF NOT FOUND THEN RETURN false; END IF;
  IF p_group IS NOT NULL AND (v_group_course IS DISTINCT FROM v_course OR NOT EXISTS(
   SELECT 1 FROM public.student_group_memberships_effective m WHERE m.organization_id=p_org AND m.group_id=p_group AND m.user_id=v_user))
  THEN RETURN false; END IF;
 END IF;
 IF public.has_role(auth.uid(),'admin'::public.app_role) OR public.is_org_owner(auth.uid(),p_org) THEN RETURN true; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.org_staff s WHERE s.organization_id=p_org AND s.user_id=auth.uid()
   AND (s.expires_at IS NULL OR s.expires_at>now())) THEN RETURN false; END IF;
 IF NOT public.uc_document_teacher_limited(p_org) THEN RETURN true; END IF;
 RETURN EXISTS(SELECT 1 FROM public.org_staff s JOIN public.org_staff_document_groups a ON a.staff_id=s.id AND a.organization_id=s.organization_id
  JOIN public.student_groups g ON g.id=a.group_id AND g.organization_id=a.organization_id
  WHERE s.organization_id=p_org AND s.user_id=auth.uid() AND (s.expires_at IS NULL OR s.expires_at>now())
   AND (p_group IS NULL OR g.id=p_group)
   AND (p_enrollment IS NULL OR (g.course_id=v_course AND EXISTS(SELECT 1 FROM public.student_group_memberships_effective m
     WHERE m.organization_id=p_org AND m.group_id=g.id AND m.user_id=v_user)))
   AND (p_group IS NOT NULL OR p_enrollment IS NOT NULL));
END;$function$

CREATE OR REPLACE FUNCTION public._test_attempt_limits(p_lesson_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_day_start timestamptz;
  v_reset timestamptz;
  v_total integer;
  v_today integer;
  v_max integer;
  v_daily integer;
BEGIN
  v_day_start := date_trunc('day', v_now AT TIME ZONE 'Europe/Moscow') AT TIME ZONE 'Europe/Moscow';
  v_reset := (date_trunc('day', v_now AT TIME ZONE 'Europe/Moscow') + interval '1 day') AT TIME ZONE 'Europe/Moscow';
  SELECT test_max_attempts, test_max_attempts_per_day INTO v_max, v_daily
    FROM public.lessons WHERE id = p_lesson_id;
  SELECT count(*)::integer, count(*) FILTER (WHERE attempt_time >= v_day_start AND attempt_time < v_reset)::integer
    INTO v_total, v_today
  FROM (
    SELECT started_at AS attempt_time FROM public.test_attempt_sessions
      WHERE user_id = p_user_id AND lesson_id = p_lesson_id
    UNION ALL
    SELECT completed_at FROM public.test_attempts
      WHERE user_id = p_user_id AND lesson_id = p_lesson_id AND session_id IS NULL
  ) attempts;
  RETURN jsonb_build_object('maxAttempts', v_max, 'maxAttemptsPerDay', v_daily,
    'attemptsUsed', v_total, 'attemptsUsedToday', v_today,
    'dayTimezone', 'Europe/Moscow', 'resetAt', v_reset);
END;
$function$

CREATE OR REPLACE FUNCTION public._test_grade_payload(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  a public.test_attempts%ROWTYPE;
  s public.test_attempt_sessions%ROWTYPE;
  v_correct jsonb := '{}'::jsonb;
  v_explanations jsonb := '{}'::jsonb;
  v_show boolean;
BEGIN
  SELECT * INTO STRICT s FROM public.test_attempt_sessions WHERE id = p_session_id;
  SELECT * INTO STRICT a FROM public.test_attempts WHERE session_id = p_session_id;
  SELECT s.show_answers AND l.test_show_answers INTO v_show FROM public.lessons l WHERE l.id = s.lesson_id;
  IF v_show THEN
    SELECT coalesce(jsonb_object_agg(q->>'id', q->'correct_answer'), '{}'::jsonb),
      coalesce(jsonb_object_agg(q->>'id', q->'explanation'), '{}'::jsonb)
      INTO v_correct, v_explanations FROM jsonb_array_elements(s.questions_snapshot) q;
  END IF;
  RETURN public._test_attempt_limits(s.lesson_id, s.user_id) || jsonb_build_object(
    'attemptId', s.id, 'score', a.score, 'maxScore', a.max_score,
    'scorePercent', CASE WHEN a.max_score > 0 THEN round(a.score * 100.0 / a.max_score)::integer ELSE 0 END,
    'passed', a.passed, 'passingScore', a.passing_score, 'showAnswers', v_show,
    'correctAnswers', v_correct, 'explanations', v_explanations);
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_complete_enrollment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.progress >= 100 AND NEW.status != 'completed' THEN
    NEW.status := 'completed';
    NEW.completed_at := now();
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_course_assignment(p_enrollment_id uuid, p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '3s'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_enrollment public.enrollments%ROWTYPE;
  v_deleted_id uuid;
  v_relation record;
  v_has_records boolean;
BEGIN
  IF v_actor IS NULL OR p_organization_id IS NULL OR NOT coalesce((
    public.has_role(v_actor, 'admin'::public.app_role)
    OR public.is_org_owner(v_actor, p_organization_id)
    OR (
      EXISTS (SELECT 1 FROM public.org_staff os
        WHERE os.user_id = v_actor AND os.organization_id = p_organization_id
          AND (os.expires_at IS NULL OR os.expires_at > now()))
      AND public.has_org_staff_permission(v_actor, p_organization_id, 'students.write')
    )
  ), false) THEN
    RAISE EXCEPTION 'assignment_forbidden' USING ERRCODE = '42501';
  END IF;
  -- Guards must observe writes that completed while waiting for the locks.
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'assignment_requires_read_committed' USING ERRCODE = '25000';
  END IF;
  -- These learning tables have no enrollment FK. Briefly prevent concurrent
  -- inserts/updates while checking them; a busy learner causes a retry, not loss.
  LOCK TABLE public.lessons, public.lesson_progress, public.test_attempts IN SHARE MODE;
  FOR v_relation IN
    SELECT c.oid::regclass AS relation FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public' AND c.relname IN (
        'test_attempt_sessions', 'homework_submissions', 'course_access_log', 'education_document_records'
      ) AND c.relkind IN ('r', 'p') ORDER BY c.oid
  LOOP
    EXECUTE format('LOCK TABLE %s IN SHARE MODE', v_relation.relation);
  END LOOP;
  -- Block concurrent changes to the incoming FK set while inspecting it.
  LOCK TABLE public.enrollments IN ROW EXCLUSIVE MODE;
  SELECT e.* INTO v_enrollment FROM public.enrollments e
    JOIN public.courses c ON c.id = e.course_id
    JOIN public.profiles p ON p.user_id = e.user_id
    WHERE e.id = p_enrollment_id AND c.organization_id = p_organization_id
      AND p.organization_id = p_organization_id
    FOR UPDATE OF e FOR SHARE OF c, p;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'assignment_not_found' USING ERRCODE = 'P0002';
  END IF;
  -- started_at is the assignment date, populated by DEFAULT now(); it is not
  -- proof that a learner started studying.
  IF coalesce(v_enrollment.progress, 0) <> 0 OR coalesce(v_enrollment.time_spent, 0) <> 0
    OR v_enrollment.status IS DISTINCT FROM 'active' OR v_enrollment.completed_at IS NOT NULL
    OR EXISTS (SELECT 1 FROM public.lesson_progress lp JOIN public.lessons l ON l.id = lp.lesson_id
      WHERE lp.user_id = v_enrollment.user_id AND l.course_id = v_enrollment.course_id)
    OR EXISTS (SELECT 1 FROM public.test_attempts ta JOIN public.lessons l ON l.id = ta.lesson_id
      WHERE ta.user_id = v_enrollment.user_id AND l.course_id = v_enrollment.course_id) THEN
    RAISE EXCEPTION 'assignment_has_learning_history' USING ERRCODE = '23514';
  END IF;
  FOR v_relation IN
    SELECT c.oid::regclass AS relation, c.relname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public' AND c.relname IN ('test_attempt_sessions', 'homework_submissions', 'course_access_log')
        AND c.relkind IN ('r', 'p') ORDER BY c.oid
  LOOP
    IF v_relation.relname = 'test_attempt_sessions' THEN
      EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s r JOIN public.lessons l ON l.id = r.lesson_id WHERE r.user_id = $1 AND l.course_id = $2)', v_relation.relation)
        INTO v_has_records USING v_enrollment.user_id, v_enrollment.course_id;
    ELSIF v_relation.relname = 'homework_submissions' THEN
      EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s WHERE student_id = $1 AND course_id = $2)', v_relation.relation)
        INTO v_has_records USING v_enrollment.user_id, v_enrollment.course_id;
    ELSE
      EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s WHERE user_id = $1 AND course_id = $2)', v_relation.relation)
        INTO v_has_records USING v_enrollment.user_id, v_enrollment.course_id;
    END IF;
    IF v_has_records THEN
      RAISE EXCEPTION 'assignment_has_learning_history' USING ERRCODE = '23514';
    END IF;
  END LOOP;
  -- Also preserve historical documents whose enrollment_id was cleared earlier.
  IF to_regclass('public.education_document_records') IS NOT NULL THEN
    EXECUTE 'SELECT EXISTS (SELECT 1 FROM public.education_document_records WHERE user_id = $1 AND course_id = $2)'
      INTO v_has_records USING v_enrollment.user_id, v_enrollment.course_id;
    IF v_has_records THEN
      RAISE EXCEPTION 'assignment_has_dependent_records' USING ERRCODE = '23514';
    END IF;
  END IF;
  -- Inspect every incoming FK, including SET NULL and future relations. The row
  -- lock prevents a concurrent child insert from passing its FK check.
  FOR v_relation IN
    SELECT con.conkey, con.confkey, ns.nspname, rel.relname, att.attname
      FROM pg_constraint con
      JOIN pg_class rel ON rel.oid = con.conrelid
      JOIN pg_namespace ns ON ns.oid = rel.relnamespace
      LEFT JOIN pg_attribute att ON att.attrelid = con.conrelid AND att.attnum = con.conkey[1]
      WHERE con.contype = 'f' AND con.confrelid = 'public.enrollments'::regclass
  LOOP
    IF cardinality(v_relation.conkey) <> 1 OR cardinality(v_relation.confkey) <> 1
      OR v_relation.confkey[1] <> (SELECT attnum FROM pg_attribute
        WHERE attrelid = 'public.enrollments'::regclass AND attname = 'id') THEN
      RAISE EXCEPTION 'assignment_has_dependent_records' USING ERRCODE = '23514';
    END IF;
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I.%I WHERE %I = $1)',
      v_relation.nspname, v_relation.relname, v_relation.attname)
      INTO v_has_records USING p_enrollment_id;
    IF v_has_records THEN
      RAISE EXCEPTION 'assignment_has_dependent_records' USING ERRCODE = '23514';
    END IF;
  END LOOP;
  DELETE FROM public.enrollments WHERE id = p_enrollment_id RETURNING id INTO v_deleted_id;
  IF v_deleted_id IS DISTINCT FROM p_enrollment_id OR EXISTS (
    SELECT 1 FROM public.enrollments WHERE id = p_enrollment_id
  ) THEN
    RAISE EXCEPTION 'assignment_verification_failed' USING ERRCODE = 'P0001';
  END IF;
  RETURN jsonb_build_object('cancelled', true, 'enrollmentId', v_deleted_id,
    'organizationId', p_organization_id, 'userId', v_enrollment.user_id, 'courseId', v_enrollment.course_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.csz_guard_homework_submission()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_scope boolean; v_lesson public.lessons%ROWTYPE; v_org uuid;
  v_enrollment public.enrollments%ROWTYPE; v_latest public.homework_submissions%ROWTYPE;
BEGIN
  v_scope := (TG_OP<>'INSERT' AND (OLD.course_id=ANY(ARRAY['7630559a-6caf-42e7-97f9-1cd0e4598c39','7e5bc4e6-0629-4186-9745-a821cbe7255a']::uuid[])
    OR EXISTS(SELECT 1 FROM public.lessons WHERE id=OLD.lesson_id AND course_id=ANY(ARRAY['7630559a-6caf-42e7-97f9-1cd0e4598c39','7e5bc4e6-0629-4186-9745-a821cbe7255a']::uuid[]))))
    OR (TG_OP<>'DELETE' AND (NEW.course_id=ANY(ARRAY['7630559a-6caf-42e7-97f9-1cd0e4598c39','7e5bc4e6-0629-4186-9745-a821cbe7255a']::uuid[])
    OR EXISTS(SELECT 1 FROM public.lessons WHERE id=NEW.lesson_id AND course_id=ANY(ARRAY['7630559a-6caf-42e7-97f9-1cd0e4598c39','7e5bc4e6-0629-4186-9745-a821cbe7255a']::uuid[]))));
  IF NOT coalesce(v_scope,false) THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
  IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'S022: READ COMMITTED required' USING ERRCODE='25000'; END IF;
  PERFORM pg_advisory_xact_lock(7630559,178); -- also serializes protected curriculum changes
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'S022: protected homework history cannot be deleted' USING ERRCODE='42501'; END IF;
  IF TG_OP='UPDATE' AND
    (to_jsonb(NEW)-ARRAY['status','score','reviewer_id','reviewer_comment','reviewed_at']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['status','score','reviewer_id','reviewer_comment','reviewed_at']) THEN
    RAISE EXCEPTION 'S022: immutable homework identity/content/order' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_enrollment FROM public.enrollments
    WHERE user_id=NEW.student_id AND course_id=NEW.course_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'S022: enrollment required' USING ERRCODE='42501'; END IF;
  -- These are separate commands AFTER the potentially blocking enrollment SELECT.
  SELECT * INTO v_lesson FROM public.lessons WHERE id=NEW.lesson_id;
  SELECT organization_id INTO v_org FROM public.courses WHERE id=NEW.course_id;
  IF (NEW.course_id IS DISTINCT FROM '7630559a-6caf-42e7-97f9-1cd0e4598c39'::uuid AND NEW.course_id IS DISTINCT FROM '7e5bc4e6-0629-4186-9745-a821cbe7255a'::uuid)
    OR v_lesson.course_id IS DISTINCT FROM NEW.course_id OR v_lesson.type IS DISTINCT FROM 'homework'
    OR NEW.organization_id IS DISTINCT FROM v_org
    OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=NEW.student_id AND organization_id=v_org) THEN
    RAISE EXCEPTION 'S022: invalid homework context' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_latest FROM public.homework_submissions
    WHERE student_id=NEW.student_id AND course_id=NEW.course_id AND lesson_id=NEW.lesson_id
    ORDER BY submitted_at DESC,id DESC LIMIT 1;
  IF TG_OP='INSERT' THEN
    IF auth.uid() IS DISTINCT FROM NEW.student_id OR NOT public.can_access_course_as_learner(NEW.course_id)
      OR v_enrollment.status<>'active' OR NEW.status<>'pending'
      OR NEW.score IS NOT NULL OR NEW.reviewer_id IS NOT NULL OR NEW.reviewer_comment IS NOT NULL OR NEW.reviewed_at IS NOT NULL THEN
      RAISE EXCEPTION 'S022: only own eligible pending submission is allowed' USING ERRCODE='42501';
    END IF;
    IF v_latest.id IS NOT NULL AND v_latest.status NOT IN ('revision','rejected') THEN
      RAISE EXCEPTION 'S022: latest submission does not permit resubmission' USING ERRCODE='23514';
    END IF;
    NEW.submitted_at:=greatest(clock_timestamp(),v_latest.submitted_at+interval '1 microsecond');
    NEW.created_at:=NEW.submitted_at;
  ELSE
    IF auth.uid() IS NULL OR auth.uid()=NEW.student_id OR NOT public.can_access_course(NEW.course_id,'homework.write') THEN
      RAISE EXCEPTION 'S022: homework.write on the actual course required' USING ERRCODE='42501';
    END IF;
    IF v_latest.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'S022: stale homework review' USING ERRCODE='23514'; END IF;
    IF NEW.status NOT IN ('approved','revision','rejected') OR (NEW.score IS NOT NULL AND NEW.score NOT BETWEEN 0 AND 100) THEN
      RAISE EXCEPTION 'S022: invalid review status/score' USING ERRCODE='23514';
    END IF;
    IF OLD.status='approved' AND NEW.status<>'approved' AND
      (v_enrollment.status='completed' OR EXISTS(SELECT 1 FROM public.lesson_progress
        WHERE user_id=NEW.student_id AND lesson_id=NEW.lesson_id AND completed)) THEN
      RAISE EXCEPTION 'S022: staff reset required before withdrawing completed approval' USING ERRCODE='23514';
    END IF;
    NEW.reviewer_id:=auth.uid(); NEW.reviewed_at:=clock_timestamp();
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.csz_guard_lesson_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_scope boolean; v_user uuid; v_lid uuid; v_lesson public.lessons%ROWTYPE;
  v_e public.enrollments%ROWTYPE; v_credit timestamptz; v_staff boolean;
BEGIN
  v_scope := EXISTS(SELECT 1 FROM public.lessons WHERE course_id=ANY(ARRAY['7630559a-6caf-42e7-97f9-1cd0e4598c39','7e5bc4e6-0629-4186-9745-a821cbe7255a']::uuid[])
    AND ((TG_OP<>'INSERT' AND id=OLD.lesson_id) OR (TG_OP<>'DELETE' AND id=NEW.lesson_id)));
  IF NOT v_scope THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
  IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'S022: READ COMMITTED required' USING ERRCODE='25000'; END IF;
  PERFORM pg_advisory_xact_lock(7630559,178);
  IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.lesson_id IS DISTINCT FROM OLD.lesson_id) THEN
    RAISE EXCEPTION 'S022: immutable progress identity' USING ERRCODE='42501';
  END IF;
  IF TG_OP='DELETE' THEN v_user:=OLD.user_id; v_lid:=OLD.lesson_id; ELSE v_user:=NEW.user_id; v_lid:=NEW.lesson_id; END IF;
  SELECT e.* INTO v_e FROM public.enrollments e JOIN public.lessons l ON l.course_id=e.course_id
    WHERE e.user_id=v_user AND l.id=v_lid FOR UPDATE OF e;
  IF NOT FOUND THEN RAISE EXCEPTION 'S022: enrollment required for progress' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_lesson FROM public.lessons WHERE id=v_lid;
  IF v_lesson.course_id IS DISTINCT FROM v_e.course_id THEN RAISE EXCEPTION 'S022: invalid progress context' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.profiles p JOIN public.courses c ON c.organization_id=p.organization_id
    WHERE p.user_id=v_user AND c.id=v_e.course_id) THEN
    RAISE EXCEPTION 'S022: progress student/tenant mismatch' USING ERRCODE='42501';
  END IF;
  v_staff:=coalesce(public.can_access_course(v_e.course_id,'students.write'),false);
  IF auth.uid() IS NULL OR NOT (v_staff OR (auth.uid()=v_user AND public.can_access_course_as_learner(v_e.course_id))) THEN
    RAISE EXCEPTION 'S022: unauthorized progress write' USING ERRCODE='42501';
  END IF;
  IF TG_OP='DELETE' THEN
    IF NOT v_staff THEN RAISE EXCEPTION 'S022: staff reset required' USING ERRCODE='42501'; END IF;
    RETURN OLD;
  END IF;
  IF TG_OP='UPDATE' AND OLD.completed AND NOT NEW.completed THEN
    RAISE EXCEPTION 'S022: use staff reset to clear completed progress' USING ERRCODE='42501';
  END IF;
  SELECT credited_at INTO v_credit FROM public.course_manual_credits WHERE enrollment_id=v_e.id AND revoked_at IS NULL;
  IF NEW.completed THEN
    IF v_lesson.type='homework' AND v_credit IS NULL AND NOT public.csz_latest_homework_approved(v_user,v_e.course_id,v_lid) THEN
      RAISE EXCEPTION 'S022: latest homework must be approved' USING ERRCODE='23514';
    END IF;
    IF TG_OP='UPDATE' AND OLD.completed THEN NEW.completed_at:=coalesce(OLD.completed_at,v_credit,clock_timestamp());
    ELSE NEW.completed_at:=coalesce(v_credit,clock_timestamp()); END IF;
  ELSE NEW.completed_at:=NULL;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_student_test_state(p_lesson_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  a public.test_attempts%ROWTYPE;
  v_active uuid;
  v_state jsonb;
  v_feedback jsonb;
  v_questions jsonb := '[]'::jsonb;
  v_used jsonb;
  v_show boolean;
  v_passing integer;
BEGIN
  PERFORM public._assert_test_learner_access(p_lesson_id);
  SELECT test_show_answers, test_passing_score INTO v_show, v_passing FROM public.lessons WHERE id = p_lesson_id;
  v_state := public._test_attempt_limits(p_lesson_id, auth.uid()) || jsonb_build_object(
    'hasAttempt', false, 'activeAttempt', NULL, 'showAnswers', v_show,
    'passingScore', v_passing, 'manualCredit', public._test_manual_credit(p_lesson_id),
    'photoRequired', public._final_test_photo_required(p_lesson_id));
  SELECT id INTO v_active FROM public.test_attempt_sessions
    WHERE user_id = auth.uid() AND lesson_id = p_lesson_id AND status = 'in_progress';
  IF v_active IS NOT NULL AND public._test_manual_credit(p_lesson_id) IS NULL THEN
    v_state := v_state || jsonb_build_object('activeAttempt', public._test_session_payload(v_active));
  END IF;
  SELECT coalesce(jsonb_agg(DISTINCT q), '[]'::jsonb) INTO v_used
    FROM public.test_attempts t CROSS JOIN LATERAL jsonb_array_elements(t.shown_question_ids) q
    WHERE t.user_id = auth.uid() AND t.lesson_id = p_lesson_id;
  v_state := v_state || jsonb_build_object('usedQuestionIds', v_used);
  SELECT * INTO a FROM public.test_attempts
    WHERE user_id = auth.uid() AND lesson_id = p_lesson_id ORDER BY completed_at DESC, id DESC LIMIT 1;
  IF NOT FOUND THEN RETURN v_state; END IF;
  IF a.session_id IS NOT NULL THEN
    v_feedback := public._test_grade_payload(a.session_id);
    SELECT public._test_public_questions(questions_snapshot, v_show AND show_answers)
      INTO v_questions FROM public.test_attempt_sessions WHERE id = a.session_id;
  ELSE
    -- Historical starts, question versions, and passing threshold are unknown.
    v_feedback := jsonb_build_object('correctAnswers', '{}'::jsonb, 'explanations', '{}'::jsonb,
      'scorePercent', CASE WHEN a.max_score > 0 THEN round(a.score * 100.0 / a.max_score)::integer ELSE 0 END,
      'passed', a.passed, 'passingScore', a.passing_score);
  END IF;
  RETURN v_state || v_feedback || jsonb_build_object('hasAttempt', true,
    'attempt', to_jsonb(a) || jsonb_build_object('questions', v_questions, 'legacy', a.session_id IS NULL));
END;
$function$

CREATE OR REPLACE FUNCTION public.get_test_attempt_photo(p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_session uuid; v_lesson uuid; v_user uuid; v_photo jsonb;
BEGIN
  SELECT id, lesson_id, user_id INTO v_session, v_lesson, v_user
    FROM public.test_attempt_sessions WHERE id = p_attempt_id;
  IF NOT FOUND THEN
    SELECT session_id, lesson_id, user_id INTO v_session, v_lesson, v_user
      FROM public.test_attempts WHERE id = p_attempt_id;
  END IF;
  IF v_user IS NULL OR auth.uid() IS NULL
    OR EXISTS (SELECT 1 FROM public.profiles WHERE user_id = auth.uid() AND blocked_at IS NOT NULL)
    OR NOT (v_user = auth.uid() OR public.can_access_lesson(v_lesson, 'students.read')) THEN
    RAISE EXCEPTION 'Attempt photo not available' USING ERRCODE = '42501';
  END IF;
  SELECT jsonb_build_object('bucket', 'final-test-photos', 'path', c.object_path,
    'capturedAt', c.completed_at, 'challengeId', c.id) INTO v_photo
    FROM public.final_test_photo_challenges c WHERE c.session_id = v_session;
  RETURN v_photo;
END;
$function$

CREATE OR REPLACE FUNCTION public.prepare_final_test_photo(p_lesson_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_enrollment uuid;
  v_course uuid;
  v_id uuid;
  c public.final_test_photo_challenges%ROWTYPE;
BEGIN
  PERFORM public._assert_test_learner_access(p_lesson_id);
  IF p_request_id IS NULL THEN RAISE EXCEPTION 'request_id is required' USING ERRCODE = '22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_user::text || ':' || p_lesson_id::text, 0));
  SELECT e.id, e.course_id INTO v_enrollment, v_course
    FROM public.enrollments e JOIN public.lessons l ON l.course_id = e.course_id
    WHERE l.id = p_lesson_id AND e.user_id = v_user FOR UPDATE OF e;
  IF NOT FOUND THEN RAISE EXCEPTION 'Enrollment is not available' USING ERRCODE = '42501'; END IF;
  PERFORM public._assert_test_learner_access(p_lesson_id);
  IF NOT public._final_test_photo_required(p_lesson_id)
    OR public._test_manual_credit(p_lesson_id) IS NOT NULL
    OR EXISTS (SELECT 1 FROM public.test_attempt_start_requests WHERE user_id = v_user
      AND lesson_id = p_lesson_id AND request_id = p_request_id)
    OR EXISTS (SELECT 1 FROM public.test_attempt_sessions WHERE user_id = v_user
      AND lesson_id = p_lesson_id AND status = 'in_progress') THEN
    RETURN jsonb_build_object('required', false);
  END IF;
  SELECT * INTO c FROM public.final_test_photo_challenges WHERE user_id = v_user
    AND lesson_id = p_lesson_id AND request_id = p_request_id FOR UPDATE;
  IF FOUND AND (c.expires_at <= clock_timestamp() OR c.enrollment_id <> v_enrollment
    OR c.completed_at IS NULL) THEN
    -- Retain the old object as orphan evidence for a service-role retention job;
    -- a fresh unpredictable path prevents reuse after expiry, an in-flight upload
    -- or a lost upload response. Every new camera preview gets a fresh path;
    -- completed proofs and actual attempt start requests remain idempotent.
    DELETE FROM public.final_test_photo_challenges WHERE id = c.id AND session_id IS NULL;
    c.id := NULL;
  END IF;
  IF c.id IS NULL THEN
    v_id := gen_random_uuid();
    INSERT INTO public.final_test_photo_challenges(id, user_id, course_id, lesson_id, enrollment_id,
      request_id, object_path, expires_at)
    VALUES (v_id, v_user, v_course, p_lesson_id, v_enrollment, p_request_id,
      v_user::text || '/' || v_id::text || '/capture.jpg', clock_timestamp() + interval '20 minutes')
    RETURNING * INTO c;
  END IF;
  RETURN jsonb_build_object('required', true, 'challengeId', c.id,
    'bucket', 'final-test-photos', 'path', c.object_path, 'expiresAt', c.expires_at,
    'completed', c.completed_at IS NOT NULL);
END;
$function$

CREATE OR REPLACE FUNCTION public.recalc_enrollment_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_course_id uuid;
  v_user_id uuid;
  v_total int;
  v_done int;
  v_progress int;
BEGIN
  -- Определяем урок (для DELETE берём OLD)
  IF TG_OP = 'DELETE' THEN
    SELECT course_id INTO v_course_id FROM lessons WHERE id = OLD.lesson_id;
    v_user_id := OLD.user_id;
  ELSE
    SELECT course_id INTO v_course_id FROM lessons WHERE id = NEW.lesson_id;
    v_user_id := NEW.user_id;
  END IF;

  IF v_course_id IS NULL OR v_user_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- Считаем общее количество уроков и пройденных
  SELECT COUNT(*) INTO v_total FROM lessons WHERE course_id = v_course_id;
  IF v_total = 0 THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT COUNT(*) INTO v_done
  FROM lesson_progress lp
  JOIN lessons l ON l.id = lp.lesson_id
  WHERE l.course_id = v_course_id
    AND lp.user_id = v_user_id
    AND lp.completed = true;

  v_progress := LEAST(100, GREATEST(0, (v_done * 100) / v_total));

  -- Обновляем enrollment, если он существует и прогресс изменился в большую сторону
  -- (не уменьшаем прогресс автоматически, чтобы не откатывать ручные правки)
  UPDATE enrollments
  SET progress = v_progress
  WHERE user_id = v_user_id
    AND course_id = v_course_id
    AND progress < v_progress;

  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.start_test_attempt(p_lesson_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_session uuid;
  v_limits jsonb;
  v_questions jsonb;
  v_count integer;
  v_passing integer;
  v_show boolean;
  v_photo_required boolean;
  v_photo_id uuid;
  v_started_at timestamptz;
BEGIN
  PERFORM public._assert_test_learner_access(p_lesson_id);
  IF p_request_id IS NULL THEN RAISE EXCEPTION 'request_id is required' USING ERRCODE = '22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_user::text || ':' || p_lesson_id::text, 0));
  PERFORM 1 FROM public.enrollments e JOIN public.lessons l ON l.course_id = e.course_id
    WHERE l.id = p_lesson_id AND e.user_id = v_user FOR UPDATE OF e;
  IF NOT FOUND THEN RAISE EXCEPTION 'Enrollment is not available' USING ERRCODE = '42501'; END IF;
  PERFORM public._assert_test_learner_access(p_lesson_id);
  IF public._test_manual_credit(p_lesson_id) IS NOT NULL THEN
    RAISE EXCEPTION 'Course already credited by the organization' USING ERRCODE = 'P0001';
  END IF;
  SELECT session_id INTO v_session FROM public.test_attempt_start_requests
    WHERE user_id = v_user AND lesson_id = p_lesson_id AND request_id = p_request_id;
  IF v_session IS NOT NULL THEN RETURN public._test_session_payload(v_session); END IF;
  -- A second tab or a network retry resumes the same attempt, including across midnight.
  SELECT id INTO v_session FROM public.test_attempt_sessions
    WHERE user_id = v_user AND lesson_id = p_lesson_id AND status = 'in_progress';
  IF v_session IS NOT NULL THEN
    INSERT INTO public.test_attempt_start_requests(user_id, lesson_id, request_id, session_id)
      VALUES (v_user, p_lesson_id, p_request_id, v_session);
    RETURN public._test_session_payload(v_session);
  END IF;
  v_limits := public._test_attempt_limits(p_lesson_id, v_user);
  IF (v_limits->>'maxAttempts')::integer > 0
    AND (v_limits->>'attemptsUsed')::integer >= (v_limits->>'maxAttempts')::integer THEN
    RAISE EXCEPTION 'Attempts exhausted' USING ERRCODE = 'P0001', DETAIL = v_limits::text;
  END IF;
  IF (v_limits->>'maxAttemptsPerDay')::integer > 0
    AND (v_limits->>'attemptsUsedToday')::integer >= (v_limits->>'maxAttemptsPerDay')::integer THEN
    RAISE EXCEPTION 'Daily attempts exhausted' USING ERRCODE = 'P0001', DETAIL = v_limits::text;
  END IF;
  SELECT test_questions_to_show, test_passing_score, test_show_answers
    INTO v_count, v_passing, v_show FROM public.lessons WHERE id = p_lesson_id;
  -- Validate every candidate before sampling: malformed content must not randomly
  -- consume a quota slot or silently disappear from the configured question bank.
  WITH normalized AS MATERIALIZED (
    SELECT tq.id, tq.lesson_id, tq.question,
      public._test_normalize_options(tq.options, tq.correct_answer) AS options,
      tq.order_index, tq.correct_answer, tq.explanation, tq.image_url, tq.is_bank_question
    FROM public.test_questions tq WHERE tq.lesson_id = p_lesson_id
  )
  SELECT jsonb_agg(to_jsonb(q) ORDER BY q.position) INTO v_questions FROM (
    SELECT tq.*, row_number() OVER () AS position
    FROM (SELECT * FROM normalized ORDER BY random()
      LIMIT CASE WHEN v_count > 0 THEN v_count ELSE NULL END) tq
  ) q;
  IF v_questions IS NULL OR jsonb_array_length(v_questions) = 0 THEN
    RAISE EXCEPTION 'No test questions available' USING ERRCODE = '22023';
  END IF;
  -- Use one reservation timestamp for expiry and the session. Crossing the
  -- expiry boundary between SELECT and INSERT must not consume an invalid slot.
  v_started_at := clock_timestamp();
  v_photo_required := public._final_test_photo_required(p_lesson_id);
  IF v_photo_required THEN
    SELECT c.id INTO v_photo_id FROM public.final_test_photo_challenges c
      JOIN public.enrollments e ON e.id = c.enrollment_id AND e.user_id = v_user AND e.course_id = c.course_id
      WHERE c.user_id = v_user AND c.lesson_id = p_lesson_id AND c.request_id = p_request_id
        AND c.completed_at IS NOT NULL AND c.expires_at > v_started_at AND c.session_id IS NULL
        AND public._final_test_photo_object_valid(c.id)
      FOR UPDATE OF c;
    IF v_photo_id IS NULL THEN
      RAISE EXCEPTION 'Final test photo required' USING ERRCODE = 'P0001';
    END IF;
  END IF;
  INSERT INTO public.test_attempt_sessions(user_id, lesson_id, request_id, started_at, questions_snapshot, passing_score, show_answers, requires_final_test_photo)
    VALUES (v_user, p_lesson_id, p_request_id, v_started_at, v_questions, coalesce(v_passing, 60), v_show, v_photo_required)
    RETURNING id INTO v_session;
  IF v_photo_id IS NOT NULL THEN
    UPDATE public.final_test_photo_challenges SET session_id = v_session WHERE id = v_photo_id;
  END IF;
  INSERT INTO public.test_attempt_start_requests(user_id, lesson_id, request_id, session_id)
    VALUES (v_user, p_lesson_id, p_request_id, v_session);
  RETURN public._test_session_payload(v_session);
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_test_attempt(p_attempt_id uuid, p_answers jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  s public.test_attempt_sessions%ROWTYPE;
  v_score integer;
  v_max integer;
  v_passed boolean;
  v_completed timestamptz;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501'; END IF;
  SELECT * INTO s FROM public.test_attempt_sessions WHERE id = p_attempt_id AND user_id = auth.uid();
  IF NOT FOUND THEN RAISE EXCEPTION 'Attempt not found' USING ERRCODE = '42501'; END IF;
  PERFORM public._assert_test_learner_access(s.lesson_id);
  PERFORM pg_advisory_xact_lock(hashtextextended(s.user_id::text || ':' || s.lesson_id::text, 0));
  SELECT * INTO STRICT s FROM public.test_attempt_sessions WHERE id = p_attempt_id FOR UPDATE;
  PERFORM public._assert_test_learner_access(s.lesson_id);
  -- A response can be lost after commit: return the original result, never regrade or recount.
  IF s.status = 'completed' THEN RETURN public._test_grade_payload(s.id); END IF;
  -- Expiry limits the START window, not test duration. An attached photo remains
  -- valid during a long attempt, even if the course setting is later disabled.
  IF s.requires_final_test_photo AND NOT EXISTS (
    SELECT 1 FROM public.final_test_photo_challenges c
    WHERE c.session_id = s.id AND c.user_id = s.user_id AND c.lesson_id = s.lesson_id
      AND c.request_id = s.request_id AND c.completed_at IS NOT NULL
      AND c.completed_at <= s.started_at AND s.started_at < c.expires_at
      AND public._final_test_photo_object_valid(c.id)
  ) THEN
    RAISE EXCEPTION 'Final test photo required' USING ERRCODE = 'P0001';
  END IF;
  IF p_answers IS NULL OR jsonb_typeof(p_answers) <> 'object' THEN
    RAISE EXCEPTION 'answers must be an object' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_each(p_answers) a
    LEFT JOIN LATERAL (SELECT q FROM jsonb_array_elements(s.questions_snapshot) q WHERE q->>'id' = a.key) item ON true
    WHERE item.q IS NULL OR jsonb_typeof(a.value) <> 'number'
      OR a.value::text !~ '^[0-9]+$'
      OR CASE WHEN jsonb_typeof(a.value) = 'number' AND a.value::text ~ '^[0-9]+$'
        THEN (a.value::text)::numeric >= jsonb_array_length(item.q->'options') ELSE false END
  ) THEN
    RAISE EXCEPTION 'Answer is not a valid option in this attempt' USING ERRCODE = '22023';
  END IF;
  SELECT count(*)::integer, count(*) FILTER (WHERE p_answers->(q->>'id') = q->'correct_answer')::integer
    INTO v_max, v_score FROM jsonb_array_elements(s.questions_snapshot) q;
  v_passed := round(v_score * 100.0 / v_max) >= s.passing_score;
  v_completed := clock_timestamp();
  INSERT INTO public.test_attempts(user_id, lesson_id, session_id, started_at, completed_at,
    score, max_score, answers, shown_question_ids, passing_score, passed)
  VALUES (s.user_id, s.lesson_id, s.id, s.started_at, v_completed, v_score, v_max, p_answers,
    (SELECT jsonb_agg(q->'id') FROM jsonb_array_elements(s.questions_snapshot) q), s.passing_score, v_passed);
  UPDATE public.test_attempt_sessions SET status = 'completed', submitted_at = v_completed WHERE id = s.id;
  IF v_passed THEN
    INSERT INTO public.lesson_progress(user_id, lesson_id, completed, completed_at)
      VALUES (s.user_id, s.lesson_id, true, v_completed)
    ON CONFLICT (user_id, lesson_id) DO UPDATE SET completed = true,
      completed_at = coalesce(public.lesson_progress.completed_at, EXCLUDED.completed_at);
  END IF;
  RETURN public._test_grade_payload(s.id);
END;
$function$

CREATE OR REPLACE FUNCTION public.uc_learning_access(p_org uuid, p_scope jsonb, p_write boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE u uuid:=auth.uid();BEGIN
 IF auth.role() IS DISTINCT FROM 'authenticated' OR NOT public.uc_learning_person(u) OR NOT public.account_deletion_access_allowed() OR NOT public.uc_learning_scope_valid(p_org,p_scope) THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
 IF NOT p_write AND u=(p_scope->>'user_id')::uuid THEN
  IF NOT coalesce(public.can_access_course_as_learner((p_scope->>'course_id')::uuid),false) OR NOT coalesce(public._paid_20260922_course_read((p_scope->>'course_id')::uuid,true),false) THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
  RETURN 'learner';
 END IF;
 IF u=(p_scope->>'user_id')::uuid OR NOT public.uc_learning_staff(u,p_org,(p_scope->>'group_id')::uuid,p_write) THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
 RETURN 'staff';
END;$function$

CREATE OR REPLACE FUNCTION public.uc_learning_test_component(p_state uc_learning_outcome_states, p_component jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE attempt_row record;best jsonb;grade jsonb;facts jsonb:='[]';r jsonb:=p_component->'pass_rule';passed boolean;n integer:=0;sessions jsonb;reason text;BEGIN
 SELECT jsonb_build_object('count',count(*),'latest_started_at',max(s.started_at)) INTO sessions
 FROM public.test_attempt_sessions s JOIN public.uc_learning_attempt_contexts c ON c.session_id=s.id
 WHERE c.state_id=p_state.id AND c.criteria_id=p_state.criteria_id AND c.binding_state='bound' AND s.user_id=p_state.user_id AND s.lesson_id=(p_component->>'lesson_id')::uuid;
 FOR attempt_row IN SELECT a.*,s.started_at original_started_at,s.passing_score original_threshold,s.submitted_at original_submitted_at
  FROM public.test_attempts a JOIN public.test_attempt_sessions s ON s.id=a.session_id AND s.user_id=a.user_id AND s.lesson_id=a.lesson_id
  JOIN public.uc_learning_attempt_contexts c ON c.session_id=s.id AND c.user_id=s.user_id AND c.lesson_id=s.lesson_id AND c.session_started_at=s.started_at
  WHERE c.state_id=p_state.id AND c.criteria_id=p_state.criteria_id AND c.binding_state='bound' AND a.user_id=p_state.user_id AND a.lesson_id=(p_component->>'lesson_id')::uuid AND s.status='completed'
  ORDER BY a.completed_at,a.id LIMIT 1001
 LOOP
  n:=n+1;IF n>1000 THEN PERFORM public.uc_learning_error('LIMIT_EXCEEDED');END IF;
  IF attempt_row.max_score<=0 OR attempt_row.score<0 OR attempt_row.score>attempt_row.max_score OR attempt_row.passed IS NULL OR attempt_row.passing_score IS NULL OR attempt_row.passing_score NOT BETWEEN 0 AND 100 OR attempt_row.started_at IS DISTINCT FROM attempt_row.original_started_at OR attempt_row.completed_at IS DISTINCT FROM attempt_row.original_submitted_at OR attempt_row.passing_score IS DISTINCT FROM attempt_row.original_threshold THEN
   reason:='ORIGINAL_GRADE_UNAVAILABLE';EXIT;
  END IF;
  grade:=jsonb_build_object('attempt_id',attempt_row.id,'session_id',attempt_row.session_id,'started_at',attempt_row.original_started_at,'completed_at',attempt_row.completed_at,'score',attempt_row.score,'max_score',attempt_row.max_score,'original_passed',attempt_row.passed,'original_passing_score',attempt_row.original_threshold);
  facts:=facts||jsonb_build_array(grade);
  IF best IS NULL OR p_component->>'retake_policy'='latest_completed'
   OR attempt_row.score::numeric*(best->>'max_score')::numeric>(best->>'score')::numeric*attempt_row.max_score::numeric
   OR (attempt_row.score::numeric*(best->>'max_score')::numeric=(best->>'score')::numeric*attempt_row.max_score::numeric AND (attempt_row.completed_at,attempt_row.id)>((best->>'completed_at')::timestamptz,(best->>'attempt_id')::uuid)) THEN best:=grade;END IF;
 END LOOP;
 IF reason IS NOT NULL THEN best:=NULL;
 ELSIF best IS NULL THEN
  reason:=CASE WHEN EXISTS(SELECT 1 FROM public.test_attempts WHERE user_id=p_state.user_id AND lesson_id=(p_component->>'lesson_id')::uuid) THEN 'LEGACY_ATTEMPT_UNBOUND' WHEN (sessions->>'count')::integer>0 THEN 'ASSESSMENT_IN_PROGRESS' ELSE 'ASSESSMENT_NOT_STARTED' END;
 ELSE
  passed:=CASE WHEN r->>'kind'='session_pass' THEN (best->>'original_passed')::boolean
   WHEN r->>'rounding'='nearest_integer_half_up' THEN floor((best->>'score')::numeric*100/(best->>'max_score')::numeric+0.5)*100>=(r->>'threshold_basis_points')::integer
   ELSE (best->>'score')::numeric*10000>=(r->>'threshold_basis_points')::numeric*(best->>'max_score')::numeric END;
  reason:=CASE WHEN passed THEN 'CRITERIA_SATISFIED' ELSE 'CRITERIA_NOT_SATISFIED' END;
 END IF;
 RETURN jsonb_build_object('component_id',p_component->'component_id','kind','test','status',CASE WHEN best IS NOT NULL THEN CASE WHEN passed THEN 'satisfied' ELSE 'not_satisfied' END WHEN reason IN('ASSESSMENT_IN_PROGRESS','ASSESSMENT_NOT_STARTED') THEN 'not_started' ELSE 'unknown' END,
  'reason_code',reason,'original_grade',best,'selected_source_hash',public.uc_program_hash(jsonb_build_object('selected',best,'actual_completed_facts',facts,'sessions',sessions)),
  'provenance',CASE WHEN best IS NOT NULL THEN 'bound_context' ELSE 'unavailable' END);
END;$function$

CREATE OR REPLACE FUNCTION public.apply_learning_outcome_action(p_organization_id uuid, p_request_id uuid, p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor uuid:=auth.uid();action text:=p_command->>'action';expected bigint;course uuid;version uuid;draft uuid;scope jsonb;scope_hash text;payload_hash text;people uuid[];
 c public.uc_learning_criteria_versions;s public.uc_learning_outcome_states;m public.uc_learning_machine_results;d public.uc_learning_attestation_decisions;oldreq public.uc_learning_outcome_requests;
 proof jsonb;modules jsonb;criteria_definition jsonb;live jsonb;current jsonb;receipt jsonb;event_id uuid;nextrev bigint;source_proof jsonb:='{}';required_ids jsonb;authority jsonb;decision_id uuid;BEGIN
 IF actor IS NULL OR p_organization_id IS NULL OR p_request_id IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR NOT public.uc_learning_person(actor) OR NOT public.account_deletion_access_allowed() THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
 IF jsonb_typeof(p_command) IS DISTINCT FROM 'object' OR octet_length(p_command::text)>65536 OR NOT coalesce(action IN('save_criteria_version','approve_criteria_version','capture_machine_result','record_attestation_decision','supersede_decision'),false) THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
 IF jsonb_typeof(p_command->'expected_revision') IS DISTINCT FROM 'number' OR coalesce(p_command->>'expected_revision','')!~'^(0|[1-9][0-9]{0,15})$' OR(p_command->>'expected_revision')::numeric>9007199254740990 THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
 expected:=(p_command->>'expected_revision')::bigint;payload_hash:=public.uc_program_hash(p_command);
 IF action='save_criteria_version' THEN
  IF NOT public.uc_learning_shape(p_command,ARRAY['action','course_id','program_version_id','draft_id','expected_revision','definition','reason']) OR NOT public.uc_learning_uuid(p_command->'course_id') OR NOT public.uc_learning_uuid(p_command->'program_version_id') OR NOT(p_command->'draft_id'='null'::jsonb OR public.uc_learning_uuid(p_command->'draft_id')) OR NOT public.uc_learning_text(p_command->'reason',2000) THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
  course:=(p_command->>'course_id')::uuid;version:=(p_command->>'program_version_id')::uuid;draft:=(p_command->>'draft_id')::uuid;
 ELSIF action='approve_criteria_version' THEN
  IF NOT public.uc_learning_shape(p_command,ARRAY['action','version_id','expected_revision','expected_content_hash','reason']) OR NOT public.uc_learning_uuid(p_command->'version_id') OR coalesce(p_command->>'expected_content_hash','')!~'^[a-f0-9]{64}$' OR NOT public.uc_learning_text(p_command->'reason',2000) THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
  draft:=(p_command->>'version_id')::uuid;SELECT * INTO c FROM public.uc_learning_criteria_versions WHERE id=draft AND organization_id=p_organization_id;course:=c.course_id;version:=c.program_version_id;
 ELSE
  scope:=p_command->'scope';PERFORM public.uc_learning_access(p_organization_id,scope,action<>'capture_machine_result');
  IF action='capture_machine_result' THEN
   IF NOT public.uc_learning_shape(p_command,ARRAY['action','scope','expected_revision','expected_criteria_ref','reason']) OR NOT public.uc_learning_text(p_command->'reason',2000) THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
  ELSE
   IF NOT public.uc_learning_shape(p_command,ARRAY['action','scope','expected_revision','criteria_ref','machine_result_id','expected_machine_input_hash','expected_decision_id','outcome','basis','staff_reason','learner_summary','reviewed_current_component_ids','recognized_component_ids','recognition_file_version_id'])
   OR NOT public.uc_learning_uuid(p_command->'machine_result_id') OR coalesce(p_command->>'expected_machine_input_hash','')!~'^[a-f0-9]{64}$'
   OR NOT(p_command->'expected_decision_id'='null'::jsonb OR public.uc_learning_uuid(p_command->'expected_decision_id'))
   OR NOT coalesce(p_command->>'outcome' IN('passed','not_passed','deferred'),false) OR NOT coalesce(p_command->>'basis' IN('machine','recognition'),false)
   OR NOT public.uc_learning_text(p_command->'staff_reason',2000) OR NOT public.uc_learning_text(p_command->'learner_summary',1000)
   OR NOT public.uc_learning_ids(p_command->'reviewed_current_component_ids',0,20) OR NOT public.uc_learning_ids(p_command->'recognized_component_ids',0,20)
   OR NOT(p_command->'recognition_file_version_id'='null'::jsonb OR public.uc_learning_uuid(p_command->'recognition_file_version_id')) THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
  END IF;
 END IF;
 IF action IN('save_criteria_version','approve_criteria_version') THEN
  IF NOT public.uc_learning_staff(actor,p_organization_id,NULL,true) OR NOT EXISTS(SELECT 1 FROM public.courses WHERE id=course AND organization_id=p_organization_id) THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
  scope_hash:=public.uc_program_hash(jsonb_build_object('organization_id',p_organization_id,'course_id',course,'program_version_id',version));
  criteria_definition:=CASE WHEN action='save_criteria_version' THEN p_command->'definition' ELSE c.definition END;
  PERFORM public.uc_learning_validate_criteria(p_organization_id,course,criteria_definition,false);
  SELECT array_agg(DISTINCT x) INTO people FROM(SELECT actor x UNION SELECT(c.definition->>'reviewer_id')::uuid UNION SELECT(criteria_definition->>'reviewer_id')::uuid UNION SELECT value::text::uuid FROM jsonb_array_elements_text(criteria_definition->'eligible_decider_ids'))q WHERE x IS NOT NULL;
 ELSE scope_hash:=public.uc_program_hash(scope);people:=ARRAY[actor,(scope->>'user_id')::uuid];END IF;
 PERFORM public.uc_learning_try_people(people);
 IF NOT pg_try_advisory_xact_lock(hashtextextended('uc014_request:'||actor::text||':'||p_request_id::text,0)) OR NOT pg_try_advisory_xact_lock(hashtextextended('uc014_scope:'||scope_hash,0)) THEN PERFORM public.uc_learning_error('REVISION_CONFLICT');END IF;
 -- Replay still checks current role, exact tenant/scope, source and assignment.
 SELECT * INTO oldreq FROM public.uc_learning_outcome_requests WHERE actor_id=actor AND request_id=p_request_id;
 IF FOUND THEN
  IF oldreq.organization_id IS DISTINCT FROM p_organization_id OR oldreq.payload_hash<>payload_hash OR oldreq.action<>action THEN PERFORM public.uc_learning_error('REQUEST_CONFLICT');END IF;
  IF action IN('save_criteria_version','approve_criteria_version') THEN
   SELECT * INTO c FROM public.uc_learning_criteria_versions WHERE id=(oldreq.receipt->>'event_id')::uuid;
   IF c.redacted OR c.programme_proof IS DISTINCT FROM public.uc_learning_programme_proof(p_organization_id,c.program_version_id) OR(action='approve_criteria_version' AND c.reviewer_id IS DISTINCT FROM actor) THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
   current:=public.read_learning_outcome(p_organization_id,jsonb_build_object('kind','criteria','course_id',course,'program_version_id',version));
  ELSE
   current:=public.uc_learning_envelope(p_organization_id,scope);
   IF action='capture_machine_result' AND NOT coalesce((current->'capabilities'->>'can_capture')::boolean,false) THEN PERFORM public.uc_learning_error('SOURCE_UNAVAILABLE');END IF;
   IF action<>'capture_machine_result' AND NOT coalesce((current->'capabilities'->>'can_decide')::boolean,false) THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
   IF action<>'capture_machine_result' AND p_command->>'basis'='recognition' THEN
    SELECT * INTO d FROM public.uc_learning_attestation_decisions WHERE id=(oldreq.receipt->>'event_id')::uuid AND organization_id=p_organization_id AND user_id=(scope->>'user_id')::uuid;
    IF NOT coalesce(public.uc_document_action_allowed(p_organization_id,'read',NULL,NULL),false) THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
    IF d.id IS NULL OR d.redacted OR d.source_proof->'recognition_proof' IS NULL OR d.source_proof->'recognition_proof' IS DISTINCT FROM public.uc_learning_recognition_proof(p_organization_id,(p_command->>'recognition_file_version_id')::uuid) THEN PERFORM public.uc_learning_error('SOURCE_CHANGED');END IF;
   END IF;
  END IF;
  RETURN jsonb_build_object('schema_version',1,'receipt',oldreq.receipt||jsonb_build_object('replayed',true),'current',current);
 END IF;
 IF action='save_criteria_version' THEN
  proof:=public.uc_learning_programme_proof(p_organization_id,version);
  IF proof IS NULL OR NOT(EXISTS(SELECT 1 FROM public.course_program_bindings WHERE organization_id=p_organization_id AND course_id=course AND version_id=version) OR EXISTS(SELECT 1 FROM public.group_program_bindings WHERE organization_id=p_organization_id AND course_id=course AND version_id=version)) THEN PERFORM public.uc_learning_error('SOURCE_UNAVAILABLE');END IF;
  IF draft IS NULL THEN
   IF expected<>0 THEN PERFORM public.uc_learning_error('REVISION_CONFLICT');END IF;
   INSERT INTO public.uc_learning_criteria_versions(organization_id,course_id,program_version_id,revision,state,definition,programme_proof,content_hash,created_by,reviewer_id,participant_ids)
   VALUES(p_organization_id,course,version,1,'draft',criteria_definition,proof,public.uc_program_hash(jsonb_build_object('definition',criteria_definition,'programme_proof',proof,'modules','[]'::jsonb)),actor,(criteria_definition->>'reviewer_id')::uuid,people) RETURNING * INTO c;
  ELSE
   SELECT * INTO c FROM public.uc_learning_criteria_versions WHERE id=draft AND organization_id=p_organization_id AND course_id=course AND program_version_id=version FOR UPDATE NOWAIT;
   IF c.id IS NULL OR c.created_by IS DISTINCT FROM actor OR c.state<>'draft' OR c.redacted THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
   IF c.revision<>expected THEN PERFORM public.uc_learning_error('REVISION_CONFLICT');END IF;
   UPDATE public.uc_learning_criteria_versions SET definition=criteria_definition,programme_proof=proof,content_hash=public.uc_program_hash(jsonb_build_object('definition',criteria_definition,'programme_proof',proof,'modules','[]'::jsonb)),reviewer_id=(criteria_definition->>'reviewer_id')::uuid,revision=revision+1,participant_ids=people WHERE id=c.id RETURNING * INTO c;
  END IF;
  event_id:=c.id;nextrev:=c.revision;
 ELSIF action='approve_criteria_version' THEN
  SELECT * INTO c FROM public.uc_learning_criteria_versions WHERE id=draft AND organization_id=p_organization_id FOR UPDATE NOWAIT;
  IF c.id IS NULL OR c.state<>'draft' OR c.redacted OR c.reviewer_id IS DISTINCT FROM actor OR((c.definition->>'independent_review_required')::boolean AND c.created_by=actor) THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
  IF c.revision<>expected OR c.content_hash<>p_command->>'expected_content_hash' THEN PERFORM public.uc_learning_error('REVISION_CONFLICT');END IF;
  proof:=public.uc_learning_programme_proof(p_organization_id,c.program_version_id);IF proof IS NULL OR proof IS DISTINCT FROM c.programme_proof THEN PERFORM public.uc_learning_error('SOURCE_CHANGED');END IF;
  modules:=public.uc_learning_validate_criteria(p_organization_id,c.course_id,c.definition,true);
  UPDATE public.uc_learning_criteria_versions v SET state='approved',approved_at=clock_timestamp(),approved_by=actor,revision=v.revision+1,module_snapshots=modules,content_hash=public.uc_program_hash(jsonb_build_object('definition',v.definition,'programme_proof',v.programme_proof,'modules',modules)) WHERE v.id=c.id RETURNING * INTO c;
  event_id:=c.id;nextrev:=c.revision;
 ELSE
  PERFORM public.uc_learning_access(p_organization_id,scope,action<>'capture_machine_result');
  SELECT * INTO s FROM public.uc_learning_outcome_states WHERE program_enrollment_snapshot_id=(scope->>'program_enrollment_snapshot_id')::uuid FOR UPDATE NOWAIT;
  IF s.id IS NULL THEN
   -- A new human-only assessment has no test session to observe. An explicit
   -- currently authorized staff capture starts its prospective unknown context.
   IF action<>'capture_machine_result' OR expected<>0 OR NOT public.uc_learning_staff(actor,p_organization_id,(scope->>'group_id')::uuid,true) THEN PERFORM public.uc_learning_error('PREREQUISITE_MISSING');END IF;
   SELECT * INTO c FROM public.uc_learning_criteria_versions v WHERE v.organization_id=p_organization_id AND v.course_id=(scope->>'course_id')::uuid AND v.program_version_id=(scope->>'program_version_id')::uuid AND v.state='approved' AND NOT v.redacted ORDER BY v.approved_at DESC,v.id DESC LIMIT 1;
   IF c.id IS NULL OR c.definition->'main'->>'kind' IS DISTINCT FROM 'human_assessment' OR public.uc_learning_criteria_ref(c) IS DISTINCT FROM p_command->'expected_criteria_ref' OR c.programme_proof IS DISTINCT FROM public.uc_learning_programme_proof(p_organization_id,c.program_version_id) THEN PERFORM public.uc_learning_error('SOURCE_CHANGED');END IF;
   INSERT INTO public.uc_learning_outcome_states(organization_id,group_id,user_id,course_id,enrollment_id,program_enrollment_snapshot_id,program_version_id,criteria_id)
   VALUES(p_organization_id,(scope->>'group_id')::uuid,(scope->>'user_id')::uuid,(scope->>'course_id')::uuid,(scope->>'enrollment_id')::uuid,(scope->>'program_enrollment_snapshot_id')::uuid,c.program_version_id,c.id) RETURNING * INTO s;
  ELSE SELECT * INTO c FROM public.uc_learning_criteria_versions WHERE id=s.criteria_id;END IF;
  IF s.revision<>expected THEN PERFORM public.uc_learning_error('REVISION_CONFLICT');END IF;
  IF c.id IS NULL OR c.redacted OR c.programme_proof IS DISTINCT FROM public.uc_learning_programme_proof(p_organization_id,c.program_version_id) OR public.uc_learning_criteria_ref(c) IS DISTINCT FROM(CASE WHEN action='capture_machine_result' THEN p_command->'expected_criteria_ref' ELSE p_command->'criteria_ref' END) THEN PERFORM public.uc_learning_error('SOURCE_CHANGED');END IF;
  nextrev:=s.revision+1;live:=public.uc_learning_evaluate(s);
  IF action='capture_machine_result' THEN
   INSERT INTO public.uc_learning_machine_results(state_id,organization_id,user_id,revision_created,criteria_ref,input_hash,evaluation) VALUES(s.id,p_organization_id,s.user_id,nextrev,public.uc_learning_criteria_ref(c),live->>'input_hash',live) RETURNING id INTO event_id;
   UPDATE public.uc_learning_outcome_states SET revision=nextrev,machine_id=event_id WHERE id=s.id;
  ELSE
   IF actor=s.user_id OR NOT c.definition->'eligible_decider_ids' ? actor::text THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
   SELECT * INTO m FROM public.uc_learning_machine_results WHERE id=s.machine_id AND state_id=s.id;
   IF m.id IS NULL OR m.id IS DISTINCT FROM(p_command->>'machine_result_id')::uuid OR m.input_hash IS DISTINCT FROM p_command->>'expected_machine_input_hash' OR m.input_hash IS DISTINCT FROM live->>'input_hash' OR c.programme_proof IS DISTINCT FROM public.uc_learning_programme_proof(p_organization_id,s.program_version_id) THEN PERFORM public.uc_learning_error('SOURCE_CHANGED');END IF;
   decision_id:=(p_command->>'expected_decision_id')::uuid;
   IF s.decision_id IS DISTINCT FROM decision_id OR(action='record_attestation_decision' AND decision_id IS NOT NULL) OR(action='supersede_decision' AND decision_id IS NULL) THEN PERFORM public.uc_learning_error('REVISION_CONFLICT');END IF;
   IF p_command->>'basis'='machine' THEN
    IF p_command->'recognition_file_version_id'<>'null'::jsonb OR jsonb_array_length(p_command->'recognized_component_ids')<>0 THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
    IF p_command->>'outcome'='passed' AND live->>'eligibility'<>'eligible' OR p_command->>'outcome'='not_passed' AND live->>'eligibility'<>'not_eligible' THEN PERFORM public.uc_learning_error('PREREQUISITE_MISSING');END IF;
    SELECT coalesce(jsonb_agg(x->'component_id' ORDER BY x->>'component_id'),'[]') INTO required_ids FROM jsonb_array_elements(live->'components')x WHERE x->>'provenance'='current_condition_observed';
    IF p_command->>'outcome'='passed' AND required_ids IS DISTINCT FROM(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x),'[]') FROM jsonb_array_elements_text(p_command->'reviewed_current_component_ids')x) THEN PERFORM public.uc_learning_error('PREREQUISITE_MISSING');END IF;
   ELSE
    IF NOT coalesce(public.uc_document_action_allowed(p_organization_id,'read',NULL,NULL),false) THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
    IF NOT c.definition->'recognition_file_version_ids' ?(p_command->>'recognition_file_version_id') OR NOT public.uc_program_active_file_proof(p_organization_id,(p_command->>'recognition_file_version_id')::uuid) OR jsonb_array_length(p_command->'recognized_component_ids')=0
    OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_command->'recognized_component_ids')x WHERE NOT(c.definition->'recognition_component_ids' ? x)) THEN PERFORM public.uc_learning_error('PREREQUISITE_MISSING');END IF;
    IF p_command->>'outcome'='passed' AND EXISTS(SELECT 1 FROM jsonb_array_elements(live->'components')x WHERE x->>'status'<>'satisfied' AND NOT(p_command->'recognized_component_ids' ?(x->>'component_id'))) THEN PERFORM public.uc_learning_error('PREREQUISITE_MISSING');END IF;
    source_proof:=jsonb_build_object('recognition_file_version_id',p_command->'recognition_file_version_id','recognition_proof',public.uc_learning_recognition_proof(p_organization_id,(p_command->>'recognition_file_version_id')::uuid),'recognized_component_ids',p_command->'recognized_component_ids');
   END IF;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_command->'reviewed_current_component_ids')r WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(live->'components')v WHERE v->>'component_id'=r AND v->>'provenance'='current_condition_observed')) THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
   IF p_command->>'outcome'='passed' AND EXISTS(SELECT 1 FROM jsonb_array_elements(live->'components')v WHERE v->>'provenance'='current_condition_observed' AND NOT(p_command->'recognized_component_ids' ?(v->>'component_id')) AND NOT(p_command->'reviewed_current_component_ids' ?(v->>'component_id'))) THEN PERFORM public.uc_learning_error('PREREQUISITE_MISSING');END IF;
   authority:=jsonb_build_object('actor_id',actor,'scope',scope,'checked_at',clock_timestamp(),'both_writes',true,'eligible_decider',true,'criteria_ref',public.uc_learning_criteria_ref(c));
   INSERT INTO public.uc_learning_attestation_decisions(state_id,organization_id,user_id,revision_created,criteria_id,machine_result_id,machine_input_hash,outcome,basis,staff_reason,learner_summary,actor_id,authority_snapshot,source_proof,supersedes_id,participant_ids)
   VALUES(s.id,p_organization_id,s.user_id,nextrev,c.id,m.id,m.input_hash,p_command->>'outcome',p_command->>'basis',p_command->>'staff_reason',p_command->>'learner_summary',actor,authority,source_proof||jsonb_build_object('reviewed_current_component_ids',p_command->'reviewed_current_component_ids'),decision_id,ARRAY[actor,s.user_id]) RETURNING id INTO event_id;
   UPDATE public.uc_learning_outcome_states SET revision=nextrev,decision_id=event_id WHERE id=s.id;
  END IF;
 END IF;
 receipt:=jsonb_build_object('request_id',p_request_id,'action',action,'scope_hash',scope_hash,'applied_revision',nextrev,'event_id',event_id,'input_hash',payload_hash,'replayed',false);
 INSERT INTO public.uc_learning_outcome_requests(actor_id,request_id,organization_id,user_id,state_id,action,payload_hash,receipt,participant_ids) VALUES(actor,p_request_id,p_organization_id,s.user_id,s.id,action,payload_hash,receipt,coalesce(people,ARRAY[actor]));
 current:=CASE WHEN action IN('save_criteria_version','approve_criteria_version') THEN public.read_learning_outcome(p_organization_id,jsonb_build_object('kind','criteria','course_id',course,'program_version_id',version)) ELSE public.uc_learning_envelope(p_organization_id,scope) END;
 RETURN jsonb_build_object('schema_version',1,'receipt',receipt,'current',current);
EXCEPTION WHEN lock_not_available THEN PERFORM public.uc_learning_error('REVISION_CONFLICT');END;$function$

CREATE OR REPLACE FUNCTION public.read_learning_outcome(p_organization_id uuid, p_query jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE u uuid:=auth.uid();target uuid;course uuid;enrollment uuid;after_id uuid;lim integer;sn record;rows jsonb:='[]';n integer:=0;last_id uuid;proof jsonb;versions jsonb;BEGIN
 IF auth.role() IS DISTINCT FROM 'authenticated' OR NOT public.uc_learning_person(u) OR NOT public.account_deletion_access_allowed() THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
 IF p_query->>'kind'='outcome' THEN
  IF NOT public.uc_learning_shape(p_query,ARRAY['kind','scope']) THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
  RETURN public.uc_learning_envelope(p_organization_id,p_query->'scope');
 ELSIF p_query->>'kind'='associations' THEN
  IF NOT public.uc_learning_shape(p_query,ARRAY['kind','user_id','course_id','enrollment_id','after_snapshot_id','limit']) OR NOT public.uc_learning_uuid(p_query->'user_id') OR NOT public.uc_learning_uuid(p_query->'course_id') OR NOT public.uc_learning_uuid(p_query->'enrollment_id') OR NOT(p_query->'after_snapshot_id'='null'::jsonb OR public.uc_learning_uuid(p_query->'after_snapshot_id')) OR jsonb_typeof(p_query->'limit') IS DISTINCT FROM 'number' OR p_query->>'limit'!~'^[1-9][0-9]?$' THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
  lim:=(p_query->>'limit')::integer;IF lim>50 THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
  target:=(p_query->>'user_id')::uuid;course:=(p_query->>'course_id')::uuid;enrollment:=(p_query->>'enrollment_id')::uuid;after_id:=(p_query->>'after_snapshot_id')::uuid;
  IF NOT EXISTS(SELECT 1 FROM public.enrollments e JOIN public.courses c ON c.id=e.course_id WHERE e.id=enrollment AND e.user_id=target AND e.course_id=course AND c.organization_id=p_organization_id AND e.status NOT IN('cancelled','revoked'))
   OR NOT(target=u AND public.can_access_course_as_learner(course) AND public._paid_20260922_course_read(course,true) OR target<>u AND(public.uc_learning_staff(u,p_organization_id,NULL,false) OR EXISTS(SELECT 1 FROM public.student_group_memberships_effective g WHERE g.user_id=target AND g.organization_id=p_organization_id AND public.uc_learning_staff(u,p_organization_id,g.group_id,false)))) THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
  FOR sn IN SELECT s.id,public.uc_learning_scope(s.id)scope FROM public.group_program_enrollment_snapshots s
   WHERE s.organization_id=p_organization_id AND s.enrollment_id=enrollment AND s.user_id=target AND s.course_id=course AND(after_id IS NULL OR s.id>after_id)
    AND public.uc_learning_scope_valid(p_organization_id,public.uc_learning_scope(s.id)) AND(target=u OR public.uc_learning_staff(u,p_organization_id,s.group_id,false)) ORDER BY s.id LIMIT lim+1
  LOOP
   n:=n+1;EXIT WHEN n>lim;rows:=rows||jsonb_build_array(public.uc_learning_envelope(p_organization_id,sn.scope));last_id:=sn.id;
  END LOOP;
  RETURN jsonb_build_object('schema_version',1,'organization_id',p_organization_id,'user_id',target,'course_id',course,'enrollment_id',enrollment,'associations',rows,'next_after_snapshot_id',CASE WHEN n>lim THEN last_id END);
 ELSIF p_query->>'kind'='criteria' THEN
  IF NOT public.uc_learning_shape(p_query,ARRAY['kind','course_id','program_version_id']) OR NOT public.uc_learning_uuid(p_query->'course_id') OR NOT public.uc_learning_uuid(p_query->'program_version_id') THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
  IF NOT public.uc_learning_staff(u,p_organization_id,NULL,false) THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
  course:=(p_query->>'course_id')::uuid;target:=(p_query->>'program_version_id')::uuid;
  IF NOT EXISTS(SELECT 1 FROM public.courses WHERE id=course AND organization_id=p_organization_id) THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
  proof:=public.uc_learning_programme_proof(p_organization_id,target);
  IF(SELECT count(*) FROM public.uc_learning_criteria_versions WHERE organization_id=p_organization_id AND course_id=course AND program_version_id=target AND NOT redacted)>50 THEN PERFORM public.uc_learning_error('LIMIT_EXCEEDED');END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(v)-'participant_ids' ORDER BY v.created_at DESC,v.id DESC),'[]') INTO versions FROM public.uc_learning_criteria_versions v WHERE v.organization_id=p_organization_id AND v.course_id=course AND v.program_version_id=target AND NOT v.redacted;
  RETURN jsonb_build_object('schema_version',1,'organization_id',p_organization_id,'course_id',course,'program_version_id',target,'programme_proof',proof,'versions',versions,'capabilities',jsonb_build_object('can_save',public.uc_learning_staff(u,p_organization_id,NULL,true)));
 ELSIF p_query->>'kind' IN('options','decision_options') THEN RETURN public.uc_learning_options(p_organization_id,p_query);
 ELSE PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
END;$function$

CREATE OR REPLACE FUNCTION public.uc_learning_envelope(p_org uuid, p_scope jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE audience text;s public.uc_learning_outcome_states;c public.uc_learning_criteria_versions;m public.uc_learning_machine_results;d public.uc_learning_attestation_decisions;fresh boolean:=false;decision_fresh boolean:=false;live jsonb;technical jsonb;decision jsonb;machine jsonb;prerequisites jsonb:='[]';can_decide boolean:=false;BEGIN
 audience:=public.uc_learning_access(p_org,p_scope,false);
 SELECT * INTO s FROM public.uc_learning_outcome_states WHERE program_enrollment_snapshot_id=(p_scope->>'program_enrollment_snapshot_id')::uuid;
 SELECT jsonb_build_object('status',e.status,'progress',coalesce(e.progress,0),'manual_credited_at',(SELECT credited_at FROM public.course_manual_credits WHERE enrollment_id=e.id AND revoked_at IS NULL ORDER BY credited_at DESC,id DESC LIMIT 1)) INTO technical FROM public.enrollments e WHERE e.id=(p_scope->>'enrollment_id')::uuid;
 IF s.id IS NULL THEN
  SELECT * INTO c FROM public.uc_learning_criteria_versions v WHERE v.organization_id=p_org AND v.course_id=(p_scope->>'course_id')::uuid AND v.program_version_id=(p_scope->>'program_version_id')::uuid AND v.state='approved' AND NOT v.redacted ORDER BY v.approved_at DESC,v.id DESC LIMIT 1;
  IF c.definition->'main'->>'kind' IS DISTINCT FROM 'human_assessment' THEN c:=NULL;END IF;
  prerequisites:=jsonb_build_array(CASE WHEN c.id IS NULL THEN 'NEW_BOUND_SESSION_REQUIRED' ELSE 'HUMAN_ASSESSMENT_CONTEXT_NOT_STARTED' END);
 ELSE
  SELECT * INTO c FROM public.uc_learning_criteria_versions WHERE id=s.criteria_id;
  SELECT * INTO m FROM public.uc_learning_machine_results WHERE id=s.machine_id AND state_id=s.id;
  SELECT * INTO d FROM public.uc_learning_attestation_decisions WHERE id=s.decision_id AND state_id=s.id;
  live:=public.uc_learning_evaluate(s);
  IF c.redacted OR c.id IS NULL THEN prerequisites:=prerequisites||jsonb_build_array('SOURCE_ERASED');END IF;
  IF c.programme_proof IS DISTINCT FROM public.uc_learning_programme_proof(p_org,s.program_version_id) THEN prerequisites:=prerequisites||jsonb_build_array('SOURCE_UNAVAILABLE');END IF;
  IF m.id IS NULL THEN prerequisites:=prerequisites||jsonb_build_array('MACHINE_RESULT_NOT_CAPTURED');
  ELSE
   fresh:=m.input_hash=live->>'input_hash';
   machine:=jsonb_build_object('id',m.id,'revision_created',m.revision_created,'criteria_ref',m.criteria_ref,'input_hash',m.input_hash,'evaluated_at',m.evaluated_at,'eligibility',m.evaluation->'eligibility','components',m.evaluation->'components','source_fresh',fresh);
   IF NOT fresh THEN prerequisites:=prerequisites||jsonb_build_array('EVIDENCE_CHANGED');END IF;
  END IF;
  can_decide:=audience='staff' AND public.uc_learning_staff(auth.uid(),p_org,s.group_id,true) AND c.definition->'eligible_decider_ids' ? auth.uid()::text AND NOT c.redacted AND m.id IS NOT NULL AND fresh;
  IF d.id IS NOT NULL THEN
   decision_fresh:=fresh AND NOT d.redacted AND(d.basis<>'recognition' OR(d.source_proof->'recognition_proof' IS NOT NULL AND d.source_proof->'recognition_proof' IS NOT DISTINCT FROM public.uc_learning_recognition_proof(p_org,(d.source_proof->>'recognition_file_version_id')::uuid)));
   IF NOT decision_fresh THEN prerequisites:=prerequisites||jsonb_build_array('DECISION_SOURCE_CHANGED');END IF;
   decision:=jsonb_build_object('id',d.id,'machine_result_id',d.machine_result_id,'outcome',d.outcome,'learner_summary',d.learner_summary,'recorded_at',d.recorded_at,'supersedes_id',d.supersedes_id);
   IF audience='staff' THEN decision:=decision||jsonb_build_object('staff_reason',d.staff_reason,'actor_id',d.actor_id,'basis',d.basis);END IF;
  END IF;
 END IF;
 RETURN jsonb_build_object('schema_version',1,'audience',audience,'scope',p_scope,'revision',coalesce(s.revision,0),'criteria_ref',CASE WHEN c.id IS NOT NULL THEN public.uc_learning_criteria_ref(c) END,'machine',machine,'last_decision',decision,
  'decision_relation',CASE WHEN d.id IS NULL THEN 'no_decision' WHEN d.machine_result_id IS DISTINCT FROM m.id THEN 'new_machine_requires_review' WHEN NOT decision_fresh THEN 'source_changed' ELSE 'current_inputs' END,
  'technical_observation',technical,'prerequisites',prerequisites,'capabilities',jsonb_build_object('can_capture',c.id IS NOT NULL AND NOT c.redacted AND c.programme_proof IS NOT DISTINCT FROM public.uc_learning_programme_proof(p_org,(p_scope->>'program_version_id')::uuid) AND(s.id IS NOT NULL OR audience='staff' AND public.uc_learning_staff(auth.uid(),p_org,(p_scope->>'group_id')::uuid,true)),'can_decide',coalesce(can_decide,false)));
END;$function$

CREATE OR REPLACE FUNCTION public.uc_learning_evaluate(p_state uc_learning_outcome_states)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.uc_learning_criteria_versions;x jsonb;part jsonb;parts jsonb:='[]';pinned jsonb;current_ids jsonb;progress jsonb;n integer;done integer;eligibility text;technical jsonb;proof jsonb;input jsonb;BEGIN
 SELECT * INTO c FROM public.uc_learning_criteria_versions WHERE id=p_state.criteria_id;
 proof:=public.uc_learning_programme_proof(p_state.organization_id,p_state.program_version_id);
 SELECT jsonb_build_object('status',e.status,'progress',coalesce(e.progress,0),'manual_credited_at',(SELECT credited_at FROM public.course_manual_credits WHERE enrollment_id=e.id AND revoked_at IS NULL ORDER BY credited_at DESC,id DESC LIMIT 1)) INTO technical FROM public.enrollments e WHERE e.id=p_state.enrollment_id AND e.user_id=p_state.user_id AND e.course_id=p_state.course_id;
 IF c.id IS NULL OR c.state<>'approved' OR c.redacted OR proof IS DISTINCT FROM c.programme_proof THEN
  eligibility:='unknown';
 ELSE
  FOR x IN SELECT value FROM jsonb_array_elements(jsonb_build_array(c.definition->'main')||(c.definition->'requirements')) LOOP
   IF x->>'kind'='test' THEN part:=public.uc_learning_test_component(p_state,x);
   ELSIF x->>'kind'='module_completion' THEN
    SELECT value INTO pinned FROM jsonb_array_elements(c.module_snapshots) WHERE value->'component_id'=x->'component_id';
    SELECT coalesce(jsonb_agg(id ORDER BY id),'[]') INTO current_ids FROM public.lessons WHERE course_id=p_state.course_id AND module_id=(x->>'module_id')::uuid;
    IF pinned IS NULL OR pinned->'lesson_ids' IS DISTINCT FROM current_ids OR NOT EXISTS(SELECT 1 FROM public.course_modules WHERE id=(x->>'module_id')::uuid AND course_id=p_state.course_id) THEN
     part:=jsonb_build_object('status','unknown','reason_code','MODULE_CONTENT_CHANGED','selected_source_hash',public.uc_program_hash(jsonb_build_object('pinned',pinned,'current',current_ids)));
    ELSE
     SELECT count(*)::integer,count(*) FILTER(WHERE lp.completed IS TRUE)::integer,coalesce(jsonb_agg(jsonb_build_object('lesson_id',l.id,'progress',to_jsonb(lp)) ORDER BY l.id),'[]') INTO n,done,progress
     FROM public.lessons l LEFT JOIN public.lesson_progress lp ON lp.lesson_id=l.id AND lp.user_id=p_state.user_id WHERE l.id IN(SELECT value::text::uuid FROM jsonb_array_elements_text(pinned->'lesson_ids'));
     part:=jsonb_build_object('status',CASE WHEN n>0 AND n=done THEN 'satisfied' ELSE 'not_started' END,'reason_code',CASE WHEN n>0 AND n=done THEN 'CURRENT_MODULE_CONDITION_OBSERVED' ELSE 'MODULE_INCOMPLETE' END,'selected_source_hash',public.uc_program_hash(jsonb_build_object('pinned',pinned,'observed_progress',progress)));
    END IF;
    part:=part||jsonb_build_object('component_id',x->'component_id','kind','module_completion','original_grade',NULL,'provenance','current_condition_observed');
   ELSE part:=jsonb_build_object('component_id',x->'component_id','kind','human_assessment','status','unknown','reason_code','HUMAN_ASSESSMENT_REQUIRED','original_grade',NULL,'selected_source_hash',NULL,'provenance','unavailable');
   END IF;
   parts:=parts||jsonb_build_array(part);
  END LOOP;
  eligibility:=CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(parts) AS elem(value) WHERE elem.value->>'status'='unknown') THEN 'unknown' WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(parts) AS elem(value) WHERE elem.value->>'status'='not_started') THEN 'incomplete' WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(parts) AS elem(value) WHERE elem.value->>'status'='not_satisfied') THEN 'not_eligible' ELSE 'eligible' END;
 END IF;
 input:=jsonb_build_object('criteria_ref',public.uc_learning_criteria_ref(c),'programme_proof',proof,'components',parts,'technical_observation',technical,'criteria_redacted',coalesce(c.redacted,true));
 RETURN jsonb_build_object('eligibility',eligibility,'components',parts,'technical_observation',technical,'input_hash',public.uc_program_hash(input));
END;$function$

CREATE OR REPLACE FUNCTION public.uc_learning_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE erased uuid;ids uuid[];j jsonb;BEGIN
 erased:=nullif(current_setting('sintagma.account_deletion_erase_user',true),'')::uuid;
 IF TG_OP<>'INSERT' AND erased IS NOT NULL AND auth.role()='service_role' AND(to_jsonb(OLD)->>'user_id'=erased::text OR coalesce(to_jsonb(OLD)->'participant_ids','[]') ? erased::text) THEN RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END IF;
 IF TG_OP='DELETE' THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
 IF TG_OP='UPDATE' THEN
  IF TG_TABLE_NAME='uc_learning_outcome_states' THEN
   IF(to_jsonb(OLD)-ARRAY['revision','machine_id','decision_id']) IS DISTINCT FROM(to_jsonb(NEW)-ARRAY['revision','machine_id','decision_id']) OR NEW.revision<>OLD.revision+1 THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
  ELSIF TG_TABLE_NAME='uc_learning_criteria_versions' THEN
   IF OLD.state<>'draft' OR OLD.redacted OR NEW.revision<>OLD.revision+1 OR(to_jsonb(OLD)-ARRAY['revision','definition','module_snapshots','programme_proof','content_hash','reviewer_id','participant_ids','state','approved_at','approved_by']) IS DISTINCT FROM(to_jsonb(NEW)-ARRAY['revision','definition','module_snapshots','programme_proof','content_hash','reviewer_id','participant_ids','state','approved_at','approved_by']) OR(NEW.state='approved' AND NEW.definition IS DISTINCT FROM OLD.definition) THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
  ELSE PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
 END IF;
 j:=to_jsonb(NEW);SELECT array_agg(DISTINCT x::uuid ORDER BY x::uuid) INTO ids FROM(SELECT j->>'user_id' x UNION SELECT value FROM jsonb_array_elements_text(coalesce(j->'participant_ids','[]')))q WHERE x IS NOT NULL;
 PERFORM public.uc_learning_try_people(coalesce(ids,'{}'::uuid[]));RETURN NEW;
END;$function$

CREATE OR REPLACE FUNCTION public.prepare_admission_case_evidence(p_case_id uuid, p_expected_revision bigint, p_expected_program_ref jsonb, p_request_id uuid, p_source jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a uuid:=auth.uid();c public.uc_admission_cases;prior public.uc_admission_case_requests;r public.uc_admission_evidence_reservations;candidate jsonb;digest text;receipt jsonb;BEGIN
 IF auth.role()IS DISTINCT FROM 'authenticated'OR a IS NULL OR p_request_id IS NULL THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
 IF p_expected_revision IS NULL OR p_expected_revision NOT BETWEEN 1 AND 9007199254740991 OR NOT public.uc_admission_ref_valid(p_expected_program_ref)OR NOT public.uc_admission_shape(p_source,CASE p_source->>'kind'WHEN 'upload'THEN ARRAY['kind','requirement_id','supersedes_id','declared_size','declared_mime','declared_sha256']WHEN 'existing'THEN ARRAY['kind','requirement_id','supersedes_id','candidate']ELSE ARRAY[]::text[]END)OR NOT public.uc_admission_uuid(p_source->'requirement_id')OR(p_source->'supersedes_id'<>'null'::jsonb AND NOT public.uc_admission_uuid(p_source->'supersedes_id'))THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
 IF p_source->>'kind'='upload'THEN
  IF jsonb_typeof(p_source->'declared_size')IS DISTINCT FROM 'number'OR p_source->>'declared_size'!~'^[1-9][0-9]{0,7}$'OR(p_source->>'declared_size')::bigint>20971520 OR coalesce(p_source->>'declared_mime'IN('application/pdf','image/jpeg','image/png'),false)=false OR coalesce(jsonb_typeof(p_source->'declared_sha256')='string'AND p_source->>'declared_sha256'~'^[a-f0-9]{64}$',false)=false THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
 ELSE
  candidate:=p_source->'candidate';IF NOT public.uc_admission_shape(candidate,ARRAY['kind','id','version_id','fingerprint'])OR NOT public.uc_admission_uuid(candidate->'id')OR(candidate->'version_id'<>'null'::jsonb AND NOT public.uc_admission_uuid(candidate->'version_id'))OR coalesce(candidate->>'kind'IN('identity_document','enrollment_document','contract_artifact','organization_document_version'),false)=false OR coalesce(candidate->>'fingerprint'~'^[a-f0-9]{64}$',false)=false THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
 END IF;
 SELECT * INTO c FROM public.uc_admission_cases WHERE id=p_case_id;IF c.id IS NULL THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
 PERFORM public.uc_admission_lock(a,c.organization_id,c.user_id,c.group_id,c.enrollment_id,c.responsible_id);PERFORM pg_advisory_xact_lock(hashtextextended('uc_admission_request:'||a::text||':'||p_request_id::text,0));
 digest:=public.uc_program_hash(jsonb_build_object('case_id',p_case_id,'expected_revision',p_expected_revision,'expected_program_ref',p_expected_program_ref,'source',p_source));
 SELECT * INTO prior FROM public.uc_admission_case_requests WHERE actor_id=a AND request_id=p_request_id;
 IF prior.actor_id IS NOT NULL THEN IF prior.case_id<>c.id OR prior.kind<>'prepare_evidence'OR prior.payload_digest<>digest THEN PERFORM public.uc_admission_error('REVISION_CONFLICT');END IF;RETURN prior.receipt;END IF;
 SELECT * INTO c FROM public.uc_admission_cases WHERE id=p_case_id FOR UPDATE;
 IF c.revision<>p_expected_revision THEN PERFORM public.uc_admission_error('REVISION_CONFLICT');END IF;IF c.revision>=9007199254740991 THEN PERFORM public.uc_admission_error('LIMIT_REACHED');END IF;
 IF c.program_ref IS DISTINCT FROM p_expected_program_ref OR c.program_ref IS DISTINCT FROM public.uc_admission_program(c.organization_id,c.user_id,c.group_id,c.enrollment_id)THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c.requirements)x WHERE x->>'id'=p_source->>'requirement_id')THEN PERFORM public.uc_admission_error('REVIEW_REQUIRED');END IF;
 IF p_source->'supersedes_id'<>'null'::jsonb AND NOT EXISTS(SELECT 1 FROM public.uc_admission_case_evidence e WHERE e.id=(p_source->>'supersedes_id')::uuid AND e.case_id=c.id AND e.requirement_id=(p_source->>'requirement_id')::uuid AND NOT EXISTS(SELECT 1 FROM public.uc_admission_case_evidence n WHERE n.case_id=c.id AND n.supersedes_id=e.id))THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;
 IF(SELECT count(*)FROM public.uc_admission_evidence_reservations WHERE case_id=c.id AND state IN('prepared','sealed')AND expires_at>clock_timestamp())>=100 OR(jsonb_array_length(public.uc_admission_current_evidence(c.id,a))>=100 AND p_source->'supersedes_id'='null'::jsonb)THEN PERFORM public.uc_admission_error('LIMIT_REACHED');END IF;
 IF p_source->>'kind'='existing'THEN candidate:=public.uc_admission_candidate(c.id,candidate->>'kind',(candidate->>'id')::uuid,(candidate->>'version_id')::uuid,a);
 IF candidate IS NULL OR candidate->'candidate'->>'fingerprint'IS DISTINCT FROM p_source->'candidate'->>'fingerprint'THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;
 IF candidate->'candidate'->>'availability'<>'capturable'THEN PERFORM public.uc_admission_error('SOURCE_UNAVAILABLE');END IF;END IF;
 INSERT INTO public.uc_admission_evidence_reservations(case_id,organization_id,user_id,actor_id,prepare_request_id,evidence_version_id,requirement_id,supersedes_id,expected_revision,program_ref,source)VALUES(c.id,c.organization_id,c.user_id,a,p_request_id,gen_random_uuid(),(p_source->>'requirement_id')::uuid,(p_source->>'supersedes_id')::uuid,p_expected_revision,c.program_ref,p_source)RETURNING * INTO r;
 receipt:=jsonb_build_object('schema_version',1,'case_id',c.id,'case_revision',c.revision,'reservation_id',r.id,'evidence_version_id',r.evidence_version_id,'expires_at',r.expires_at,'source_kind',p_source->>'kind','upload_slot',CASE WHEN p_source->>'kind'='upload'THEN jsonb_build_object('bucket','admission-case-evidence','path',c.user_id::text||'/'||c.organization_id::text||'/'||c.id::text||'/staging/'||a::text||'/'||r.id::text,'upsert',false,'max_bytes',20971520)END);
 INSERT INTO public.uc_admission_case_requests(actor_id,request_id,case_id,organization_id,user_id,kind,payload_digest,receipt)VALUES(a,p_request_id,c.id,c.organization_id,c.user_id,'prepare_evidence',digest,receipt);RETURN receipt;END;$function$

CREATE OR REPLACE FUNCTION public.uc_admission_candidate(p_case uuid, p_kind text, p_id uuid, p_version uuid DEFAULT NULL::uuid, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.uc_admission_cases;s jsonb;obj jsonb;path text;label text;availability text:='unavailable';fingerprint text;BEGIN SELECT * INTO c FROM public.uc_admission_cases WHERE id=p_case;
 p_actor:=coalesce(p_actor,auth.uid());IF NOT public.uc_admission_staff_allowed(p_actor,c.organization_id,c.user_id,c.group_id,c.enrollment_id,false)THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
 IF p_kind='identity_document'AND p_version IS NULL THEN SELECT to_jsonb(d)INTO s FROM public.student_identity_documents d WHERE d.id=p_id AND d.user_id=c.user_id AND d.organization_id=c.organization_id;
 ELSIF p_kind='enrollment_document'AND p_version IS NULL THEN SELECT to_jsonb(d)INTO s FROM public.student_documents d WHERE d.id=p_id AND d.enrollment_id=c.enrollment_id;
 ELSIF p_kind='organization_document_version'AND p_version IS NOT NULL THEN
  IF p_actor IS DISTINCT FROM auth.uid()OR NOT public.uc_document_action_allowed(c.organization_id,'read',NULL,NULL)THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
  SELECT to_jsonb(v)||jsonb_build_object('name',d.name)INTO s FROM public.org_documents d JOIN public.org_document_versions v ON v.document_id=d.id AND v.organization_id=d.organization_id WHERE d.id=p_id AND v.id=p_version AND d.organization_id=c.organization_id AND public.uc_program_file_proof(c.organization_id,v.id);availability:='needs_individual_copy';
 ELSIF p_kind='contract_artifact'AND p_version IS NULL THEN SELECT to_jsonb(d)INTO s FROM public.org_contracts d WHERE d.id=p_id AND d.organization_id=c.organization_id AND d.student_user_id=c.user_id;availability:='needs_individual_copy';END IF;
 IF s IS NULL THEN RETURN NULL;END IF;
 label:=coalesce(nullif(public.uc_admission_trim(left(coalesce(s->>'name',s->>'title'),160)),''),'Документ');
 IF p_kind IN('identity_document','enrollment_document')THEN
  path:=public.uc_admission_student_path(coalesce(nullif(s->>'file_path',''),s->>'file_url'),c.user_id);
  IF nullif(s->>'file_path','')IS NOT NULL AND nullif(s->>'file_url','')IS NOT NULL AND public.uc_admission_student_path(s->>'file_url',c.user_id)IS DISTINCT FROM path THEN path:=NULL;END IF;
  IF path IS NOT NULL THEN obj:=public.uc_admission_object('student-documents',path,NULL,s);END IF;
  IF obj IS NOT NULL THEN availability:='capturable';END IF;
 END IF;
 fingerprint:=public.uc_program_hash(jsonb_build_object('scope',public.uc_admission_scope(c.id),'kind',p_kind,'id',p_id,'version_id',p_version,'row',s,'object',obj));
 RETURN jsonb_build_object('candidate',jsonb_build_object('kind',p_kind,'id',p_id,'version_id',p_version,'availability',availability,'label',label,'fingerprint',fingerprint),'object',obj,'source_snapshot',s);
END;$function$

CREATE OR REPLACE FUNCTION public.uc_admission_evidence_context(p_case_id uuid, p_reservation_id uuid, p_expected_revision bigint, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a uuid:=auth.uid();c public.uc_admission_cases;r public.uc_admission_evidence_reservations;src jsonb;sealed jsonb;prior public.uc_admission_case_requests;replay jsonb;digest text;BEGIN
 SELECT * INTO c FROM public.uc_admission_cases WHERE id=p_case_id;SELECT * INTO r FROM public.uc_admission_evidence_reservations WHERE id=p_reservation_id AND case_id=c.id AND actor_id=a;
 IF auth.role()IS DISTINCT FROM 'authenticated'OR a IS NULL OR r.id IS NULL OR p_request_id IS NULL OR NOT public.uc_admission_staff_allowed(a,c.organization_id,c.user_id,c.group_id,c.enrollment_id,true)OR NOT public.uc_admission_staff_allowed(a,c.organization_id,c.user_id,c.group_id,c.enrollment_id,false)THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
 IF p_expected_revision IS DISTINCT FROM r.expected_revision THEN PERFORM public.uc_admission_error('REVISION_CONFLICT');END IF;
 digest:=public.uc_program_hash(jsonb_build_object('case_id',c.id,'reservation_id',r.id,'expected_revision',p_expected_revision));
 sealed:=coalesce(r.sealed_proof,jsonb_build_object('bucket','admission-case-evidence','path',r.user_id::text||'/'||r.organization_id::text||'/'||r.case_id::text||'/sealed/'||r.evidence_version_id::text,'object_id',NULL,'updated_at',NULL,'byte_sha256',NULL,'byte_size',NULL,'mime_type',NULL));
 IF r.state='consumed'THEN
  SELECT * INTO prior FROM public.uc_admission_case_requests WHERE actor_id=a AND request_id=p_request_id AND case_id=c.id AND kind='evidence_committed'AND payload_digest=digest;
  IF prior.actor_id IS NULL OR r.commit_request_id IS DISTINCT FROM p_request_id THEN PERFORM public.uc_admission_error('REVISION_CONFLICT');END IF;
  src:=public.uc_admission_object('admission-case-evidence',sealed->>'path',sealed->>'byte_sha256');IF src IS NULL OR src->>'object_id'IS DISTINCT FROM sealed->>'object_id'OR(src->>'updated_at')::timestamptz IS DISTINCT FROM(sealed->>'updated_at')::timestamptz OR src->>'byte_size'IS DISTINCT FROM sealed->>'byte_size'OR src->>'mime_type'IS DISTINCT FROM sealed->>'mime_type'THEN PERFORM public.uc_admission_error('SOURCE_UNAVAILABLE');END IF;
  replay:=public.uc_admission_result(c.id,a,prior.receipt,true);
 ELSE
  IF r.state NOT IN('prepared','sealed')OR r.expires_at<=clock_timestamp()THEN PERFORM public.uc_admission_error('SOURCE_UNAVAILABLE');END IF;
  IF c.revision<>p_expected_revision THEN PERFORM public.uc_admission_error('REVISION_CONFLICT');END IF;IF c.revision>=9007199254740991 THEN PERFORM public.uc_admission_error('LIMIT_REACHED');END IF;
  IF c.program_ref IS DISTINCT FROM r.program_ref OR c.program_ref IS DISTINCT FROM public.uc_admission_program(c.organization_id,c.user_id,c.group_id,c.enrollment_id)THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;
  src:=public.uc_admission_source_proof(r.id,a);IF src IS NULL THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;
  IF r.state='sealed'THEN
   IF r.commit_request_id IS DISTINCT FROM p_request_id OR src IS DISTINCT FROM r.source_proof THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;
   prior.receipt:=public.uc_admission_object('admission-case-evidence',sealed->>'path',sealed->>'byte_sha256');IF prior.receipt IS NULL OR prior.receipt->>'object_id'IS DISTINCT FROM sealed->>'object_id'OR(prior.receipt->>'updated_at')::timestamptz IS DISTINCT FROM(sealed->>'updated_at')::timestamptz OR prior.receipt->>'byte_size'IS DISTINCT FROM sealed->>'byte_size'OR prior.receipt->>'mime_type'IS DISTINCT FROM sealed->>'mime_type'THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;
  END IF;
 END IF;
 RETURN jsonb_build_object('schema_version',1,'mode',r.state,'actor_id',a,'scope',public.uc_admission_scope(c.id),'case_id',c.id,'case_revision',c.revision,'expected_revision',r.expected_revision,'reservation_id',r.id,'evidence_version_id',r.evidence_version_id,'requirement_id',r.requirement_id,'supersedes_id',r.supersedes_id,'request_id',p_request_id,'expires_at',r.expires_at,'source_kind',r.source->>'kind','source',src,'sealed',sealed,'replay_result',replay);
END;$function$

CREATE OR REPLACE FUNCTION public.uc_admission_evidence_file_context(p_case_id uuid, p_evidence_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a uuid:=auth.uid();c public.uc_admission_cases;e public.uc_admission_case_evidence;o jsonb;BEGIN SELECT * INTO c FROM public.uc_admission_cases WHERE id=p_case_id;
 IF auth.role()IS DISTINCT FROM 'authenticated'OR NOT public.uc_admission_staff_allowed(a,c.organization_id,c.user_id,c.group_id,c.enrollment_id,false)THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
 SELECT * INTO e FROM public.uc_admission_case_evidence WHERE id=p_evidence_version_id AND case_id=c.id;
 o:=public.uc_admission_object('admission-case-evidence',e.sealed_path,e.byte_sha256);IF e.id IS NULL OR o IS NULL OR(o->>'object_id')::uuid IS DISTINCT FROM e.storage_object_id OR(o->>'updated_at')::timestamptz IS DISTINCT FROM e.object_updated_at OR(o->>'byte_size')::bigint IS DISTINCT FROM e.byte_size OR o->>'mime_type'IS DISTINCT FROM e.mime_type THEN PERFORM public.uc_admission_error('SOURCE_UNAVAILABLE');END IF;
 RETURN jsonb_build_object('schema_version',1,'actor_id',a,'scope',public.uc_admission_scope(c.id),'case_id',c.id,'case_revision',c.revision,'evidence_version_id',e.id,'object',o,'byte_sha256',e.byte_sha256,'byte_size',e.byte_size,'mime_type',e.mime_type);END;$function$

CREATE OR REPLACE FUNCTION public.uc_admission_lock_rules(p_sources jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 PERFORM 1 FROM public.org_documents WHERE id IN(SELECT(x->>'document_id')::uuid FROM jsonb_array_elements(p_sources)x)ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.org_document_versions WHERE id IN(SELECT(x->>'version_id')::uuid FROM jsonb_array_elements(p_sources)x)ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.org_document_reviews WHERE id IN(SELECT(x->>'review_id')::uuid FROM jsonb_array_elements(p_sources)x)ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM storage.objects WHERE id IN(SELECT v.storage_object_id FROM public.org_document_versions v,jsonb_array_elements(p_sources)x WHERE v.id=(x->>'version_id')::uuid)ORDER BY id FOR SHARE NOWAIT;
EXCEPTION WHEN lock_not_available THEN PERFORM public.uc_admission_error('REVISION_CONFLICT');END;$function$

CREATE OR REPLACE FUNCTION public.uc_admission_lock_source(p_reservation uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r public.uc_admission_evidence_reservations;s jsonb;BEGIN SELECT * INTO STRICT r FROM public.uc_admission_evidence_reservations WHERE id=p_reservation;
 IF r.source->>'kind'='existing'THEN
  IF r.source->'candidate'->>'kind'='identity_document'THEN PERFORM 1 FROM public.student_identity_documents WHERE id=(r.source->'candidate'->>'id')::uuid FOR SHARE NOWAIT;
  ELSIF r.source->'candidate'->>'kind'='enrollment_document'THEN PERFORM 1 FROM public.student_documents WHERE id=(r.source->'candidate'->>'id')::uuid FOR SHARE NOWAIT;ELSE PERFORM public.uc_admission_error('SOURCE_UNAVAILABLE');END IF;END IF;
 s:=public.uc_admission_source_proof(r.id,r.actor_id);
 PERFORM 1 FROM storage.objects WHERE id IN((s->>'object_id')::uuid,(r.sealed_proof->>'object_id')::uuid)ORDER BY id FOR SHARE NOWAIT;
EXCEPTION WHEN lock_not_available THEN PERFORM public.uc_admission_error('REVISION_CONFLICT');END;$function$

CREATE OR REPLACE FUNCTION public.uc_admission_prerequisites(p_org uuid, p_user uuid, p_group uuid, p_enrollment uuid, p_rules boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE code text;BEGIN
 IF public.uc_admission_association(p_org,p_user,p_group,p_enrollment)IS NULL THEN code:='association_inactive';
 ELSIF NOT EXISTS(SELECT 1 FROM public.group_program_bindings WHERE group_id=p_group AND organization_id=p_org)THEN code:='missing_program_binding';
 ELSIF NOT EXISTS(SELECT 1 FROM public.group_program_enrollment_snapshots WHERE group_id=p_group AND enrollment_id=p_enrollment AND user_id=p_user AND organization_id=p_org)THEN code:='missing_enrollment_snapshot';
 ELSIF public.uc_admission_program(p_org,p_user,p_group,p_enrollment)IS NULL THEN code:='program_file_unavailable';ELSIF p_rules THEN code:='rule_set_unreviewed';END IF;
 RETURN CASE WHEN code IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(jsonb_build_object('code',code,'public_label',CASE code WHEN 'association_inactive'THEN 'Учебная связь недоступна'WHEN 'rule_set_unreviewed'THEN 'Нужно проверить правила личного дела'ELSE 'Нужно подтвердить программу обучения'END,'next_action',CASE code WHEN 'association_inactive'THEN 'contact_staff'WHEN 'rule_set_unreviewed'THEN 'review_rule_set'ELSE 'open_programme_confirmation'END,'persisted',false))END;END;$function$

CREATE OR REPLACE FUNCTION public.uc_admission_redact(p_value jsonb, p_user uuid, p_force boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE k text;v jsonb;result jsonb;active boolean:=p_force;BEGIN
 IF jsonb_typeof(p_value)='array'THEN SELECT coalesce(jsonb_agg(public.uc_admission_redact(x,p_user,p_force)),'[]')INTO result FROM jsonb_array_elements(p_value)x;RETURN result;
 ELSIF jsonb_typeof(p_value)<>'object'THEN RETURN p_value;END IF;
 active:=active OR EXISTS(SELECT 1 FROM jsonb_each(p_value)e WHERE e.key IN('actor_id','reviewer_id','responsible_id','assignee_id','captured_by','approved_by','recorded_by')AND e.value=to_jsonb(p_user));
 result:='{}';FOR k,v IN SELECT * FROM jsonb_each(p_value)LOOP
  IF k IN('actor_id','reviewer_id','responsible_id','assignee_id','captured_by','approved_by','recorded_by')AND v=to_jsonb(p_user)THEN v:='null';
  ELSIF active AND k IN('reason','review_reason','staff_label','provision','label')AND jsonb_typeof(v)='string'THEN v:=to_jsonb('Сведения удалены'::text);
  ELSIF active AND k IN('staff_id','org_staff_id')THEN v:='null';
  ELSIF active AND k='path'AND jsonb_typeof(v)='string'AND position(p_user::text IN(v#>>'{}'))>0 THEN v:='null';
  ELSE v:=public.uc_admission_redact(v,p_user,active);END IF;result:=result||jsonb_build_object(k,v);END LOOP;
 IF p_value?'authority_snapshot'AND result->'authority_snapshot'IS DISTINCT FROM p_value->'authority_snapshot'THEN result:=jsonb_set(result,'{authority_redacted}','true');END IF;
 IF p_value?'source_snapshot'AND result->'source_snapshot'IS DISTINCT FROM p_value->'source_snapshot'THEN result:=jsonb_set(result,'{source_redacted}','true');END IF;RETURN result;END;$function$

CREATE OR REPLACE FUNCTION public.uc_admission_source_proof(p_reservation uuid, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r public.uc_admission_evidence_reservations;candidate jsonb;o jsonb;path text;BEGIN SELECT * INTO r FROM public.uc_admission_evidence_reservations WHERE id=p_reservation;
 IF r.source->>'kind'='upload'THEN
  path:=r.user_id::text||'/'||r.organization_id::text||'/'||r.case_id::text||'/staging/'||r.actor_id::text||'/'||r.id::text;
  IF NOT EXISTS(SELECT 1 FROM storage.objects s WHERE s.bucket_id='admission-case-evidence'AND s.name=path AND coalesce(to_jsonb(s)->>'owner_id',to_jsonb(s)->>'owner')=r.actor_id::text)THEN RETURN NULL;END IF;
  o:=public.uc_admission_object('admission-case-evidence',path,r.source->>'declared_sha256',r.source);
  IF o->>'byte_size'IS DISTINCT FROM r.source->>'declared_size'OR o->>'mime_type'IS DISTINCT FROM r.source->>'declared_mime'THEN RETURN NULL;END IF;RETURN o;
 END IF;
 candidate:=public.uc_admission_candidate(r.case_id,r.source->'candidate'->>'kind',(r.source->'candidate'->>'id')::uuid,(r.source->'candidate'->>'version_id')::uuid,p_actor);
 IF candidate->'candidate'->>'fingerprint'IS DISTINCT FROM r.source->'candidate'->>'fingerprint'OR candidate->'candidate'->>'availability'IS DISTINCT FROM 'capturable'THEN RETURN NULL;END IF;RETURN candidate->'object';END;$function$

CREATE OR REPLACE FUNCTION public.uc_attest_admission_case_evidence(p_actor_id uuid, p_case_id uuid, p_reservation_id uuid, p_expected_revision bigint, p_request_id uuid, p_source_object_id uuid, p_source_updated_at timestamp with time zone, p_source_fingerprint text, p_sealed_object_id uuid, p_sealed_updated_at timestamp with time zone, p_byte_sha256 text, p_byte_size bigint, p_mime_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.uc_admission_cases;r public.uc_admission_evidence_reservations;src jsonb;obj jsonb;sealed jsonb;ctx uuid;BEGIN
 IF auth.role()IS DISTINCT FROM 'service_role'OR auth.uid()IS NOT NULL THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
 IF p_request_id IS NULL OR p_source_object_id IS NULL OR p_source_updated_at IS NULL OR p_sealed_object_id IS NULL OR p_sealed_updated_at IS NULL OR coalesce(p_byte_sha256~'^[a-f0-9]{64}$',false)=false OR p_byte_size IS NULL OR p_byte_size NOT BETWEEN 1 AND 20971520 OR coalesce(p_mime_type IN('application/pdf','image/jpeg','image/png'),false)=false THEN PERFORM public.uc_admission_error('INVALID_INPUT');END IF;
 SELECT * INTO c FROM public.uc_admission_cases WHERE id=p_case_id;SELECT * INTO r FROM public.uc_admission_evidence_reservations WHERE id=p_reservation_id AND case_id=c.id AND actor_id=p_actor_id;IF r.id IS NULL THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
 PERFORM public.uc_admission_lock(p_actor_id,c.organization_id,c.user_id,c.group_id,c.enrollment_id,c.responsible_id);SELECT * INTO c FROM public.uc_admission_cases WHERE id=p_case_id FOR UPDATE;SELECT * INTO r FROM public.uc_admission_evidence_reservations WHERE id=p_reservation_id FOR UPDATE;
 IF r.expected_revision IS DISTINCT FROM p_expected_revision OR c.revision IS DISTINCT FROM p_expected_revision THEN PERFORM public.uc_admission_error('REVISION_CONFLICT');END IF;IF c.revision>=9007199254740991 THEN PERFORM public.uc_admission_error('LIMIT_REACHED');END IF;
 IF r.state NOT IN('prepared','sealed')OR r.expires_at<=clock_timestamp()THEN PERFORM public.uc_admission_error('SOURCE_UNAVAILABLE');END IF;
 IF c.program_ref IS DISTINCT FROM r.program_ref OR c.program_ref IS DISTINCT FROM public.uc_admission_program(c.organization_id,c.user_id,c.group_id,c.enrollment_id)THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;
 PERFORM public.uc_admission_lock_source(r.id);src:=public.uc_admission_source_proof(r.id,p_actor_id);
 IF src IS NULL OR(src->>'object_id')::uuid IS DISTINCT FROM p_source_object_id OR(src->>'updated_at')::timestamptz IS DISTINCT FROM p_source_updated_at OR src->>'fingerprint'IS DISTINCT FROM p_source_fingerprint OR(src->>'byte_size')::bigint IS DISTINCT FROM p_byte_size OR src->>'mime_type'IS DISTINCT FROM p_mime_type OR(src->>'known_sha256'IS NOT NULL AND src->>'known_sha256'<>p_byte_sha256)THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;
 BEGIN PERFORM 1 FROM storage.objects WHERE id=p_sealed_object_id FOR SHARE NOWAIT;EXCEPTION WHEN lock_not_available THEN PERFORM public.uc_admission_error('REVISION_CONFLICT');END;
 obj:=public.uc_admission_object('admission-case-evidence',r.user_id::text||'/'||r.organization_id::text||'/'||r.case_id::text||'/sealed/'||r.evidence_version_id::text,p_byte_sha256);
 IF r.expires_at<=clock_timestamp()THEN PERFORM public.uc_admission_error('SOURCE_UNAVAILABLE');END IF;
 IF obj IS NULL OR(obj->>'object_id')::uuid IS DISTINCT FROM p_sealed_object_id OR(obj->>'updated_at')::timestamptz IS DISTINCT FROM p_sealed_updated_at OR(obj->>'byte_size')::bigint IS DISTINCT FROM p_byte_size OR obj->>'mime_type'IS DISTINCT FROM p_mime_type THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;
 sealed:=jsonb_build_object('bucket','admission-case-evidence','path',obj->'path','object_id',p_sealed_object_id,'updated_at',p_sealed_updated_at,'byte_sha256',p_byte_sha256,'byte_size',p_byte_size,'mime_type',p_mime_type);
 IF r.state='sealed'THEN IF r.source_proof IS DISTINCT FROM src OR r.sealed_proof IS DISTINCT FROM sealed OR r.commit_request_id IS DISTINCT FROM p_request_id THEN PERFORM public.uc_admission_error('REVISION_CONFLICT');END IF;
 ELSE ctx:=public.uc_admission_context(c.id,p_actor_id,'attest');UPDATE public.uc_admission_evidence_reservations SET state='sealed',source_proof=src,sealed_proof=sealed,commit_request_id=p_request_id WHERE id=r.id;DELETE FROM public.uc_admission_case_requests WHERE actor_id=p_actor_id AND request_id=ctx AND kind='_context';END IF;
 RETURN jsonb_build_object('schema_version',1,'case_id',c.id,'reservation_id',r.id,'evidence_version_id',r.evidence_version_id,'state','sealed','byte_sha256',p_byte_sha256,'byte_size',p_byte_size,'mime_type',p_mime_type);END;$function$

CREATE OR REPLACE FUNCTION public.uc_erase_admission_cases(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE cid uuid;t text;r record;redacted jsonb;ctx uuid;force boolean;BEGIN
 IF auth.role()IS DISTINCT FROM 'service_role'OR auth.uid()IS NOT NULL OR current_setting('sintagma.account_deletion_erase_user',true)IS DISTINCT FROM p_user::text OR NOT EXISTS(SELECT 1 FROM public.account_deletion_revocations WHERE user_id=p_user)THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
 -- Never acquire other subjects'/reviewers' account advisory locks here.
 -- Sort the complete parent union before touching any registry child.
 FOR cid IN SELECT c.id FROM public.uc_admission_cases c WHERE c.user_id=p_user OR c.responsible_id=p_user OR c.reviews::text LIKE '%'||p_user::text||'%'OR c.decision::text LIKE '%'||p_user::text||'%'OR c.tasks::text LIKE '%'||p_user::text||'%'
 OR EXISTS(SELECT 1 FROM public.uc_admission_case_events e WHERE e.case_id=c.id AND(e.actor_id=p_user OR e.payload::text LIKE '%'||p_user::text||'%'OR e.authority_snapshot::text LIKE '%'||p_user::text||'%'))
 OR EXISTS(SELECT 1 FROM public.uc_admission_rule_sets s WHERE s.case_id=c.id AND(s.reviewer_id=p_user OR s.authority_snapshot::text LIKE '%'||p_user::text||'%'))
 OR EXISTS(SELECT 1 FROM public.uc_admission_case_evidence e WHERE e.case_id=c.id AND(e.captured_by=p_user OR p_user=ANY(e.participant_ids)))
 OR EXISTS(SELECT 1 FROM public.uc_admission_case_requests q WHERE q.case_id=c.id AND q.actor_id=p_user)
 OR EXISTS(SELECT 1 FROM public.uc_admission_evidence_reservations q WHERE q.case_id=c.id AND q.actor_id=p_user)ORDER BY c.id LOOP PERFORM 1 FROM public.uc_admission_cases WHERE id=cid FOR UPDATE;END LOOP;
 FOR cid IN SELECT c.id FROM public.uc_admission_cases c WHERE c.user_id=p_user OR c.responsible_id=p_user OR c.reviews::text LIKE '%'||p_user::text||'%'OR c.decision::text LIKE '%'||p_user::text||'%'OR c.tasks::text LIKE '%'||p_user::text||'%'
 OR EXISTS(SELECT 1 FROM public.uc_admission_case_events e WHERE e.case_id=c.id AND(e.actor_id=p_user OR e.payload::text LIKE '%'||p_user::text||'%'OR e.authority_snapshot::text LIKE '%'||p_user::text||'%'))
 OR EXISTS(SELECT 1 FROM public.uc_admission_rule_sets s WHERE s.case_id=c.id AND(s.reviewer_id=p_user OR s.authority_snapshot::text LIKE '%'||p_user::text||'%'))
 OR EXISTS(SELECT 1 FROM public.uc_admission_case_evidence e WHERE e.case_id=c.id AND(e.captured_by=p_user OR p_user=ANY(e.participant_ids)))
 OR EXISTS(SELECT 1 FROM public.uc_admission_case_requests q WHERE q.case_id=c.id AND q.actor_id=p_user)
 OR EXISTS(SELECT 1 FROM public.uc_admission_evidence_reservations q WHERE q.case_id=c.id AND q.actor_id=p_user)ORDER BY c.id LOOP
  ctx:=public.uc_admission_context(cid,p_user,'reviewer_erase',p_user);
  DELETE FROM public.uc_admission_evidence_reservations WHERE case_id=cid AND(actor_id=p_user OR user_id=p_user);
  DELETE FROM public.uc_admission_case_requests WHERE case_id=cid AND kind<>'_context'AND(actor_id=p_user OR user_id=p_user);
  IF EXISTS(SELECT 1 FROM public.uc_admission_cases WHERE id=cid AND user_id=p_user)THEN
   DELETE FROM public.uc_admission_case_evidence WHERE case_id=cid;DELETE FROM public.uc_admission_case_events WHERE case_id=cid;DELETE FROM public.uc_admission_rule_sets WHERE case_id=cid;
   DELETE FROM public.uc_admission_cases WHERE id=cid;DELETE FROM public.uc_admission_case_requests WHERE actor_id=p_user AND request_id=ctx AND kind='_context';
  ELSE
   SELECT EXISTS(SELECT 1 FROM public.uc_admission_cases c JOIN public.uc_admission_rule_sets s ON s.id=c.rule_set_id WHERE c.id=cid AND s.reviewer_id=p_user)INTO force;
   FOREACH t IN ARRAY ARRAY['uc_admission_cases','uc_admission_rule_sets','uc_admission_case_events','uc_admission_case_evidence']LOOP
    FOR r IN EXECUTE format('SELECT to_jsonb(x)old_row FROM public.%I x WHERE %s=$1',t,CASE WHEN t='uc_admission_cases'THEN 'id'ELSE 'case_id'END)USING cid LOOP
     redacted:=public.uc_admission_redact(r.old_row,p_user,(t='uc_admission_cases'AND force)OR(t='uc_admission_rule_sets'AND r.old_row->>'reviewer_id'=p_user::text)OR(t='uc_admission_case_events'AND r.old_row->>'actor_id'=p_user::text));
     IF redacted IS DISTINCT FROM r.old_row THEN
      -- Full typed-row equality is rechecked by the private erasure guard.
      EXECUTE format('UPDATE public.%I x SET(%s)=(SELECT %s FROM jsonb_populate_record(NULL::public.%I,$1))WHERE id=$2',t,
       (SELECT string_agg(quote_ident(attname),','ORDER BY attnum)FROM pg_attribute WHERE attrelid=('public.'||t)::regclass AND attnum>0 AND NOT attisdropped),
       (SELECT string_agg(quote_ident(attname),','ORDER BY attnum)FROM pg_attribute WHERE attrelid=('public.'||t)::regclass AND attnum>0 AND NOT attisdropped),t)USING redacted,(r.old_row->>'id')::uuid;
     END IF;
    END LOOP;
   END LOOP;
   DELETE FROM public.uc_admission_case_requests WHERE actor_id=p_user AND request_id=ctx AND kind='_context';
  END IF;
 END LOOP;
END;$function$

CREATE OR REPLACE FUNCTION public.uc_finalize_admission_case_evidence(p_case_id uuid, p_reservation_id uuid, p_expected_revision bigint, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a uuid:=auth.uid();c public.uc_admission_cases;r public.uc_admission_evidence_reservations;context jsonb;ctx uuid;event uuid:=gen_random_uuid();digest text;receipt jsonb;BEGIN
 context:=public.uc_admission_evidence_context(p_case_id,p_reservation_id,p_expected_revision,p_request_id);
 IF context->>'mode'='consumed'THEN RETURN context->'replay_result';END IF;
 SELECT * INTO c FROM public.uc_admission_cases WHERE id=p_case_id;PERFORM public.uc_admission_lock(a,c.organization_id,c.user_id,c.group_id,c.enrollment_id,c.responsible_id);
 PERFORM pg_advisory_xact_lock(hashtextextended('uc_admission_request:'||a::text||':'||p_request_id::text,0));SELECT * INTO c FROM public.uc_admission_cases WHERE id=p_case_id FOR UPDATE;SELECT * INTO r FROM public.uc_admission_evidence_reservations WHERE id=p_reservation_id FOR UPDATE;
 context:=public.uc_admission_evidence_context(p_case_id,p_reservation_id,p_expected_revision,p_request_id);IF context->>'mode'='consumed'THEN RETURN context->'replay_result';END IF;
 IF r.state<>'sealed'THEN PERFORM public.uc_admission_error('REVIEW_REQUIRED');END IF;PERFORM public.uc_admission_lock_source(r.id);
 context:=public.uc_admission_evidence_context(p_case_id,p_reservation_id,p_expected_revision,p_request_id);
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c.requirements)x WHERE x->>'id'=r.requirement_id::text)OR(r.supersedes_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.uc_admission_case_evidence e WHERE e.id=r.supersedes_id AND e.case_id=c.id AND e.requirement_id=r.requirement_id AND NOT EXISTS(SELECT 1 FROM public.uc_admission_case_evidence n WHERE n.case_id=c.id AND n.supersedes_id=e.id)))THEN PERFORM public.uc_admission_error('SOURCE_CHANGED');END IF;
 IF EXISTS(SELECT 1 FROM public.uc_admission_case_requests WHERE actor_id=a AND request_id=p_request_id)THEN PERFORM public.uc_admission_error('REVISION_CONFLICT');END IF;
 ctx:=public.uc_admission_context(c.id,a,'mutation');
 INSERT INTO public.uc_admission_case_evidence(id,case_id,organization_id,user_id,requirement_id,case_revision_created,supersedes_id,source_kind,source_snapshot,participant_ids,captured_by,byte_sha256,byte_size,mime_type,storage_object_id,object_updated_at,sealed_path,event_id)VALUES(r.evidence_version_id,c.id,c.organization_id,c.user_id,r.requirement_id,c.revision+1,r.supersedes_id,CASE WHEN r.source->>'kind'='upload'THEN 'upload'ELSE r.source->'candidate'->>'kind'END,jsonb_build_object('declaration',r.source,'proof',r.source_proof),ARRAY[c.user_id],a,r.sealed_proof->>'byte_sha256',(r.sealed_proof->>'byte_size')::bigint,r.sealed_proof->>'mime_type',(r.sealed_proof->>'object_id')::uuid,(r.sealed_proof->>'updated_at')::timestamptz,r.sealed_proof->>'path',event);
 UPDATE public.uc_admission_cases SET revision=revision+1,updated_at=clock_timestamp()WHERE id=c.id;UPDATE public.uc_admission_evidence_reservations SET state='consumed'WHERE id=r.id;PERFORM public.uc_admission_refresh(c.id);
 digest:=public.uc_program_hash(jsonb_build_object('case_id',c.id,'reservation_id',r.id,'expected_revision',p_expected_revision));receipt:=public.uc_admission_event(c.id,a,event,'evidence_committed',p_request_id,digest,NULL);
 DELETE FROM public.uc_admission_case_requests WHERE actor_id=a AND request_id=ctx AND kind='_context';RETURN public.uc_admission_result(c.id,a,receipt,false);END;$function$

CREATE OR REPLACE FUNCTION public.uc_guard_admission_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE ctx record;c public.uc_admission_cases;cid uuid:=coalesce((to_jsonb(OLD)->>'case_id')::uuid,(to_jsonb(OLD)->'receipt'->>'case_id')::uuid);mode text;erase_user uuid;BEGIN
 IF TG_TABLE_NAME='uc_admission_cases'THEN cid:=OLD.id;END IF;SELECT * INTO c FROM public.uc_admission_cases WHERE id=cid;
 FOR ctx IN SELECT * FROM public.uc_admission_case_requests q WHERE q.kind='_context'AND q.receipt->>'case_id'=cid::text AND(q.receipt->>'pid')::integer=pg_backend_pid()AND(q.receipt->>'tx')::bigint=txid_current()LOOP
  mode:=ctx.receipt->>'mode';erase_user:=(ctx.receipt->>'erase_user')::uuid;
  IF mode IN('subject_erase','reviewer_erase')AND auth.role()='service_role'AND auth.uid()IS NULL AND current_setting('sintagma.account_deletion_erase_user',true)=erase_user::text AND EXISTS(SELECT 1 FROM public.account_deletion_revocations WHERE user_id=erase_user)THEN
   IF TG_OP='DELETE'AND(TG_TABLE_NAME='uc_admission_case_requests'AND(to_jsonb(OLD)->>'actor_id'=erase_user::text OR to_jsonb(OLD)->>'user_id'=erase_user::text OR to_jsonb(OLD)->>'kind'='_context')OR to_jsonb(OLD)->>'user_id'=erase_user::text OR TG_TABLE_NAME='uc_admission_evidence_reservations'AND to_jsonb(OLD)->>'actor_id'=erase_user::text)THEN RETURN OLD;END IF;
   IF mode='reviewer_erase'AND TG_OP='UPDATE'AND to_jsonb(NEW)=public.uc_admission_redact(to_jsonb(OLD),erase_user,(TG_TABLE_NAME IN('uc_admission_rule_sets','uc_admission_case_events')AND(to_jsonb(OLD)->>'reviewer_id'=erase_user::text OR to_jsonb(OLD)->>'actor_id'=erase_user::text))OR(TG_TABLE_NAME='uc_admission_cases'AND EXISTS(SELECT 1 FROM public.uc_admission_rule_sets s WHERE s.id=(to_jsonb(OLD)->>'rule_set_id')::uuid AND s.reviewer_id=erase_user)))THEN RETURN NEW;END IF;
  ELSIF mode IN('mutation','attest')AND((mode='mutation'AND auth.role()='authenticated'AND auth.uid()=ctx.actor_id)OR(mode='attest'AND auth.role()='service_role'AND auth.uid()IS NULL))AND public.uc_admission_staff_allowed(ctx.actor_id,c.organization_id,c.user_id,c.group_id,c.enrollment_id,true)AND public.uc_admission_staff_allowed(ctx.actor_id,c.organization_id,c.user_id,c.group_id,c.enrollment_id,false)THEN
   IF TG_OP='DELETE'AND TG_TABLE_NAME='uc_admission_case_requests'AND to_jsonb(OLD)->>'kind'='_context'AND to_jsonb(OLD)->>'actor_id'=ctx.actor_id::text AND to_jsonb(OLD)->>'request_id'=ctx.request_id::text THEN RETURN OLD;END IF;
   IF TG_OP='UPDATE'AND TG_TABLE_NAME='uc_admission_evidence_reservations'AND(to_jsonb(OLD)-ARRAY['state','source_proof','sealed_proof','commit_request_id'])=(to_jsonb(NEW)-ARRAY['state','source_proof','sealed_proof','commit_request_id'])AND to_jsonb(OLD)->>'actor_id'=ctx.actor_id::text THEN RETURN NEW;END IF;
   IF mode='mutation'AND TG_OP='UPDATE'AND TG_TABLE_NAME='uc_admission_cases'AND(to_jsonb(OLD)-ARRAY['revision','responsible_id','rule_set_id','requirements','reviews','tasks','decision','updated_at'])=(to_jsonb(NEW)-ARRAY['revision','responsible_id','rule_set_id','requirements','reviews','tasks','decision','updated_at'])THEN RETURN NEW;END IF;
  END IF;
 END LOOP;PERFORM public.uc_admission_error('ACCESS_DENIED');RETURN NULL;END;$function$

CREATE OR REPLACE FUNCTION public.uc_guard_admission_storage()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o jsonb:=CASE WHEN TG_OP='DELETE'THEN to_jsonb(OLD)ELSE to_jsonb(NEW)END;r public.uc_admission_evidence_reservations;c public.uc_admission_cases;BEGIN
 IF TG_OP='UPDATE'AND(OLD.bucket_id='admission-case-evidence'OR NEW.bucket_id='admission-case-evidence')THEN PERFORM public.uc_admission_error('ACCESS_DENIED');END IF;
 IF o->>'bucket_id'<>'admission-case-evidence'THEN RETURN CASE WHEN TG_OP='DELETE'THEN OLD ELSE NEW END;END IF;
 IF TG_OP='INSERT'THEN
  IF auth.role()='authenticated'AND public.uc_admission_stage_allowed(NEW.bucket_id,NEW.name,true)AND coalesce(to_jsonb(NEW)->>'owner_id',to_jsonb(NEW)->>'owner')=auth.uid()::text THEN RETURN NEW;END IF;
  IF auth.role()='service_role'AND auth.uid()IS NULL THEN
   SELECT * INTO r FROM public.uc_admission_evidence_reservations q WHERE NEW.name=q.user_id::text||'/'||q.organization_id::text||'/'||q.case_id::text||'/sealed/'||q.evidence_version_id::text AND q.state IN('prepared','sealed')AND q.expires_at>clock_timestamp();SELECT * INTO c FROM public.uc_admission_cases WHERE id=r.case_id;
   IF r.id IS NOT NULL AND c.revision=r.expected_revision AND public.uc_admission_staff_allowed(r.actor_id,c.organization_id,c.user_id,c.group_id,c.enrollment_id,true)AND public.uc_admission_staff_allowed(r.actor_id,c.organization_id,c.user_id,c.group_id,c.enrollment_id,false)AND c.program_ref=public.uc_admission_program(c.organization_id,c.user_id,c.group_id,c.enrollment_id)AND NOT EXISTS(SELECT 1 FROM public.uc_admission_case_evidence e WHERE e.id=r.evidence_version_id)THEN RETURN NEW;END IF;
  END IF;
 ELSIF TG_OP='DELETE'AND auth.role()='service_role'AND auth.uid()IS NULL THEN
  -- The confirmed job snapshot is the explicit exact file plan. Unlike a GUC,
  -- this private row remains valid for the separate Storage cleanup request.
  IF EXISTS(SELECT 1 FROM public.account_deletion_jobs j,jsonb_array_elements(j.files)f WHERE j.state='cleanup_pending'AND EXISTS(SELECT 1 FROM public.account_deletion_revocations v WHERE v.user_id=j.user_id)AND(split_part(OLD.name,'/',1)=j.user_id::text OR split_part(OLD.name,'/',4)='staging'AND split_part(OLD.name,'/',5)=j.user_id::text)AND f->>'bucket'=OLD.bucket_id AND f->>'path'=OLD.name AND f->>'objectId'=OLD.id::text AND(f->>'updatedAt')::timestamptz=OLD.updated_at)THEN RETURN OLD;END IF;
  IF NOT EXISTS(SELECT 1 FROM public.uc_admission_case_evidence e WHERE e.storage_object_id=OLD.id OR e.sealed_path=OLD.name)AND EXISTS(SELECT 1 FROM public.uc_admission_evidence_reservations q WHERE q.state<>'consumed'AND q.expires_at<=clock_timestamp()AND(OLD.name=q.user_id::text||'/'||q.organization_id::text||'/'||q.case_id::text||'/sealed/'||q.evidence_version_id::text OR OLD.name=q.user_id::text||'/'||q.organization_id::text||'/'||q.case_id::text||'/staging/'||q.actor_id::text||'/'||q.id::text))THEN RETURN OLD;END IF;
 END IF;PERFORM public.uc_admission_error('ACCESS_DENIED');RETURN NULL;END;$function$

CREATE OR REPLACE FUNCTION public.commit_org_document_version(p_document_id uuid, p_organization_id uuid, p_request_id uuid, p_expected_revision bigint, p_upload jsonb DEFAULT NULL::jsonb, p_restore_version_id uuid DEFAULT NULL::uuid, p_document jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  d public.org_documents%ROWTYPE;
  v public.org_document_versions%ROWTYPE;
  source_version public.org_document_versions%ROWTYPE;
  payload jsonb;
  meta jsonb;
  v_id uuid;
  next_number integer;
  v_path text; v_url text; v_name text; v_size bigint; v_summary text;
  actor_name text;
  v_origin text;
  v_object_id uuid;
  v_storage_metadata jsonb;
  v_actual_size bigint;
BEGIN
  IF auth.uid() IS NULL OR NOT public.account_deletion_access_allowed()
    OR NOT public.can_access_organization(p_organization_id,'documents.write') THEN
    RAISE EXCEPTION 'Document write permission required' USING ERRCODE='42501';
  END IF;
  IF p_document_id IS NULL OR p_organization_id IS NULL OR p_request_id IS NULL
    OR p_expected_revision IS NULL OR p_expected_revision<0
    OR jsonb_typeof(p_document) IS DISTINCT FROM 'object'
    OR (p_upload IS NULL) = (p_restore_version_id IS NULL) THEN
    RAISE EXCEPTION 'Invalid version operation' USING ERRCODE='22023';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_document) k
    WHERE k NOT IN ('name','type','issue_date','expires_at','responsible_person','status')) THEN
    RAISE EXCEPTION 'Unsupported document field' USING ERRCODE='22023';
  END IF;
  IF p_document ? 'status' AND (p_document->>'status') NOT IN ('active','archived','expired') THEN
    RAISE EXCEPTION 'Invalid document status' USING ERRCODE='22023';
  END IF;
  payload:=jsonb_build_object('document_id',p_document_id,'organization_id',p_organization_id,
    'expected_revision',p_expected_revision,'upload',p_upload,'restore_version_id',p_restore_version_id,'document',p_document);
  -- Serialize a request before checking replay, then serialize the document.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_request_id::text,610181020));
  SELECT * INTO v FROM public.org_document_versions WHERE request_id=p_request_id;
  IF FOUND THEN
    IF v.organization_id<>p_organization_id OR v.document_id<>p_document_id OR v.request_payload IS DISTINCT FROM payload THEN
      RAISE EXCEPTION 'Request identifier already used for another operation' USING ERRCODE='22023';
    END IF;
    RETURN jsonb_build_object('document_id',v.document_id,'revision',v.result_revision,
      'version_id',v.id,'version_number',v.version_number,'replayed',true);
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_document_id::text,610181021));
  SELECT * INTO d FROM public.org_documents WHERE id=p_document_id FOR UPDATE;
  IF FOUND THEN
    IF d.organization_id<>p_organization_id THEN RAISE EXCEPTION 'Document organization mismatch' USING ERRCODE='42501'; END IF;
    IF d.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'Document is in the recycle bin' USING ERRCODE='22023'; END IF;
    IF d.document_revision<>p_expected_revision THEN RAISE EXCEPTION 'Document changed; reload before replacing it' USING ERRCODE='40001'; END IF;
    IF p_document ? 'type' AND p_document->>'type' IS DISTINCT FROM d.type THEN
      RAISE EXCEPTION 'Document type cannot be changed during replacement' USING ERRCODE='22023';
    END IF;
  ELSE
    IF p_expected_revision<>0 OR p_restore_version_id IS NOT NULL
      OR nullif(btrim(p_document->>'name'),'') IS NULL OR nullif(btrim(p_document->>'type'),'') IS NULL THEN
      RAISE EXCEPTION 'New document name and type are required' USING ERRCODE='22023';
    END IF;
    -- Required catalogue rows are single-current-entry types. No destructive
    -- unique backfill: existing duplicates remain visible for manual review.
    IF p_document->>'type' IN ('charter','license','registration','admission_rules','edu_activity_order',
      'attestation_rules','edu_relations','expulsion_rules','program_dev_rules','vsoko','elearning_rules',
      'practice_rules','qualification_issuance','credit_rules','salary_rules','pedagogical_council',
      'paid_services','personal_data','electronic_docs_rules','program_approval','schedule_approval',
      'commission_orders','doc_forms_approval','electronic_docs_order','self_examination_report') THEN
      PERFORM pg_advisory_xact_lock(hashtextextended(p_organization_id::text||':'||(p_document->>'type'),610181022));
      IF EXISTS(SELECT 1 FROM public.org_documents WHERE organization_id=p_organization_id
        AND type=p_document->>'type' AND deleted_at IS NULL) THEN
        RAISE EXCEPTION 'Document already exists; reload before replacing it' USING ERRCODE='40001';
      END IF;
    END IF;
    INSERT INTO public.org_documents(id,organization_id,name,type,file_url)
      VALUES(p_document_id,p_organization_id,p_document->>'name',p_document->>'type',NULL) RETURNING * INTO d;
  END IF;
  meta:=jsonb_build_object('name',d.name,'type',d.type,'issue_date',d.issue_date,
    'expires_at',d.expires_at,'responsible_person',d.responsible_person);
  IF p_restore_version_id IS NOT NULL THEN
    SELECT * INTO source_version FROM public.org_document_versions
      WHERE id=p_restore_version_id AND document_id=d.id AND organization_id=d.organization_id;
    IF NOT FOUND OR nullif(btrim(source_version.file_url),'') IS NULL THEN
      RAISE EXCEPTION 'Restorable version not found' USING ERRCODE='22023';
    END IF;
    v_path:=source_version.file_path;v_url:=source_version.file_url;v_name:=source_version.file_name;v_size:=source_version.file_size;
    v_object_id:=source_version.storage_object_id;v_storage_metadata:=source_version.storage_metadata;
    v_summary:='Восстановлен файл версии №'||source_version.version_number;
    meta:=meta||coalesce(source_version.document_metadata,'{}'::jsonb);
  ELSE
    IF jsonb_typeof(p_upload) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Upload details required' USING ERRCODE='22023'; END IF;
    v_path:=p_upload->>'file_path';v_name:=p_upload->>'file_name';
    v_size:=(p_upload->>'file_size')::bigint;v_summary:=nullif(btrim(p_upload->>'change_summary'),'');
    -- PostgREST supplies claims from the verified user JWT, not a request body.
    v_origin:=auth.jwt()->>'iss';
    IF v_origin IS NULL OR v_origin !~ '^https://[a-zA-Z0-9.-]+(:[0-9]+)?/auth/v1/?$' THEN
      RAISE EXCEPTION 'Verified Storage origin unavailable' USING ERRCODE='22023';
    END IF;
    v_origin:=regexp_replace(v_origin,'/auth/v1/?$','');
    v_url:=v_origin||'/storage/v1/object/public/org-documents/'||v_path;
    IF v_path IS NULL OR v_path !~ ('^'||p_organization_id::text||'/versions/'||p_document_id::text||'/'||p_request_id::text||'\.[a-z0-9]{1,12}$')
      OR v_size IS NULL OR v_size<0 OR nullif(btrim(v_name),'') IS NULL THEN
      RAISE EXCEPTION 'Invalid staged file' USING ERRCODE='22023';
    END IF;
    SELECT id,metadata INTO v_object_id,v_storage_metadata FROM storage.objects
      WHERE bucket_id='org-documents' AND name=v_path FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Staged file not found' USING ERRCODE='22023';
    END IF;
    IF coalesce(v_storage_metadata->>'size','') !~ '^[0-9]+$' THEN
      RAISE EXCEPTION 'Staged file size unavailable' USING ERRCODE='22023';
    END IF;
    v_actual_size:=(v_storage_metadata->>'size')::bigint;
    IF v_size<>v_actual_size THEN RAISE EXCEPTION 'Staged file size mismatch' USING ERRCODE='22023'; END IF;
    v_storage_metadata:=jsonb_build_object('size',v_actual_size,'etag',coalesce(v_storage_metadata->>'eTag',v_storage_metadata->>'etag'),
      'mimetype',v_storage_metadata->>'mimetype');
  END IF;
  meta:=meta||(p_document-'status');
  IF nullif(btrim(meta->>'name'),'') IS NULL THEN RAISE EXCEPTION 'Document name required' USING ERRCODE='22023'; END IF;
  IF nullif(meta->>'expires_at','')::date < nullif(meta->>'issue_date','')::date THEN
    RAISE EXCEPTION 'Expiry precedes issue date' USING ERRCODE='22023';
  END IF;
  SELECT full_name INTO actor_name FROM public.profiles WHERE user_id=auth.uid() LIMIT 1;
  INSERT INTO public.org_document_write_tokens VALUES(d.id,txid_current());
  SELECT coalesce(max(version_number),0)+1 INTO next_number FROM public.org_document_versions WHERE document_id=d.id;
  IF d.current_version_id IS NULL AND nullif(btrim(d.file_url),'') IS NOT NULL THEN
    INSERT INTO public.org_document_versions(document_id,organization_id,version_number,file_url,event_kind,change_summary,
      uploaded_by,uploaded_by_name,document_metadata)
    VALUES(d.id,d.organization_id,next_number,d.file_url,'baseline',
      'Снимок предыдущего файла на дату операции. Исходная дата и автор загрузки неизвестны.',auth.uid(),actor_name,
      jsonb_build_object('name',d.name,'type',d.type,'issue_date',d.issue_date,'expires_at',d.expires_at,'responsible_person',d.responsible_person));
    next_number:=next_number+1;
  END IF;
  INSERT INTO public.org_document_versions(document_id,organization_id,version_number,file_url,file_path,file_name,file_size,
    change_summary,uploaded_by,uploaded_by_name,event_kind,restored_from_version_id,request_id,request_payload,result_revision,document_metadata,storage_object_id,storage_metadata)
  VALUES(d.id,d.organization_id,next_number,v_url,v_path,v_name,v_size,v_summary,auth.uid(),actor_name,
    CASE WHEN p_restore_version_id IS NULL THEN 'upload' ELSE 'restore' END,p_restore_version_id,p_request_id,
    payload,d.document_revision+1,meta,v_object_id,v_storage_metadata) RETURNING id INTO v_id;
  UPDATE public.org_documents SET file_url=v_url,current_version_id=v_id,document_revision=d.document_revision+1,
    name=meta->>'name',issue_date=nullif(meta->>'issue_date','')::date,expires_at=nullif(meta->>'expires_at','')::date,
    responsible_person=nullif(btrim(meta->>'responsible_person'),''),
    status=coalesce(p_document->>'status',d.status,'active'),reminder_sent_at=NULL
    WHERE id=d.id;
  DELETE FROM public.org_document_write_tokens WHERE document_id=d.id AND transaction_id=txid_current();
  RETURN jsonb_build_object('document_id',d.id,'revision',d.document_revision+1,
    'version_id',v_id,'version_number',next_number,'replayed',false);
END $function$

CREATE OR REPLACE FUNCTION public.account_deletion_storage_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE target_text text; target_id uuid;
BEGIN
 IF NEW.bucket_id IN ('avatars','student-documents','final-test-photos','student-identification-media','admission-case-evidence') THEN
  target_text:=split_part(NEW.name,'/',1);
  IF NEW.bucket_id='student-documents' AND target_text='avatars' THEN
   target_text:=split_part(split_part(NEW.name,'/',2),'.',1);
  END IF;
 ELSIF NEW.bucket_id='chat-attachments' THEN target_text:=split_part(NEW.name,'/',2);
 ELSE RETURN NEW; END IF;
 IF target_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN NEW; END IF;
 target_id:=target_text::uuid;
 PERFORM pg_advisory_xact_lock(hashtextextended(target_id::text,42007));
 IF EXISTS(SELECT 1 FROM public.account_deletion_revocations WHERE user_id=target_id) THEN
  RAISE EXCEPTION 'Account personal uploads are closed' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END;$function$

CREATE OR REPLACE FUNCTION public.account_deletion_subject_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE column_name text; target_id uuid; targets uuid[]; pep_targets uuid[];
BEGIN
 -- Sort locks to avoid deadlocks in two-person message rows.
 -- UPDATE may not move a revoked subject's data outside the deletion scope.
 SELECT array_agg(DISTINCT subject_id::uuid ORDER BY subject_id::uuid) INTO targets
 FROM unnest(TG_ARGV) c CROSS JOIN LATERAL (
  VALUES (to_jsonb(NEW)->>c),
         (CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD)->>c END)
 ) subjects(subject_id) WHERE subject_id IS NOT NULL;
 -- A signature may refer to a person's PEP agreement even if its party UUIDs
 -- differ. Keep that exact indirect relationship inside the same write fence.
 IF TG_TABLE_NAME='document_signatures' THEN
  SELECT array_agg(DISTINCT p.user_id) INTO pep_targets FROM public.pep_agreements p
  WHERE p.user_id IS NOT NULL AND p.id IN (
   (to_jsonb(NEW)->>'pep_agreement_id')::uuid,
   CASE WHEN TG_OP='UPDATE' THEN (to_jsonb(OLD)->>'pep_agreement_id')::uuid END);
  SELECT array_agg(DISTINCT x ORDER BY x) INTO targets
  FROM unnest(coalesce(targets,'{}'::uuid[])||coalesce(pep_targets,'{}'::uuid[])) x;
 END IF;
 FOREACH target_id IN ARRAY coalesce(targets,'{}'::uuid[]) LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended(target_id::text,42007));
  IF EXISTS(SELECT 1 FROM public.account_deletion_revocations WHERE user_id=target_id) THEN
   -- Only these two real DELETE-trigger event rows may be generated during
   -- service cleanup. The same transaction erases them at the tail. The flag
   -- is transaction-local and never bypasses profile/learning/document writes.
   IF TG_OP='INSERT' AND TG_TABLE_NAME IN ('enrollment_history','role_audit_log')
    AND auth.role()='service_role'
    AND current_setting('sintagma.account_deletion_erase_user',true)=target_id::text THEN CONTINUE; END IF;
   RAISE EXCEPTION 'Account personal data writes are closed' USING ERRCODE='42501';
  END IF;
 END LOOP;
 RETURN NEW;
END;$function$

CREATE OR REPLACE FUNCTION public.account_deletion_begin(p_user_id uuid, p_plan_hash text, p_consent_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE j public.account_deletion_jobs%ROWTYPE; s jsonb;
BEGIN
 IF p_consent_version IS DISTINCT FROM 'full-personal-data-v1' THEN RETURN jsonb_build_object('code','CONSENT_REQUIRED'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_user_id::text,42007));
 SELECT * INTO j FROM public.account_deletion_jobs WHERE user_id=p_user_id AND plan_hash=p_plan_hash FOR UPDATE;
 IF FOUND AND j.consent_version IS DISTINCT FROM p_consent_version THEN RETURN jsonb_build_object('code','CONSENT_REQUIRED'); END IF;
 IF NOT FOUND OR j.state<>'planned' OR j.expires_at<=clock_timestamp() THEN RETURN jsonb_build_object('code','PLAN_EXPIRED'); END IF;
 PERFORM 1 FROM auth.users WHERE id=p_user_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('code','PLAN_CHANGED'); END IF;
 PERFORM 1 FROM public.profiles WHERE user_id=p_user_id FOR UPDATE;
 PERFORM 1 FROM public.organizations WHERE id=(j.snapshot->>'organizationId')::uuid FOR UPDATE;
 s:=public.account_deletion_snapshot(p_user_id);
 IF s IS DISTINCT FROM j.snapshot OR jsonb_array_length(s->'blockers')>0 THEN RETURN jsonb_build_object('code','PLAN_CHANGED'); END IF;
 INSERT INTO public.account_deletion_revocations(user_id) VALUES(p_user_id);
 DELETE FROM public.student_login_tokens WHERE user_id=p_user_id;
 UPDATE public.account_deletion_jobs SET state='cleanup_pending' WHERE id=j.id;
 RETURN jsonb_build_object('requestId',j.id,'receiptHash',j.receipt_hash);
END;$function$

CREATE OR REPLACE FUNCTION public._paid_20260922_course_read(p_course_id uuid, p_allow_learner boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET row_security TO 'off'
AS $function$
DECLARE v_course public.courses%ROWTYPE; v_valid boolean;
BEGIN
 -- Legacy must remain neutral to every existing permissive/restrictive policy.
 IF NOT public._paid_20260922_course_scope(p_course_id) THEN RETURN true; END IF;
 IF auth.uid() IS NULL THEN RETURN false; END IF;
 IF EXISTS (SELECT 1 FROM public.profiles p WHERE p.user_id=auth.uid() AND p.blocked_at IS NOT NULL) THEN
   RETURN false;
 END IF;
 SELECT c.* INTO v_course FROM public.courses c WHERE c.id=p_course_id;
 IF NOT FOUND THEN RETURN false; END IF;
 -- Platform administration retains inspection of pending/invalid deliveries.
 IF public.has_role(auth.uid(),'admin'::public.app_role) THEN RETURN true; END IF;
 IF p_course_id=ANY(public._paid_20260922_original_ids()) THEN
   RETURN v_course.organization_id='4ac2c05a-d8b5-4e72-ba31-f2c743091d95'::uuid
      AND COALESCE(public.can_access_course(p_course_id,'courses.read'),false);
 END IF;
 -- Every descendant hop requires its own order tied to that parent listing.
 -- UNION (not UNION ALL) terminates cycles; scoped anchors cannot be reparented.
 WITH RECURSIVE ancestry AS (
   SELECT c.id,c.organization_id,c.source_course_id,c.source_order_id FROM public.courses c WHERE c.id=p_course_id
   UNION
   SELECT p.id,p.organization_id,p.source_course_id,p.source_order_id FROM public.courses p
   JOIN ancestry a ON p.id=a.source_course_id
 )
 SELECT EXISTS (
   SELECT 1 FROM ancestry a WHERE a.id=ANY(public._paid_20260922_original_ids())
     AND a.organization_id='4ac2c05a-d8b5-4e72-ba31-f2c743091d95'::uuid
     AND a.source_course_id IS NULL AND a.source_order_id IS NULL
 ) AND NOT EXISTS (
   SELECT 1 FROM ancestry a
   WHERE NOT a.id=ANY(public._paid_20260922_original_ids())
     AND NOT EXISTS (
       SELECT 1 FROM public.marketplace_orders mo
       JOIN public.marketplace_courses mc ON mc.id=mo.marketplace_course_id
       JOIN public.courses parent ON parent.id=a.source_course_id
       WHERE mo.id=a.source_order_id AND mo.buyer_type='organization'
         AND mo.status IN ('paid','completed') AND mo.paid_at IS NOT NULL
         AND mo.buyer_organization_id=a.organization_id
         AND mc.course_id=a.source_course_id
         AND (mc.organization_id=parent.organization_id OR
              (mc.organization_id IS NULL AND parent.organization_id='4ac2c05a-d8b5-4e72-ba31-f2c743091d95'::uuid))
     )
 ) INTO v_valid;
 IF NOT COALESCE(v_valid,false) THEN RETURN false; END IF;
 IF public.can_access_course(p_course_id,'courses.read') THEN RETURN true; END IF;
 RETURN COALESCE(p_allow_learner,false) AND v_course.is_published IS TRUE
   AND COALESCE(public.can_access_course_as_learner(p_course_id),false);
END
$function$

CREATE OR REPLACE FUNCTION public.apply_document_registry_action(p_org uuid, p_scope jsonb, p_expected_revision bigint, p_request_id uuid, p_action jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE v_group uuid;v_op text:=p_action->>'action';v_caps jsonb;v_head bigint;v_payload text;v_req public.uc_document_registry_requests;v_rec public.uc_document_registry_records;v_previous public.uc_document_registry_records;v_incoming public.incoming_documents;v_link public.uc_document_registry_incoming_sources;v_version public.org_document_versions;v_data jsonb;v_proof jsonb;v_old_proof jsonb;v_src jsonb;v_plan jsonb;v_result jsonb;v_people uuid[]:='{}';v_groups uuid[]:='{}';v_reason text;v_year integer;v_number integer;v_registration text;v_event text;v_link_revision bigint;v_link_hash text;v_company uuid;v_inn text;BEGIN
 v_group:=public.uc_document_registry_scope(p_org,p_scope);IF p_expected_revision IS NULL OR p_expected_revision<0 OR p_expected_revision>9007199254740991 OR p_request_id IS NULL OR jsonb_typeof(p_action)IS DISTINCT FROM'object'OR octet_length(p_action::text)>8388608 THEN PERFORM public.uc_document_registry_error('INVALID_INPUT');END IF;
 IF NOT coalesce(v_op IN('capture_incoming','register','register_incoming','correct','archive'),false)THEN PERFORM public.uc_document_registry_error('INVALID_INPUT');END IF;
 PERFORM public.uc_document_registry_fence(p_org,v_group,'{}',true,p_request_id);v_caps:=public.uc_document_registry_caps(p_org,v_group);
 IF (CASE v_op WHEN'capture_incoming'THEN NOT(v_caps->>'can_capture_incoming')::boolean WHEN'archive'THEN NOT(v_caps->>'can_archive')::boolean WHEN'register_incoming'THEN NOT(v_caps->>'can_register_incoming')::boolean WHEN'register'THEN NOT(v_caps->>'can_register')::boolean WHEN'correct'THEN NOT(v_caps->>'can_correct')::boolean ELSE true END) THEN PERFORM public.uc_document_registry_error('ACCESS_DENIED');END IF;
 INSERT INTO public.uc_document_registry_heads(organization_id)VALUES(p_org)ON CONFLICT DO NOTHING;SELECT revision INTO STRICT v_head FROM public.uc_document_registry_heads WHERE organization_id=p_org FOR UPDATE NOWAIT;
 v_payload:=public.uc_document_registry_hash(jsonb_build_object('organization_id',p_org,'scope',p_scope,'expected_revision',p_expected_revision,'action',p_action)::text);
 SELECT*INTO v_req FROM public.uc_document_registry_requests WHERE actor_id=auth.uid()AND request_id=p_request_id;
 IF v_req.request_id IS NOT NULL THEN
  IF v_req.payload_hash<>v_payload OR v_req.organization_id<>p_org OR v_req.scope<>p_scope THEN PERFORM public.uc_document_registry_error('REQUEST_MISMATCH');END IF;
  PERFORM public.uc_document_registry_fence(p_org,v_group,v_req.participant_ids,true,p_request_id);RETURN public.uc_document_registry_replay(p_org,p_scope,v_req,v_caps);
 END IF;
 IF v_op='capture_incoming'THEN
  IF NOT public.uc_custom_journal_shape(p_action,ARRAY['action','data'])OR p_expected_revision<>0 THEN PERFORM public.uc_document_registry_error('INVALID_INPUT');END IF;v_data:=p_action->'data';v_proof:=public.uc_document_registry_capture_data(p_org,v_data);
  SELECT coalesce(array_agg(x::uuid),'{}')INTO v_people FROM jsonb_array_elements_text(v_proof->'participants')x;PERFORM public.uc_document_registry_fence(p_org,v_group,v_people,true,p_request_id);PERFORM public.uc_document_registry_source_lock(p_org,v_data->'source',true);
  SELECT*INTO STRICT v_version FROM public.org_document_versions WHERE id=(v_data->'source'->>'version_id')::uuid AND document_id=(v_data->'source'->>'document_id')::uuid AND organization_id=p_org;
  INSERT INTO public.incoming_documents(organization_id,doc_type,title,counterparty_name,counterparty_inn,doc_number,doc_date,file_url,file_path,file_size,notes,uploaded_by)
   VALUES(p_org,v_data->>'doc_type',v_data->>'title',v_data->>'counterparty_name',v_data->>'counterparty_inn',v_data->>'doc_number',(v_data->>'doc_date')::date,v_version.file_path,v_version.file_path,v_version.file_size,v_data->>'notes',v_version.uploaded_by)RETURNING*INTO v_incoming;
  v_people:=array_append(v_people,auth.uid());v_link_hash:=public.uc_document_registry_hash(jsonb_build_object('organization_id',p_org,'incoming_document_id',v_incoming.id,'source',v_data->'source','revision',1)::text);
  INSERT INTO public.uc_document_registry_incoming_sources(incoming_document_id,organization_id,source,binding_hash,participant_ids,linked_by,updated_by)VALUES(v_incoming.id,p_org,v_data->'source',v_link_hash,v_people,auth.uid(),auth.uid());
  v_result:=jsonb_build_object('incoming',public.uc_document_registry_incoming_json(v_incoming,v_group,v_caps));
 ELSIF v_op IN('register','register_incoming')THEN
  IF p_expected_revision<>0 OR NOT public.uc_document_registry_text(p_action->'reason',2000)THEN PERFORM public.uc_document_registry_error('INVALID_INPUT');END IF;v_reason:=p_action->>'reason';
  IF v_op='register'THEN IF NOT public.uc_custom_journal_shape(p_action,ARRAY['action','data','reason'])THEN PERFORM public.uc_document_registry_error('INVALID_INPUT');END IF;v_data:=p_action->'data';IF v_data->>'direction'IS DISTINCT FROM'outgoing'OR v_data->'origin'->>'kind'='incoming_document'THEN PERFORM public.uc_document_registry_error('INVALID_INPUT');END IF;
  ELSE IF NOT public.uc_custom_journal_shape(p_action,ARRAY['action','incoming','data','reason'])THEN PERFORM public.uc_document_registry_error('INVALID_INPUT');END IF;v_plan:=public.uc_document_registry_incoming_plan(p_org,v_group,p_action->'incoming',p_action->'data');v_data:=v_plan->'data';
   IF p_action->'incoming'->>'kind'='existing'THEN SELECT*INTO STRICT v_incoming FROM public.incoming_documents WHERE id=(p_action->'incoming'->>'incoming_document_id')::uuid AND organization_id=p_org AND deleted_at IS NULL FOR SHARE NOWAIT;SELECT*INTO v_link FROM public.uc_document_registry_incoming_sources WHERE incoming_document_id=v_incoming.id AND organization_id=p_org FOR UPDATE NOWAIT;IF v_link.binding_hash IS DISTINCT FROM p_action->'incoming'->>'expected_binding_hash'OR v_link.record_id IS NOT NULL THEN PERFORM public.uc_document_registry_error('REVISION_CONFLICT');END IF;END IF;
  END IF;
  v_proof:=public.uc_document_registry_write_proof(p_org,v_group,v_data);
  IF v_data->'origin'->>'kind'='legacy_issuance_log'AND EXISTS(SELECT 1 FROM public.uc_document_registry_records x WHERE x.organization_id=p_org AND x.data->'origin'->>'kind'='legacy_issuance_log'AND x.data->'origin'->>'legacy_id'=v_data->'origin'->>'legacy_id')THEN PERFORM public.uc_document_registry_error('REVISION_CONFLICT');END IF;
  IF v_op='register_incoming'AND v_incoming.id IS NULL THEN
   SELECT*INTO STRICT v_version FROM public.org_document_versions WHERE id=(v_data->'source'->>'version_id')::uuid AND organization_id=p_org;
   IF v_data->'sender'->>'kind'='company'THEN v_company:=(v_data->'sender'->>'company_id')::uuid;SELECT inn INTO v_inn FROM public.companies WHERE id=v_company AND organization_id=p_org;ELSIF v_data->'sender'->>'kind'='external'THEN v_inn:=v_data->'sender'->>'inn';END IF;
   INSERT INTO public.incoming_documents(organization_id,doc_type,title,counterparty_name,counterparty_inn,doc_number,doc_date,file_url,file_path,file_size,notes,related_company_id,uploaded_by)VALUES(p_org,CASE WHEN v_data->>'document_type'IN('contract','act','invoice')THEN v_data->>'document_type'ELSE'other'END,v_data->>'title',v_proof->>'sender_label',v_inn,v_data->>'declared_document_number',(v_data->>'document_date')::date,v_version.file_path,v_version.file_path,v_version.file_size,v_data->>'notes',v_company,v_version.uploaded_by)RETURNING*INTO v_incoming;
   v_data:=v_data||jsonb_build_object('origin',jsonb_build_object('kind','incoming_document','incoming_document_id',v_incoming.id));v_proof:=public.uc_document_registry_write_proof(p_org,v_group,v_data);
  END IF;
  IF v_head>=9007199254740991 THEN PERFORM public.uc_document_registry_error('LIMIT_EXCEEDED');END IF;v_year:=extract(year FROM timezone('Europe/Moscow',clock_timestamp()))::integer;
  INSERT INTO public.document_number_sequences(organization_id,doc_type,year,last_number,updated_at)VALUES(p_org,'general_registration',v_year,1,clock_timestamp())ON CONFLICT(organization_id,doc_type,year)DO UPDATE SET last_number=document_number_sequences.last_number+1,updated_at=clock_timestamp()WHERE document_number_sequences.last_number<2147483647 RETURNING last_number INTO v_number;
  IF v_number IS NULL THEN PERFORM public.uc_document_registry_error('LIMIT_EXCEEDED');END IF;v_registration:='РЕГ-'||v_year||'/'||CASE WHEN v_number<1000000 THEN lpad(v_number::text,6,'0')ELSE v_number::text END;
  SELECT coalesce(array_agg(x::uuid),'{}')INTO v_people FROM jsonb_array_elements_text(v_proof->'participants')x;v_people:=array_append(v_people,auth.uid());SELECT coalesce(array_agg(x::uuid),'{}')INTO v_groups FROM jsonb_array_elements_text(v_proof->'groups')x;
