  v_event:=CASE WHEN v_data->'origin'->>'kind'='legacy_issuance_log'THEN'attach_legacy'ELSE'register'END;
  INSERT INTO public.uc_document_registry_events(organization_id,record_id,revision,action,reason,snapshot,participant_ids,recorded_by)VALUES(p_org,v_rec.id,1,v_event,v_reason,jsonb_build_object('data',v_data,'status',v_rec.status,'context_binding',v_rec.context_binding),v_people,auth.uid());

 ELSIF v_op IN('correct','archive')THEN
  IF NOT (CASE WHEN v_op='correct'THEN public.uc_custom_journal_shape(p_action,ARRAY['action','record_id','data','reason'])ELSE public.uc_custom_journal_shape(p_action,ARRAY['action','record_id','reason'])END) OR NOT public.uc_custom_journal_uuid(p_action->'record_id')OR NOT public.uc_document_registry_text(p_action->'reason',2000)THEN PERFORM public.uc_document_registry_error('INVALID_INPUT');END IF;
  SELECT*INTO v_rec FROM public.uc_document_registry_records WHERE id=(p_action->>'record_id')::uuid AND organization_id=p_org AND NOT redacted AND(v_group IS NULL OR v_group=ANY(scope_group_ids))FOR UPDATE NOWAIT;
  IF v_rec.id IS NULL THEN PERFORM public.uc_document_registry_error('NOT_FOUND');END IF;IF v_rec.status<>'registered'OR v_rec.revision<>p_expected_revision THEN PERFORM public.uc_document_registry_error('REVISION_CONFLICT');END IF;
  IF v_rec.revision>=9007199254740991 OR v_head>=9007199254740991 THEN PERFORM public.uc_document_registry_error('LIMIT_EXCEEDED');END IF;v_previous:=v_rec;v_reason:=p_action->>'reason';
  IF v_op='correct'THEN
   v_old_proof:=public.uc_document_registry_write_proof(p_org,v_rec.group_id,v_rec.data);v_data:=p_action->'data';v_proof:=public.uc_document_registry_write_proof(p_org,v_rec.group_id,v_data);
   IF v_data->>'direction'IS DISTINCT FROM v_rec.data->>'direction'OR v_data->'origin'->>'kind'IS DISTINCT FROM v_rec.data->'origin'->>'kind'OR v_data->'origin'->>'incoming_document_id'IS DISTINCT FROM v_rec.data->'origin'->>'incoming_document_id'OR v_data->'origin'->>'legacy_id'IS DISTINCT FROM v_rec.data->'origin'->>'legacy_id'THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;
   SELECT coalesce(array_agg(x::uuid),'{}')INTO v_groups FROM jsonb_array_elements_text(v_proof->'groups')x;SELECT coalesce(array_agg(x ORDER BY x),'{}')INTO v_groups FROM unnest(v_rec.scope_group_ids)x WHERE x=ANY(v_groups);
   SELECT coalesce(array_agg(x::uuid),'{}')INTO v_people FROM jsonb_array_elements_text(v_proof->'participants')x;v_people:=v_people||v_rec.participant_ids;
   UPDATE public.uc_document_registry_records SET data=v_data,context_binding=v_proof->'context_binding',legacy_claim=v_proof->'legacy_claim',scope_group_ids=v_groups,revision=revision+1,participant_ids=v_people,updated_by=auth.uid(),updated_at=clock_timestamp()WHERE id=v_rec.id RETURNING*INTO v_rec;
  ELSE
   v_people:=v_rec.participant_ids;PERFORM public.uc_document_registry_fence(p_org,v_group,v_people,true,p_request_id);
   UPDATE public.uc_document_registry_records SET status='archived',revision=revision+1,updated_by=auth.uid(),updated_at=clock_timestamp()WHERE id=v_rec.id RETURNING*INTO v_rec;
  END IF;
  INSERT INTO public.uc_document_registry_events(organization_id,record_id,revision,action,reason,snapshot,participant_ids,recorded_by)VALUES(p_org,v_rec.id,v_rec.revision,v_op,v_reason,jsonb_build_object('data',v_rec.data,'status',v_rec.status,'context_binding',v_rec.context_binding),array_append(v_people,auth.uid()),auth.uid());
 ELSE PERFORM public.uc_document_registry_error('INVALID_INPUT');END IF;
 IF v_op<>'capture_incoming'THEN
  IF v_op='register_incoming'OR v_op='correct'AND v_rec.data->'origin'->>'kind'='incoming_document'THEN
   IF v_incoming.id IS NULL THEN SELECT*INTO STRICT v_incoming FROM public.incoming_documents WHERE id=(v_rec.data->'origin'->>'incoming_document_id')::uuid AND organization_id=p_org AND deleted_at IS NULL FOR SHARE NOWAIT;END IF;
   SELECT*INTO v_link FROM public.uc_document_registry_incoming_sources WHERE incoming_document_id=v_incoming.id AND organization_id=p_org FOR UPDATE NOWAIT;
   IF v_op='correct'AND(v_link.record_id IS DISTINCT FROM v_rec.id OR v_link.source IS DISTINCT FROM v_previous.data->'source')THEN PERFORM public.uc_document_registry_error('REVISION_CONFLICT');END IF;
   IF v_op='register_incoming'AND v_link.record_id IS NOT NULL THEN PERFORM public.uc_document_registry_error('REVISION_CONFLICT');END IF;
   v_link_revision:=coalesce(v_link.revision,0)+1;v_link_hash:=public.uc_document_registry_hash(jsonb_build_object('organization_id',p_org,'incoming_document_id',v_incoming.id,'source',v_rec.data->'source','revision',v_link_revision)::text);
   INSERT INTO public.uc_document_registry_incoming_sources(incoming_document_id,organization_id,source,binding_hash,record_id,revision,participant_ids,linked_by,updated_by)
    VALUES(v_incoming.id,p_org,v_rec.data->'source',v_link_hash,v_rec.id,v_link_revision,v_people,auth.uid(),auth.uid())ON CONFLICT(incoming_document_id)DO UPDATE SET source=excluded.source,binding_hash=excluded.binding_hash,record_id=excluded.record_id,revision=excluded.revision,participant_ids=uc_document_registry_incoming_sources.participant_ids||excluded.participant_ids,updated_by=excluded.updated_by,updated_at=clock_timestamp();
  END IF;
  UPDATE public.uc_document_registry_heads SET revision=revision+1 WHERE organization_id=p_org RETURNING revision INTO v_head;
  v_result:=jsonb_build_object('record',public.uc_document_registry_record_json(v_rec,v_caps));
 END IF;
 v_people:=array_append(coalesce(v_people,'{}'),auth.uid());SELECT coalesce(array_agg(DISTINCT x ORDER BY x),'{}')INTO v_people FROM unnest(v_people)x WHERE x IS NOT NULL;PERFORM public.uc_document_registry_fence(p_org,v_group,v_people,true,p_request_id);
 v_result:=public.uc_document_registry_base(p_org,p_scope)||jsonb_build_object('kind',v_op,'request_id',p_request_id,'replayed',false)||v_result;
 INSERT INTO public.uc_document_registry_requests(actor_id,request_id,organization_id,scope,payload_hash,result,participant_ids)VALUES(auth.uid(),p_request_id,p_org,p_scope,v_payload,v_result,v_people);RETURN v_result;
 EXCEPTION WHEN lock_not_available OR serialization_failure OR deadlock_detected THEN PERFORM public.uc_document_registry_error('REVISION_CONFLICT');END;$function$

CREATE OR REPLACE FUNCTION public.uc_copy_registry_erase_user(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE targets jsonb;BEGIN
 IF auth.role() IS DISTINCT FROM'service_role' OR current_setting('sintagma.account_deletion_erase_user',true) IS DISTINCT FROM p_user::text OR NOT EXISTS(SELECT 1 FROM public.account_deletion_revocations WHERE user_id=p_user) THEN PERFORM public.uc_copy_registry_error('ACCESS_DENIED');END IF;
 targets:=public.uc_copy_registry_privacy_targets(p_user);
 -- Delete immutable artifacts only if they contain a subject-linked copy or printed actor attribution.
 DELETE FROM public.uc_copy_registry_exports WHERE id IN(SELECT x::uuid FROM jsonb_array_elements_text(targets->'exports')x);
 DELETE FROM public.uc_copy_registry_requests q WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(targets->'requests')x WHERE q.actor_id::text=x.value->>'actor_id'AND q.request_id::text=x.value->>'request_id');
 DELETE FROM public.uc_copy_registry_imports WHERE id IN(SELECT x::uuid FROM jsonb_array_elements_text(targets->'imports')x);
 -- A known subject/recipient owns the copied content, including prior unknown raw/digest history.
 UPDATE public.uc_copy_registry_history SET snapshot='{}',reason='',recorded_by=NULL,participant_ids='{}',redacted=true WHERE id IN(SELECT x::uuid FROM jsonb_array_elements_text(targets->'histories')x);
 UPDATE public.uc_copy_registry_records SET data='{}',latest_transfer=NULL,registered_by=NULL,updated_by=NULL,participant_ids='{}',redacted=true,archived=true WHERE id IN(SELECT x::uuid FROM jsonb_array_elements_text(targets->'records')x);
 -- Attribution alone never authorizes redacting customer content, history or source_raw.
 UPDATE public.uc_copy_registry_records SET
  registered_by=CASE WHEN registered_by=p_user THEN NULL ELSE registered_by END,
  updated_by=CASE WHEN updated_by=p_user THEN NULL ELSE updated_by END,
  latest_transfer=CASE WHEN latest_transfer->>'recorded_by'=p_user::text THEN jsonb_set(latest_transfer,'{recorded_by}','null'::jsonb) ELSE latest_transfer END,
  participant_ids=array_remove(participant_ids,p_user)
 WHERE registered_by=p_user OR updated_by=p_user OR latest_transfer->>'recorded_by'=p_user::text OR p_user=ANY(participant_ids);
 UPDATE public.uc_copy_registry_history SET
  recorded_by=CASE WHEN recorded_by=p_user THEN NULL ELSE recorded_by END,
  snapshot=CASE WHEN snapshot->'latest_transfer'->>'recorded_by'=p_user::text THEN jsonb_set(snapshot,'{latest_transfer,recorded_by}','null'::jsonb) ELSE snapshot END,
  participant_ids=array_remove(participant_ids,p_user)
 WHERE recorded_by=p_user OR snapshot->'latest_transfer'->>'recorded_by'=p_user::text OR p_user=ANY(participant_ids);
 UPDATE public.uc_copy_registry_imports SET created_by=CASE WHEN created_by=p_user THEN NULL ELSE created_by END,participant_ids=array_remove(participant_ids,p_user)
 WHERE created_by=p_user OR p_user=ANY(participant_ids);
 UPDATE public.uc_copy_registry_exports SET participant_ids=array_remove(participant_ids,p_user) WHERE p_user=ANY(participant_ids);
 UPDATE public.uc_copy_registry_requests SET participant_ids=array_remove(participant_ids,p_user) WHERE p_user=ANY(participant_ids);
 IF public.uc_copy_registry_personal_counts(p_user)<>'[]'::jsonb THEN PERFORM public.uc_copy_registry_error('DEPENDENCY_UNAVAILABLE');END IF;END;$function$

CREATE OR REPLACE FUNCTION public.uc_document_registry_context(p_org uuid, p_group uuid, p_subject jsonb, p_context jsonb, p_check boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE k text:=p_context->>'kind';subject_id uuid;e public.enrollments;c public.courses;t public.org_contracts;group_ids uuid[]:='{}';people uuid[]:='{}';binding jsonb;proof jsonb;label text;expected text;ref jsonb;
BEGIN
 IF public.uc_custom_journal_shape(p_subject,ARRAY['kind'])AND p_subject->>'kind'='none'THEN subject_id:=NULL;
 ELSIF public.uc_custom_journal_shape(p_subject,ARRAY['kind','user_id'])AND p_subject->>'kind'='student'AND public.uc_custom_journal_uuid(p_subject->'user_id')THEN subject_id:=(p_subject->>'user_id')::uuid;IF NOT public.uc_document_registry_student(p_org,p_group,subject_id)THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;people:=array_append(people,subject_id);
 ELSE PERFORM public.uc_document_registry_error('INVALID_INPUT');END IF;
 IF k='organization'THEN
  IF NOT public.uc_custom_journal_shape(p_context,ARRAY['kind','not_applicable_reason'])OR NOT public.uc_document_registry_text(p_context->'not_applicable_reason',2000)OR p_group IS NOT NULL THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;label:='Документ организации: '||left(p_context->>'not_applicable_reason',350);
 ELSIF k IN('enrollment','contract','enrollment_contract')THEN
  IF NOT (CASE k WHEN'enrollment'THEN public.uc_custom_journal_shape(p_context,ARRAY['kind','enrollment_id','binding_hash'])WHEN'contract'THEN public.uc_custom_journal_shape(p_context,ARRAY['kind','contract_id','binding_hash'])ELSE public.uc_custom_journal_shape(p_context,ARRAY['kind','enrollment_id','contract_id','binding_hash'])END)
  OR coalesce(p_context->>'binding_hash','')!~'^[a-f0-9]{64}$'THEN PERFORM public.uc_document_registry_error('INVALID_INPUT');END IF;
  IF k IN('enrollment','enrollment_contract')THEN
   IF NOT public.uc_custom_journal_uuid(p_context->'enrollment_id')THEN PERFORM public.uc_document_registry_error('INVALID_INPUT');END IF;
   SELECT x.*INTO e FROM public.enrollments x JOIN public.courses y ON y.id=x.course_id WHERE x.id=(p_context->>'enrollment_id')::uuid AND y.organization_id=p_org;
   IF e.id IS NULL OR NOT public.uc_document_registry_student(p_org,p_group,e.user_id)OR(subject_id IS NOT NULL AND subject_id<>e.user_id)THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;
   SELECT*INTO c FROM public.courses WHERE id=e.course_id AND organization_id=p_org;people:=array_append(people,e.user_id);label:='Зачисление: '||left(coalesce(to_jsonb(c)->>'title','Курс'),250)||' · '||left(public.uc_copy_registry_label(e.user_id),200)||' · '||left(e.status,50);
   IF p_group IS NOT NULL AND EXISTS(SELECT 1 FROM public.student_groups g WHERE g.id=p_group AND g.organization_id=p_org AND g.course_id IS NOT NULL AND g.course_id<>e.course_id)THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;
  END IF;
  IF k IN('contract','enrollment_contract')THEN
   IF NOT public.uc_custom_journal_uuid(p_context->'contract_id')THEN PERFORM public.uc_document_registry_error('INVALID_INPUT');END IF;
   SELECT*INTO t FROM public.org_contracts WHERE id=(p_context->>'contract_id')::uuid AND organization_id=p_org AND status NOT IN('deleted','cancelled','archived');
   IF t.id IS NULL OR NOT public.can_access_organization(p_org,'documents.read')THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;
   IF t.student_user_id IS NOT NULL AND(NOT public.uc_document_registry_student(p_org,p_group,t.student_user_id)OR(subject_id IS NOT NULL AND subject_id<>t.student_user_id)OR(e.id IS NOT NULL AND t.student_user_id<>e.user_id))THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;
   IF t.student_group_id IS NOT NULL AND(NOT EXISTS(SELECT 1 FROM public.student_groups g WHERE g.id=t.student_group_id AND g.organization_id=p_org)OR(p_group IS NOT NULL AND p_group<>t.student_group_id)OR(t.student_user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.student_group_memberships_effective m WHERE m.organization_id=p_org AND m.group_id=t.student_group_id AND m.user_id=t.student_user_id))OR(e.id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.student_group_memberships_effective m JOIN public.student_groups g ON g.id=m.group_id WHERE m.organization_id=p_org AND m.group_id=t.student_group_id AND m.user_id=e.user_id AND(g.course_id IS NULL OR g.course_id=e.course_id))))THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;
   IF p_group IS NOT NULL AND t.student_group_id IS DISTINCT FROM p_group AND(t.student_user_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.student_group_memberships_effective m WHERE m.organization_id=p_org AND m.group_id=p_group AND m.user_id=t.student_user_id))THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;
   IF e.id IS NOT NULL AND t.student_user_id IS NULL AND(t.student_group_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.student_group_memberships_effective m WHERE m.organization_id=p_org AND m.group_id=t.student_group_id AND m.user_id=e.user_id))THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;
   IF subject_id IS NOT NULL AND e.id IS NULL AND t.student_user_id IS NULL AND(t.student_group_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.student_group_memberships_effective m WHERE m.organization_id=p_org AND m.group_id=t.student_group_id AND m.user_id=subject_id))THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;
   IF t.company_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.companies x WHERE x.id=t.company_id AND x.organization_id=p_org)THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;
   people:=array_append(people,t.student_user_id);IF t.student_group_id IS NOT NULL THEN group_ids:=array_append(group_ids,t.student_group_id);END IF;
   label:=concat_ws(' + ',label,'Договор '||left(coalesce(t.contract_number,t.name),180)||' · '||left(t.status,50));
  END IF;
 ELSE PERFORM public.uc_document_registry_error('INVALID_INPUT');END IF;
 SELECT coalesce(array_agg(DISTINCT id ORDER BY id),'{}')INTO people FROM unnest(people)id WHERE id IS NOT NULL;
 SELECT coalesce(array_agg(DISTINCT m.group_id ORDER BY m.group_id),'{}')INTO group_ids FROM public.student_group_memberships_effective m JOIN public.student_groups g ON g.id=m.group_id WHERE m.organization_id=p_org AND m.user_id=ANY(people)AND(e.id IS NULL OR g.course_id IS NULL OR g.course_id=e.course_id)AND(t.student_group_id IS NULL OR m.group_id=t.student_group_id);
 IF t.student_group_id IS NOT NULL THEN group_ids:=array_append(group_ids,t.student_group_id);END IF;
 IF p_group IS NOT NULL AND NOT(p_group=ANY(group_ids))THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;
 SELECT coalesce(array_agg(DISTINCT id ORDER BY id),'{}')INTO group_ids FROM unnest(group_ids)id WHERE id IS NOT NULL;
 binding:=jsonb_build_object('kind',k,'organization_id',p_org,'enrollment_id',e.id,'user_id',coalesce(e.user_id,t.student_user_id,subject_id),'course_id',e.course_id,'enrollment_status',e.status,'enrollment_revision',CASE WHEN e.id IS NULL THEN NULL ELSE e.document_facts_revision END,'contract_id',t.id,'contract_student_user_id',t.student_user_id,'contract_group_id',t.student_group_id,'contract_company_id',t.company_id,'contract_status',t.status,'contract_updated_at',t.updated_at,'scope_group_id',p_group);
 proof:=jsonb_build_object('binding',binding,'factual_group_ids',to_jsonb(group_ids),'reason',CASE WHEN k='organization'THEN p_context->>'not_applicable_reason'ELSE NULL END);expected:=public.uc_document_registry_hash(proof::text);
 IF k<>'organization'AND p_check AND expected<>p_context->>'binding_hash'THEN PERFORM public.uc_document_registry_error('CONTEXT_CHANGED');END IF;
 binding:=binding||jsonb_build_object('binding_hash',expected);ref:=CASE k WHEN'organization'THEN p_context WHEN'enrollment'THEN jsonb_build_object('kind',k,'enrollment_id',e.id,'binding_hash',expected)WHEN'contract'THEN jsonb_build_object('kind',k,'contract_id',t.id,'binding_hash',expected)ELSE jsonb_build_object('kind',k,'enrollment_id',e.id,'contract_id',t.id,'binding_hash',expected)END;
 RETURN jsonb_build_object('binding',binding,'context',ref,'participants',to_jsonb(people),'groups',to_jsonb(group_ids),'label',left(label,500));END;$function$

CREATE OR REPLACE FUNCTION public.uc_document_registry_erase_user(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE target jsonb;BEGIN
 IF auth.role()IS DISTINCT FROM'service_role'OR current_setting('sintagma.account_deletion_erase_user',true)IS DISTINCT FROM p_user::text OR NOT EXISTS(SELECT 1 FROM public.account_deletion_revocations WHERE user_id=p_user)THEN PERFORM public.uc_document_registry_error('ACCESS_DENIED');END IF;
 target:=public.uc_document_registry_privacy_targets(p_user);
 DELETE FROM public.uc_document_registry_requests q WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(target->'requests')x WHERE q.actor_id::text=x.value->>'actor_id'AND q.request_id::text=x.value->>'request_id');
 UPDATE public.uc_document_registry_events SET snapshot='{}',reason='',recorded_by=NULL,participant_ids='{}',redacted=true WHERE record_id IN(SELECT x::uuid FROM jsonb_array_elements_text(target->'records')x);
 UPDATE public.uc_document_registry_records SET data='{}',context_binding='{}',legacy_claim=NULL,registered_by=NULL,updated_by=NULL,participant_ids='{}',redacted=true,status='archived'WHERE id IN(SELECT x::uuid FROM jsonb_array_elements_text(target->'records')x);
 -- Source associations retain archive identity and a tombstone: no record can be silently registered again.
 UPDATE public.uc_document_registry_records SET registered_by=CASE WHEN registered_by=p_user THEN NULL ELSE registered_by END,updated_by=CASE WHEN updated_by=p_user THEN NULL ELSE updated_by END,participant_ids=array_remove(participant_ids,p_user),legacy_claim=CASE WHEN legacy_claim->>'stored_user_id'=p_user::text THEN jsonb_set(legacy_claim,'{stored_user_id}','null')ELSE legacy_claim END WHERE registered_by=p_user OR updated_by=p_user OR p_user=ANY(participant_ids)OR legacy_claim->>'stored_user_id'=p_user::text;
 UPDATE public.uc_document_registry_events SET recorded_by=CASE WHEN recorded_by=p_user THEN NULL ELSE recorded_by END,participant_ids=array_remove(participant_ids,p_user)WHERE recorded_by=p_user OR p_user=ANY(participant_ids);
 UPDATE public.uc_document_registry_incoming_sources SET linked_by=CASE WHEN linked_by=p_user THEN NULL ELSE linked_by END,updated_by=CASE WHEN updated_by=p_user THEN NULL ELSE updated_by END,participant_ids=array_remove(participant_ids,p_user)WHERE linked_by=p_user OR updated_by=p_user OR p_user=ANY(participant_ids);
 UPDATE public.uc_document_registry_requests SET participant_ids=array_remove(participant_ids,p_user)WHERE p_user=ANY(participant_ids);
 IF public.uc_document_registry_personal_counts(p_user)<>'[]'::jsonb THEN PERFORM public.uc_document_registry_error('DEPENDENCY_UNAVAILABLE');END IF;END;$function$

CREATE OR REPLACE FUNCTION public.uc_document_registry_source(p_org uuid, p_ref jsonb, p_required boolean DEFAULT true, p_own_write boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE proof jsonb;v public.org_document_versions;d public.org_documents;BEGIN
 proof:=public.uc_copy_registry_source(p_org,p_ref,false,false);
 IF proof IS NULL AND p_own_write AND public.uc_custom_journal_shape(p_ref,ARRAY['kind','document_id','version_id','content_hash'])AND p_ref->>'kind'='org_document_version'AND public.uc_custom_journal_uuid(p_ref->'document_id')AND public.uc_custom_journal_uuid(p_ref->'version_id')AND coalesce(p_ref->>'content_hash','')~'^[a-f0-9]{64}$'
 AND NOT public.uc_document_teacher_limited(p_org)AND public.uc_document_org_access(p_org,true)THEN
  SELECT x.*INTO d FROM public.org_documents x WHERE x.id=(p_ref->>'document_id')::uuid AND x.organization_id=p_org AND x.deleted_at IS NULL AND coalesce(to_jsonb(x)->>'status','active')NOT IN('archived','expired');
  SELECT x.*INTO v FROM public.org_document_versions x WHERE x.id=(p_ref->>'version_id')::uuid AND x.document_id=d.id AND x.organization_id=p_org AND x.uploaded_by=auth.uid();
  IF v.id IS NOT NULL AND public.uc_copy_registry_object_matches(v)AND public.uc_copy_registry_original_ref(v)=p_ref THEN proof:=jsonb_build_object('participants',jsonb_build_array(v.uploaded_by),'label','Загруженная версия '||v.version_number||' · '||left(coalesce(v.file_name,'Файл'),400),'verified',true);END IF;
 END IF;
 IF proof IS NOT NULL THEN
  SELECT x.*INTO v FROM public.org_document_versions x WHERE x.id=(p_ref->>'version_id')::uuid AND x.document_id=(p_ref->>'document_id')::uuid AND x.organization_id=p_org;
  IF v.id IS NULL OR NOT public.uc_document_registry_text(to_jsonb(v.file_path),2000)OR v.file_path LIKE'/%'OR v.file_path LIKE'%..%'OR v.file_path LIKE'%://%'OR v.file_path~'[[:cntrl:]?]'OR strpos(v.file_path,chr(92))>0
   OR NOT public.uc_document_registry_text(to_jsonb(coalesce(nullif(v.file_name,''),'document')),1000)OR NOT public.uc_document_registry_text(to_jsonb(lower(btrim(v.storage_metadata->>'mimetype'))),200)
   OR coalesce(v.file_size,(v.storage_metadata->>'size')::bigint)NOT BETWEEN 0 AND 9007199254740991 THEN proof:=NULL;END IF;
 END IF;
 IF proof IS NULL AND p_required THEN PERFORM public.uc_document_registry_error('SOURCE_UNAVAILABLE');END IF;RETURN proof;END;$function$

CREATE OR REPLACE FUNCTION public.uc_learning_options(p_org uuid, p_query jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE course uuid;version uuid;lessons jsonb;modules jsonb;humans jsonb;files jsonb;eligible uuid[];scope jsonb;envelope jsonb;c public.uc_learning_criteria_versions;BEGIN
 IF p_query->>'kind'='decision_options' THEN
  IF NOT public.uc_learning_shape(p_query,ARRAY['kind','scope']) THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
  scope:=p_query->'scope';PERFORM public.uc_learning_access(p_org,scope,true);envelope:=public.uc_learning_envelope(p_org,scope);
  IF NOT coalesce((envelope->'capabilities'->>'can_decide')::boolean,false) THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
  SELECT * INTO c FROM public.uc_learning_criteria_versions WHERE id=(envelope->'criteria_ref'->>'id')::uuid AND NOT redacted;
  IF EXISTS(SELECT 1 FROM public.org_document_versions v JOIN public.org_documents d ON d.id=v.document_id AND d.organization_id=v.organization_id WHERE v.organization_id=p_org AND c.definition->'recognition_file_version_ids' ? v.id::text AND public.uc_program_active_file_proof(p_org,v.id) AND public.uc_document_action_allowed(p_org,'read',NULL,NULL) AND length(d.name)>1000) THEN PERFORM public.uc_learning_error('LIMIT_EXCEEDED');END IF;
  IF EXISTS(SELECT 1 FROM public.org_document_versions v JOIN public.org_documents d ON d.id=v.document_id AND d.organization_id=v.organization_id WHERE v.organization_id=p_org AND c.definition->'recognition_file_version_ids' ? v.id::text AND public.uc_program_active_file_proof(p_org,v.id) AND public.uc_document_action_allowed(p_org,'read',NULL,NULL) AND(d.name IS NULL OR d.name!~'[^[:space:]]')) THEN PERFORM public.uc_learning_error('SOURCE_UNAVAILABLE');END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('version_id',v.id,'document_name',d.name) ORDER BY v.id),'[]') INTO files FROM public.org_document_versions v JOIN public.org_documents d ON d.id=v.document_id AND d.organization_id=v.organization_id
   WHERE v.organization_id=p_org AND c.definition->'recognition_file_version_ids' ? v.id::text AND public.uc_program_active_file_proof(p_org,v.id) AND public.uc_document_action_allowed(p_org,'read',NULL,NULL);
  RETURN jsonb_build_object('schema_version',1,'scope',scope,'allowed_component_ids',c.definition->'recognition_component_ids','files',files);
 END IF;
 IF NOT public.uc_learning_shape(p_query,ARRAY['kind','course_id','program_version_id']) OR NOT public.uc_learning_uuid(p_query->'course_id') OR NOT public.uc_learning_uuid(p_query->'program_version_id') THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
 IF NOT public.uc_learning_staff(auth.uid(),p_org,NULL,true) THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
 course:=(p_query->>'course_id')::uuid;version:=(p_query->>'program_version_id')::uuid;
 IF NOT EXISTS(SELECT 1 FROM public.courses WHERE id=course AND organization_id=p_org) THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
 IF public.uc_learning_programme_proof(p_org,version) IS NULL THEN PERFORM public.uc_learning_error('SOURCE_UNAVAILABLE');END IF;
 IF(SELECT count(*) FROM public.lessons WHERE course_id=course)>500 OR(SELECT count(*) FROM public.course_modules WHERE course_id=course)>250 THEN PERFORM public.uc_learning_error('LIMIT_EXCEEDED');END IF;
 IF EXISTS(SELECT 1 FROM public.lessons WHERE course_id=course AND(length(title)>1000 OR length(type)>80)) OR EXISTS(SELECT 1 FROM public.course_modules WHERE course_id=course AND length(title)>1000) THEN PERFORM public.uc_learning_error('LIMIT_EXCEEDED');END IF;
 IF EXISTS(SELECT 1 FROM public.lessons WHERE course_id=course AND(title IS NULL OR title!~'[^[:space:]]' OR type IS NULL OR type!~'[^[:space:]]')) OR EXISTS(SELECT 1 FROM public.course_modules WHERE course_id=course AND(title IS NULL OR title!~'[^[:space:]]')) THEN PERFORM public.uc_learning_error('SOURCE_UNAVAILABLE');END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',l.id,'title',l.title,'type',l.type,'module_id',l.module_id) ORDER BY l.order_index,l.id),'[]') INTO lessons FROM public.lessons l WHERE l.course_id=course;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',m.id,'title',m.title) ORDER BY m.id),'[]') INTO modules FROM public.course_modules m WHERE m.course_id=course;
 SELECT array_agg(DISTINCT q.user_id ORDER BY q.user_id) INTO eligible FROM(SELECT user_id FROM public.profiles WHERE organization_id=p_org UNION SELECT user_id FROM public.org_staff WHERE organization_id=p_org)q
  WHERE public.uc_learning_staff(q.user_id,p_org,NULL,true) OR EXISTS(SELECT 1 FROM public.student_groups g WHERE g.organization_id=p_org AND g.course_id=course AND public.uc_learning_staff(q.user_id,p_org,g.id,true));
 IF coalesce(cardinality(eligible),0)>250 THEN PERFORM public.uc_learning_error('LIMIT_EXCEEDED');END IF;
 IF EXISTS(SELECT 1 FROM unnest(coalesce(eligible,'{}'::uuid[]))u WHERE length(public.uc_org_document_review_actor_name(p_org,u))>500) THEN PERFORM public.uc_learning_error('LIMIT_EXCEEDED');END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('user_id',q.user_id,'display_name',public.uc_org_document_review_actor_name(p_org,q.user_id),'can_review',public.uc_learning_staff(q.user_id,p_org,NULL,true),'can_decide',true) ORDER BY q.user_id),'[]') INTO humans FROM unnest(coalesce(eligible,'{}'::uuid[]))q(user_id);
 IF(SELECT count(*) FROM public.org_document_versions v WHERE v.organization_id=p_org AND public.uc_program_active_file_proof(p_org,v.id))>250 THEN PERFORM public.uc_learning_error('LIMIT_EXCEEDED');END IF;
 IF EXISTS(SELECT 1 FROM public.org_document_versions v JOIN public.org_documents d ON d.id=v.document_id WHERE v.organization_id=p_org AND public.uc_program_active_file_proof(p_org,v.id) AND length(d.name)>1000) THEN PERFORM public.uc_learning_error('LIMIT_EXCEEDED');END IF;
 IF EXISTS(SELECT 1 FROM public.org_document_versions v JOIN public.org_documents d ON d.id=v.document_id WHERE v.organization_id=p_org AND public.uc_program_active_file_proof(p_org,v.id) AND(d.name IS NULL OR d.name!~'[^[:space:]]')) THEN PERFORM public.uc_learning_error('SOURCE_UNAVAILABLE');END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('version_id',v.id,'document_name',d.name) ORDER BY v.id),'[]') INTO files FROM public.org_document_versions v JOIN public.org_documents d ON d.id=v.document_id AND d.organization_id=v.organization_id WHERE v.organization_id=p_org AND public.uc_program_active_file_proof(p_org,v.id);
 RETURN jsonb_build_object('schema_version',1,'organization_id',p_org,'course_id',course,'program_version_id',version,'lessons',lessons,'modules',modules,'humans',humans,'files',files);
END;$function$

CREATE OR REPLACE FUNCTION public.uc_learning_personal_counts(p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb:='[]';t text;n bigint;BEGIN
 FOREACH t IN ARRAY ARRAY['uc_learning_criteria_versions','uc_learning_attestation_decisions','uc_learning_outcome_requests'] LOOP
  EXECUTE format('SELECT count(*) FROM public.%I WHERE participant_ids @> ARRAY[$1]::uuid[]',t) INTO n USING p_user;
  IF n>0 THEN result:=result||jsonb_build_array(jsonb_build_object('table',t,'column','participant_ids','count',n));END IF;
 END LOOP;
 FOREACH t IN ARRAY ARRAY['uc_learning_outcome_states','uc_learning_attempt_contexts','uc_learning_machine_results'] LOOP
  EXECUTE format('SELECT count(*) FROM public.%I WHERE user_id=$1',t) INTO n USING p_user;
  IF n>0 THEN result:=result||jsonb_build_array(jsonb_build_object('table',t,'column','user_id','count',n));END IF;
 END LOOP;RETURN result;
END;$function$

CREATE OR REPLACE FUNCTION public._assert_test_learner_access(p_lesson_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public._paid_20260922_lesson_read(p_lesson_id,false,true) THEN
    RAISE EXCEPTION 'Paid test content is not available for this user' USING ERRCODE='42501';
  END IF;
  IF auth.uid() IS NULL OR EXISTS (
    SELECT 1 FROM public.profiles WHERE user_id = auth.uid() AND blocked_at IS NOT NULL
  ) OR NOT EXISTS (
    SELECT 1 FROM public.lessons l JOIN public.courses c ON c.id = l.course_id
    WHERE l.id = p_lesson_id AND l.type = 'test' AND c.is_published = true
      AND public.can_access_course_as_learner(c.id)
  ) THEN
    RAISE EXCEPTION 'Test is not available for this learner' USING ERRCODE = '42501';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public._test_normalize_options(p_options jsonb, p_correct_answer integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_options jsonb := p_options;
BEGIN
  IF jsonb_typeof(v_options) = 'string' THEN
    BEGIN
      v_options := (v_options #>> '{}')::jsonb;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'Test content invalid: answer options are not a valid JSON array' USING ERRCODE = '22023';
    END;
  END IF;
  IF jsonb_typeof(v_options) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Test content invalid: answer options must be an array' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(v_options) = 0 THEN
    RAISE EXCEPTION 'Test content invalid: answer options are empty' USING ERRCODE = '22023';
  END IF;
  -- Preserve legacy keys, including NULL and out-of-range values, in the snapshot.
  -- Legal answers still use zero-based option indexes; these keys cannot earn a point.
  RETURN v_options;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_org_staff_permissions(_user_id uuid, _organization_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  staff_role text;
  base_perms text[];
  override_perms text[];
BEGIN
  SELECT role,
         COALESCE(
           ARRAY(SELECT jsonb_array_elements_text(sections_access)),
           ARRAY[]::text[]
         )
    INTO staff_role, override_perms
    FROM public.org_staff
   WHERE user_id = _user_id AND organization_id = _organization_id
   LIMIT 1;

  IF staff_role IS NULL THEN
    RETURN ARRAY[]::text[];
  END IF;

  base_perms := public.org_role_default_permissions(staff_role);

  -- merge: union of base + overrides (overrides могут только добавлять права)
  RETURN ARRAY(
    SELECT DISTINCT unnest(base_perms || override_perms)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.uc_copy_registry_source(p_org uuid, p_ref jsonb, p_unresolved boolean DEFAULT false, p_required boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE v public.org_document_versions;d public.org_documents;proof jsonb;people uuid[];available boolean:=false;
BEGIN
 IF p_unresolved AND public.uc_custom_journal_shape(p_ref,ARRAY['kind','document_type','document_number','issue_date','explanation']) AND p_ref->>'kind'='unresolved'
  AND public.uc_custom_journal_text(p_ref->'document_type',100) AND public.uc_custom_journal_text(p_ref->'document_number',120) AND public.uc_custom_journal_text(p_ref->'issue_date',80) AND public.uc_custom_journal_text(p_ref->'explanation',2000) THEN RETURN jsonb_build_object('participants','[]'::jsonb,'label',NULL,'verified',false);END IF;
 IF NOT public.uc_custom_journal_shape(p_ref,ARRAY['kind','document_id','version_id','content_hash']) OR p_ref->>'kind' IS DISTINCT FROM'org_document_version' OR NOT public.uc_custom_journal_uuid(p_ref->'document_id') OR NOT public.uc_custom_journal_uuid(p_ref->'version_id') OR coalesce(p_ref->>'content_hash','')!~'^[a-f0-9]{64}$' THEN
  IF p_required THEN PERFORM public.uc_copy_registry_error('INVALID_INPUT');END IF;RETURN NULL;END IF;
 IF public.uc_copy_registry_file_permission(p_org) THEN
  SELECT x.* INTO d FROM public.org_documents x WHERE x.id=(p_ref->>'document_id')::uuid AND x.organization_id=p_org AND x.deleted_at IS NULL AND coalesce(to_jsonb(x)->>'status','active') NOT IN('archived','expired');
  SELECT x.* INTO v FROM public.org_document_versions x WHERE x.id=(p_ref->>'version_id')::uuid AND x.document_id=d.id AND x.organization_id=p_org;
  IF v.id IS NOT NULL AND public.uc_copy_registry_object_matches(v) THEN
   proof:=jsonb_build_object('document_id',v.document_id,'version_id',v.id,'version_number',v.version_number,'file_path',v.file_path,'file_size',v.file_size,'file_name',v.file_name,'storage_object_id',v.storage_object_id,'storage_metadata',v.storage_metadata,'document_metadata',v.document_metadata);
   available:=public.uc_copy_registry_hash(proof::text)=p_ref->>'content_hash' AND(v.uploaded_by IS NULL OR public.uc_custom_journal_person(v.uploaded_by));
  END IF;
 END IF;
 IF NOT available THEN IF p_required THEN PERFORM public.uc_copy_registry_error('SOURCE_UNAVAILABLE');END IF;RETURN NULL;END IF;
 people:=array_remove(ARRAY[v.uploaded_by],NULL);RETURN jsonb_build_object('participants',to_jsonb(people),'label',left(d.name||' · версия '||v.version_number,500),'verified',true);
END;$function$

CREATE OR REPLACE FUNCTION public.uc_custom_journal_erase_user(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF auth.role()IS DISTINCT FROM 'service_role'OR current_setting('sintagma.account_deletion_erase_user',true)IS DISTINCT FROM p_user::text OR NOT EXISTS(SELECT 1 FROM public.account_deletion_revocations WHERE user_id=p_user)THEN PERFORM public.uc_custom_journal_error('ACCESS_DENIED');END IF;
 PERFORM public.uc_scoped_journal_erase_user(p_user);
 DELETE FROM public.uc_custom_journal_requests WHERE actor_id=p_user OR subject_user_id=p_user;
 DELETE FROM public.uc_custom_journal_history WHERE subject_user_id=p_user;
 DELETE FROM public.uc_custom_journal_records WHERE subject_user_id=p_user;
 -- Conservatively remove the erased author's entire attributed free-text copy.
 -- This is exact-reference erasure, not discovery of third-party PII in arbitrary text.
 UPDATE public.uc_custom_journal_history SET recorded_by=NULL,field_values='{}',reason='',redacted=true WHERE recorded_by=p_user;
 UPDATE public.uc_custom_journal_records SET recorded_by=NULL,field_values='{}',redacted=true WHERE recorded_by=p_user;
 UPDATE public.uc_custom_journal_schemas SET created_by=NULL,fields='[]',title='',description='',reason='',redacted=true WHERE created_by=p_user;
 UPDATE public.uc_custom_journals SET created_by=NULL,updated_by=NULL,title='',description='',redacted=true WHERE created_by=p_user OR updated_by=p_user;
 IF public.uc_custom_journal_personal_counts(p_user)<>'[]'::jsonb THEN PERFORM public.uc_custom_journal_error('DEPENDENCY_UNAVAILABLE');END IF;
END;$function$

CREATE OR REPLACE FUNCTION public.uc_document_contract_scope(p_org uuid, p_group uuid, p_user uuid, p_company uuid, p_students jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE item jsonb;v_user uuid;
BEGIN
 IF p_company IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.companies c WHERE c.id=p_company AND c.organization_id=p_org) THEN RETURN false; END IF;
 IF p_user IS NOT NULL AND p_group IS NULL AND NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.user_id=p_user AND p.organization_id=p_org)
 AND NOT EXISTS(SELECT 1 FROM public.enrollments e JOIN public.courses c ON c.id=e.course_id WHERE e.user_id=p_user AND c.organization_id=p_org)
 THEN RETURN false; END IF;
 IF p_students IS NULL OR jsonb_typeof(p_students)<>'array' THEN RETURN false; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_students) LOOP
  v_user:=public.storage_try_uuid(item->>'user_id');
  IF v_user IS NULL THEN
   IF public.uc_document_teacher_limited(p_org) OR nullif(item->>'user_id','') IS NOT NULL THEN RETURN false; END IF;
  ELSIF p_group IS NOT NULL THEN
   IF NOT EXISTS(SELECT 1 FROM public.student_group_memberships_effective m WHERE m.organization_id=p_org AND m.group_id=p_group AND m.user_id=v_user) THEN RETURN false; END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.user_id=v_user AND p.organization_id=p_org) THEN RETURN false;
  END IF;
 END LOOP;
 RETURN public.uc_document_record_scope(p_org,p_group,NULL,p_user,NULL);
END;$function$

CREATE OR REPLACE FUNCTION public.uc_document_registry_fence(p_org uuid, p_group uuid, p_people uuid[], p_write boolean DEFAULT false, p_request uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE who uuid;BEGIN
 IF cardinality(coalesce(p_people,'{}'))>20000 THEN PERFORM public.uc_document_registry_error('LIMIT_EXCEEDED');END IF;
 FOR who IN SELECT DISTINCT x FROM unnest(array_append(coalesce(p_people,'{}'),auth.uid()))x WHERE x IS NOT NULL ORDER BY x LOOP
  IF NOT pg_try_advisory_xact_lock_shared(hashtextextended(who::text,42007))THEN PERFORM public.uc_document_registry_error('REVISION_CONFLICT');END IF;
  IF NOT public.uc_custom_journal_person(who)THEN PERFORM public.uc_document_registry_error('SOURCE_UNAVAILABLE');END IF;
 END LOOP;
 IF p_write THEN
  IF NOT pg_try_advisory_xact_lock(hashtextextended(p_org::text,0))THEN PERFORM public.uc_document_registry_error('REVISION_CONFLICT');END IF;
  IF p_group IS NOT NULL AND NOT pg_try_advisory_xact_lock(hashtextextended('uc_program_roster:'||p_group::text,0))THEN PERFORM public.uc_document_registry_error('REVISION_CONFLICT');END IF;
  IF NOT pg_try_advisory_xact_lock(hashtextextended('uc_document_registry:'||p_org::text,0))THEN PERFORM public.uc_document_registry_error('REVISION_CONFLICT');END IF;
 END IF;
 IF NOT p_write AND NOT pg_try_advisory_xact_lock_shared(hashtextextended('uc_document_registry:'||p_org::text,0))THEN PERFORM public.uc_document_registry_error('REVISION_CONFLICT');END IF;
 IF p_request IS NOT NULL AND NOT pg_try_advisory_xact_lock(hashtextextended('uc_document_registry_request:'||auth.uid()::text||':'||p_request::text,0))THEN PERFORM public.uc_document_registry_error('REVISION_CONFLICT');END IF;
 LOCK TABLE public.organizations,public.org_staff,public.org_staff_document_groups,public.user_roles,public.admin_staff IN ROW SHARE MODE NOWAIT;
 PERFORM 1 FROM public.organizations WHERE id=p_org FOR SHARE NOWAIT;
 PERFORM 1 FROM public.org_staff WHERE organization_id=p_org AND user_id=auth.uid()ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.org_staff_document_groups a JOIN public.org_staff s ON s.id=a.staff_id WHERE a.organization_id=p_org AND a.group_id=p_group AND s.user_id=auth.uid()ORDER BY a.staff_id FOR SHARE OF a NOWAIT;
 PERFORM 1 FROM public.user_roles WHERE user_id=auth.uid()FOR SHARE NOWAIT;PERFORM 1 FROM public.admin_staff WHERE user_id=auth.uid()FOR SHARE NOWAIT;
 PERFORM public.uc_document_registry_scope(p_org,CASE WHEN p_group IS NULL THEN jsonb_build_object('kind','organization')ELSE jsonb_build_object('kind','group','group_id',p_group)END);
 EXCEPTION WHEN lock_not_available OR serialization_failure OR deadlock_detected THEN PERFORM public.uc_document_registry_error('REVISION_CONFLICT');END;$function$

CREATE OR REPLACE FUNCTION public.uc_document_registry_incoming_json(p incoming_documents, p_group uuid, p_caps jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE link public.uc_document_registry_incoming_sources;r public.uc_document_registry_records;src jsonb;oldfile boolean:=false;BEGIN
 SELECT*INTO link FROM public.uc_document_registry_incoming_sources WHERE incoming_document_id=p.id AND organization_id=p.organization_id;
 IF link.record_id IS NOT NULL THEN SELECT*INTO r FROM public.uc_document_registry_records WHERE id=link.record_id AND organization_id=p.organization_id AND NOT redacted AND(p_group IS NULL OR p_group=ANY(scope_group_ids));END IF;
 IF p_group IS NOT NULL AND r.id IS NULL THEN PERFORM public.uc_document_registry_error('NOT_FOUND');END IF;
 IF link.incoming_document_id IS NOT NULL THEN src:=public.uc_document_registry_source(p.organization_id,link.source,false,false);ELSE
  oldfile:=coalesce(public.uc_document_org_access(p.organization_id,false)AND NOT public.uc_document_teacher_limited(p.organization_id)AND EXISTS(SELECT 1 FROM storage.objects o JOIN storage.buckets b ON b.id=o.bucket_id WHERE b.id='incoming-documents'AND NOT b.public AND o.name=p.file_path AND o.name LIKE p.organization_id::text||'/%'),false);
 END IF;
 RETURN jsonb_build_object('id',p.id,'doc_type',p.doc_type,'title',p.title,'counterparty_name',p.counterparty_name,'counterparty_inn',p.counterparty_inn,'doc_number',p.doc_number,'doc_date',p.doc_date,'notes',p.notes,'created_at',p.created_at,'updated_at',p.updated_at,'related_signature_id',p.related_signature_id,'related_billing_doc_id',p.related_billing_doc_id,'related_company_id',p.related_company_id,'linked_source',link.source,'source_label',src->'label','source_available',src IS NOT NULL,'binding_hash',link.binding_hash,'registry_record_id',r.id,'registration_id',r.registration_id,'legacy_unversioned',link.incoming_document_id IS NULL,'can_register',(p_caps->>'can_register_incoming')::boolean AND link.record_id IS NULL,'can_open_file',src IS NOT NULL OR oldfile);END;$function$

CREATE OR REPLACE FUNCTION public.uc_document_registry_incoming_plan(p_org uuid, p_group uuid, p_incoming jsonb, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r public.incoming_documents;link public.uc_document_registry_incoming_sources;full_data jsonb;proof jsonb;BEGIN
 IF NOT public.uc_custom_journal_shape(p_data,ARRAY['direction','document_type','title','document_date','declared_document_number','source','sender','recipient','subject','context','notes'])OR p_data->>'direction'IS DISTINCT FROM'incoming'THEN PERFORM public.uc_document_registry_error('INVALID_INPUT');END IF;
 IF public.uc_custom_journal_shape(p_incoming,ARRAY['kind'])AND p_incoming->>'kind'='new'THEN full_data:=p_data||jsonb_build_object('origin',jsonb_build_object('kind','org_document'));
 ELSIF public.uc_custom_journal_shape(p_incoming,ARRAY['kind','incoming_document_id','expected_binding_hash'])AND p_incoming->>'kind'='existing'AND public.uc_custom_journal_uuid(p_incoming->'incoming_document_id')AND(p_incoming->'expected_binding_hash'='null'::jsonb OR jsonb_typeof(p_incoming->'expected_binding_hash')='string'AND p_incoming->>'expected_binding_hash'~'^[a-f0-9]{64}$')THEN
  SELECT*INTO r FROM public.incoming_documents WHERE id=(p_incoming->>'incoming_document_id')::uuid AND organization_id=p_org AND deleted_at IS NULL;IF r.id IS NULL THEN PERFORM public.uc_document_registry_error('NOT_FOUND');END IF;
  SELECT*INTO link FROM public.uc_document_registry_incoming_sources WHERE incoming_document_id=r.id AND organization_id=p_org;
  IF link.binding_hash IS DISTINCT FROM p_incoming->>'expected_binding_hash'OR link.record_id IS NOT NULL THEN PERFORM public.uc_document_registry_error('REVISION_CONFLICT');END IF;
  full_data:=p_data||jsonb_build_object('origin',jsonb_build_object('kind','incoming_document','incoming_document_id',r.id));
 ELSE PERFORM public.uc_document_registry_error('INVALID_INPUT');END IF;
 proof:=public.uc_document_registry_data(p_org,p_group,full_data,true);RETURN jsonb_build_object('data',full_data,'proof',proof);END;$function$

CREATE OR REPLACE FUNCTION public.uc_document_registry_record_json(p uc_document_registry_records, p_caps jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE src jsonb;ctx jsonb;current_context boolean:=false;can_correct boolean:=false;context_label text:='Связь изменена; прежние идентификаторы сохранены';proof jsonb;BEGIN
 src:=public.uc_document_registry_source(p.organization_id,p.data->'source',false,false);
 BEGIN ctx:=public.uc_document_registry_context(p.organization_id,p.group_id,p.data->'subject',p.data->'context',true);current_context:=ctx->'binding'=p.context_binding;IF current_context THEN context_label:=ctx->>'label';END IF;
 EXCEPTION WHEN SQLSTATE'22023'OR SQLSTATE'PT409'OR SQLSTATE'PT404'OR SQLSTATE'42501'THEN IF SQLERRM NOT LIKE'DOCUMENT_REGISTRY_%'THEN RAISE;END IF;current_context:=false;END;
 IF(p_caps->>'can_correct')::boolean AND p.status='registered'AND src IS NOT NULL AND current_context THEN BEGIN proof:=public.uc_document_registry_data(p.organization_id,p.group_id,p.data,true);can_correct:=true;
 EXCEPTION WHEN SQLSTATE'22023'OR SQLSTATE'PT409'OR SQLSTATE'PT404'OR SQLSTATE'42501'THEN IF SQLERRM NOT LIKE'DOCUMENT_REGISTRY_%'THEN RAISE;END IF;can_correct:=false;END;END IF;
 RETURN jsonb_build_object('id',p.id,'group_id',p.group_id,'registration_id',p.registration_id,'sequence_year',p.sequence_year,'sequence_number',p.sequence_number,'revision',p.revision,'status',p.status,'data',p.data,'context_binding',p.context_binding,'registered_at',p.registered_at,'recorded_by',p.registered_by,'recorded_by_label',CASE WHEN p.registered_by IS NULL THEN NULL ELSE public.uc_copy_registry_label(p.registered_by)END,'updated_at',p.updated_at,'source_label',src->'label','source_available',src IS NOT NULL,'sender_label',public.uc_document_registry_party_label(p.organization_id,p.data->'sender'),'recipient_label',public.uc_document_registry_party_label(p.organization_id,p.data->'recipient'),'subject_label',CASE WHEN p.data->'subject'->>'kind'='student'THEN public.uc_copy_registry_label((p.data->'subject'->>'user_id')::uuid)ELSE NULL END,'context_label',context_label,'context_current',current_context,'legacy_claim',p.legacy_claim,'can_correct',can_correct,'can_archive',(p_caps->>'can_archive')::boolean AND p.status='registered','can_open_file',(p_caps->>'can_open_file')::boolean AND src IS NOT NULL);
END;$function$

CREATE OR REPLACE FUNCTION public.uc_document_registry_replay(p_org uuid, p_scope jsonb, p_req uc_document_registry_requests, p_caps jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE g uuid:=CASE WHEN p_scope->>'kind'='group'THEN(p_scope->>'group_id')::uuid ELSE NULL END;result jsonb:=p_req.result;item jsonb;src jsonb;ctx jsonb;proof jsonb;r public.uc_document_registry_records;i public.incoming_documents;link public.uc_document_registry_incoming_sources;current_context boolean:=false;same_current boolean:=false;BEGIN
 IF result->>'kind'='capture_incoming'THEN
  item:=result->'incoming';SELECT*INTO i FROM public.incoming_documents WHERE id=(item->>'id')::uuid AND organization_id=p_org AND deleted_at IS NULL;IF i.id IS NULL OR NOT(p_caps->>'can_capture_incoming')::boolean THEN PERFORM public.uc_document_registry_error('NOT_FOUND');END IF;
  PERFORM public.uc_document_registry_source_lock(p_org,item->'linked_source',true);src:=public.uc_document_registry_source(p_org,item->'linked_source',false,false);SELECT*INTO link FROM public.uc_document_registry_incoming_sources WHERE incoming_document_id=i.id AND organization_id=p_org;
  item:=item||jsonb_build_object('source_label',src->'label','source_available',src IS NOT NULL,'can_open_file',src IS NOT NULL,'can_register',(p_caps->>'can_register_incoming')::boolean AND link.record_id IS NULL);
  RETURN result||public.uc_document_registry_base(p_org,p_scope)||jsonb_build_object('replayed',true,'incoming',item);
 END IF;
 item:=result->'record';SELECT*INTO r FROM public.uc_document_registry_records WHERE id=(item->>'id')::uuid AND organization_id=p_org AND NOT redacted AND(g IS NULL OR g=ANY(scope_group_ids));IF r.id IS NULL THEN PERFORM public.uc_document_registry_error('NOT_FOUND');END IF;
 IF result->>'kind'<>'archive'THEN proof:=public.uc_document_registry_write_proof(p_org,r.group_id,item->'data');END IF;
 src:=public.uc_document_registry_source(p_org,item->'data'->'source',false,false);
 BEGIN ctx:=public.uc_document_registry_context(p_org,r.group_id,item->'data'->'subject',item->'data'->'context',true);current_context:=ctx->'binding'=item->'context_binding';EXCEPTION WHEN SQLSTATE'22023'OR SQLSTATE'42501'OR SQLSTATE'PT409'OR SQLSTATE'PT404'THEN IF SQLERRM NOT LIKE'DOCUMENT_REGISTRY_%'THEN RAISE;END IF;current_context:=false;END;
 same_current:=r.revision=(item->>'revision')::bigint AND r.data=item->'data'AND r.status=item->>'status';
 item:=item||jsonb_build_object('source_label',src->'label','source_available',src IS NOT NULL,'context_label',CASE WHEN current_context THEN ctx->>'label'ELSE'Связь изменена; прежние идентификаторы сохранены'END,'context_current',current_context,'can_open_file',(p_caps->>'can_open_file')::boolean AND src IS NOT NULL,'can_correct',(p_caps->>'can_correct')::boolean AND same_current AND current_context AND src IS NOT NULL AND r.status='registered','can_archive',(p_caps->>'can_archive')::boolean AND same_current AND r.status='registered');
 RETURN result||public.uc_document_registry_base(p_org,p_scope)||jsonb_build_object('replayed',true,'record',item);END;$function$

CREATE OR REPLACE FUNCTION public.uc_document_registry_write_proof(p_org uuid, p_group uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE proof jsonb;after_proof jsonb;people uuid[];group_ids uuid[];BEGIN
 proof:=public.uc_document_registry_data(p_org,p_group,p_data,true);SELECT coalesce(array_agg(x::uuid),'{}')INTO people FROM jsonb_array_elements_text(proof->'participants')x;PERFORM public.uc_document_registry_fence(p_org,p_group,people,true,NULL);
 PERFORM public.uc_document_registry_source_lock(p_org,p_data->'source',false);
 IF proof->'context_binding'->>'enrollment_id'IS NOT NULL THEN PERFORM 1 FROM public.enrollments WHERE id=(proof->'context_binding'->>'enrollment_id')::uuid FOR SHARE NOWAIT;END IF;
 IF proof->'context_binding'->>'course_id'IS NOT NULL THEN PERFORM 1 FROM public.courses WHERE id=(proof->'context_binding'->>'course_id')::uuid FOR SHARE NOWAIT;END IF;
 IF proof->'context_binding'->>'contract_id'IS NOT NULL THEN PERFORM 1 FROM public.org_contracts WHERE id=(proof->'context_binding'->>'contract_id')::uuid FOR SHARE NOWAIT;END IF;
 SELECT coalesce(array_agg(x::uuid),'{}')INTO group_ids FROM jsonb_array_elements_text(proof->'groups')x;PERFORM 1 FROM public.student_groups WHERE organization_id=p_org AND id=ANY(group_ids)ORDER BY id FOR SHARE NOWAIT;
 after_proof:=public.uc_document_registry_data(p_org,p_group,p_data,true);IF after_proof IS DISTINCT FROM proof THEN PERFORM public.uc_document_registry_error('CONTEXT_CHANGED');END IF;RETURN after_proof;END;$function$

CREATE OR REPLACE FUNCTION public.uc_erase_group_education_facts(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE job uuid;job_count integer;scopes jsonb;scope jsonb;o uuid;g uuid;t text;r record;value jsonb;old_row jsonb;columns text;id_column text;current_context jsonb;enrollment_ids uuid[];snapshot_ids uuid[];operational boolean;
BEGIN
 IF p_user IS NULL OR auth.role()IS DISTINCT FROM'service_role'OR auth.uid()IS NOT NULL OR current_setting('sintagma.account_deletion_erase_user',true)IS DISTINCT FROM p_user::text OR NOT EXISTS(SELECT 1 FROM public.account_deletion_revocations WHERE user_id=p_user)THEN RAISE EXCEPTION 'GROUP_FACTS_ACCESS_DENIED' USING ERRCODE='42501';END IF;
 SELECT count(*)INTO job_count FROM public.account_deletion_jobs WHERE user_id=p_user AND state='cleanup_pending'AND consent_version='full-personal-data-v1';
 IF job_count<>1 THEN RAISE EXCEPTION 'GROUP_FACTS_ACCESS_DENIED' USING ERRCODE='42501';END IF;
 SELECT id INTO job FROM public.account_deletion_jobs WHERE user_id=p_user AND state='cleanup_pending'AND consent_version='full-personal-data-v1'FOR UPDATE NOWAIT;
 IF NOT pg_try_advisory_xact_lock(hashtextextended(p_user::text,42007))THEN RAISE EXCEPTION 'GROUP_FACTS_SOURCE_CHANGED' USING ERRCODE='40001';END IF;
 -- Collect exact individual association anchors from own nested subject rows,
 -- including association-event payloads inheriting the explicit root subject.
 WITH RECURSIVE roots(v)AS(
  SELECT to_jsonb(x)FROM public.uc_group_education_states x WHERE position(p_user::text IN to_jsonb(x)::text)>0
  UNION ALL SELECT to_jsonb(x)FROM public.uc_group_education_events x WHERE position(p_user::text IN to_jsonb(x)::text)>0
  UNION ALL SELECT to_jsonb(x)FROM public.uc_group_calendar_versions x WHERE position(p_user::text IN to_jsonb(x)::text)>0
  UNION ALL SELECT to_jsonb(x)FROM public.uc_group_roster_snapshots x WHERE position(p_user::text IN to_jsonb(x)::text)>0
  UNION ALL SELECT to_jsonb(x)FROM public.uc_group_education_requests x WHERE position(p_user::text IN to_jsonb(x)::text)>0
 ),walk(v,own)AS(
  SELECT v,coalesce(v->>'user_id'=p_user::text OR v->>'subject_user_id'=p_user::text,false)FROM roots
  UNION ALL SELECT child.v,coalesce(child.v->>'user_id'=p_user::text OR child.v->>'subject_user_id'=p_user::text,false)OR(w.own AND NOT EXISTS(SELECT 1 FROM jsonb_each(CASE WHEN jsonb_typeof(child.v)='object'THEN child.v ELSE'{}'END)e WHERE e.key IN('user_id','subject_user_id','actor_id','staff_user_id','teacher_user_id')AND jsonb_typeof(e.value)='string'AND e.value<>to_jsonb(p_user)))
  FROM walk w CROSS JOIN LATERAL(SELECT e.value v FROM jsonb_each(CASE WHEN jsonb_typeof(w.v)='object'THEN w.v ELSE'{}'END)e UNION ALL SELECT e.value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(w.v)='array'THEN w.v ELSE'[]'END)e(value))child
 )SELECT coalesce(array_agg(DISTINCT(v->>'enrollment_id')::uuid)FILTER(WHERE own AND v->>'enrollment_id'IS NOT NULL),'{}'),coalesce(array_agg(DISTINCT(v->>'program_enrollment_snapshot_id')::uuid)FILTER(WHERE own AND v->>'program_enrollment_snapshot_id'IS NOT NULL),'{}')INTO enrollment_ids,snapshot_ids FROM walk;
 SELECT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=p_user)OR EXISTS(SELECT 1 FROM public.enrollments WHERE user_id=p_user)OR EXISTS(SELECT 1 FROM public.student_group_memberships WHERE user_id=p_user)INTO operational;
 WITH raw AS(
  SELECT organization_id o,group_id g,course_id c FROM public.uc_group_education_states x WHERE position(p_user::text IN to_jsonb(x)::text)>0
  UNION SELECT organization_id,group_id,course_id FROM public.uc_group_education_events x WHERE position(p_user::text IN to_jsonb(x)::text)>0
  UNION SELECT organization_id,group_id,course_id FROM public.uc_group_calendar_versions x WHERE position(p_user::text IN to_jsonb(x)::text)>0
  UNION SELECT organization_id,group_id,course_id FROM public.uc_group_roster_snapshots x WHERE position(p_user::text IN to_jsonb(x)::text)>0
  UNION SELECT organization_id,group_id,course_id FROM public.uc_group_education_requests x WHERE group_id IS NOT NULL AND position(p_user::text IN to_jsonb(x)::text)>0
  UNION SELECT s.organization_id,s.group_id,s.course_id FROM public.uc_group_education_states s JOIN public.uc_group_education_requests q ON q.row_kind='source_parent'AND position(p_user::text IN to_jsonb(q)::text)>0 AND(
   q.context->'old_tuple'->>'organization_id'=s.organization_id::text OR q.context->'old_tuple'->>'group_id'=s.group_id::text OR q.context->'old_tuple'->>'student_group_id'=s.group_id::text OR q.context->'old_tuple'->>'course_id'=s.course_id::text
   OR q.context->>'parent_table'='student_groups'AND q.context->'old_tuple'->>'id'=s.group_id::text OR q.context->>'parent_table'='courses'AND q.context->'old_tuple'->>'id'=s.course_id::text OR q.context->>'parent_table'='organizations'AND q.context->'old_tuple'->>'id'=s.organization_id::text)
 )SELECT coalesce(jsonb_agg(jsonb_build_object('organization_id',z.o,'group_id',z.g,'course_id',z.c)ORDER BY z.o,z.g),'[]')INTO scopes FROM raw z WHERE z.o IS NOT NULL AND z.g IS NOT NULL AND z.c IS NOT NULL;
 -- Complete O then complete G, sorted, try-only; no foreign account A locks.
 FOR o IN SELECT DISTINCT(x.value->>'organization_id')::uuid FROM jsonb_array_elements(scopes)x(value)ORDER BY 1 LOOP IF NOT pg_try_advisory_xact_lock(hashtextextended(o::text,0))THEN RAISE EXCEPTION 'GROUP_FACTS_SOURCE_CHANGED' USING ERRCODE='40001';END IF;END LOOP;
 FOR g IN SELECT DISTINCT(x.value->>'group_id')::uuid FROM jsonb_array_elements(scopes)x(value)ORDER BY 1 LOOP IF NOT pg_try_advisory_xact_lock(hashtextextended('uc_program_roster:'||g::text,0))THEN RAISE EXCEPTION 'GROUP_FACTS_SOURCE_CHANGED' USING ERRCODE='40001';END IF;END LOOP;
 FOREACH t IN ARRAY ARRAY['uc_group_education_states','uc_group_education_events','uc_group_calendar_versions','uc_group_roster_snapshots','uc_group_education_requests']LOOP
  id_column:=CASE WHEN t='uc_group_education_states'THEN'group_id'ELSE'id'END;
  FOR r IN EXECUTE format('SELECT %I id FROM public.%I x WHERE position($1 IN to_jsonb(x)::text)>0 ORDER BY %I FOR UPDATE NOWAIT',id_column,t,id_column)USING p_user::text LOOP NULL;END LOOP;
 END LOOP;
 FOR scope IN SELECT x.value FROM jsonb_array_elements(scopes)x(value)LOOP
  current_context:=jsonb_build_object('schema_version',1,'p_user',p_user,'cleanup_job_id',job);
  INSERT INTO public.uc_group_education_requests(row_kind,organization_id,group_id,course_id,backend_pid,full_transaction_id,context,subject_ids,actor_ids,teacher_ids)
  VALUES('erase_context',(scope->>'organization_id')::uuid,(scope->>'group_id')::uuid,(scope->>'course_id')::uuid,pg_backend_pid(),pg_current_xact_id()::text,current_context,ARRAY[p_user],'{}','{}')ON CONFLICT DO NOTHING;
  IF NOT EXISTS(SELECT 1 FROM public.uc_group_education_requests q WHERE row_kind='erase_context'AND q.organization_id=(scope->>'organization_id')::uuid AND q.group_id=(scope->>'group_id')::uuid AND q.course_id=(scope->>'course_id')::uuid AND q.backend_pid=pg_backend_pid()AND q.full_transaction_id=pg_current_xact_id()::text AND q.context=current_context AND q.subject_ids=ARRAY[p_user]AND q.actor_ids='{}'AND q.teacher_ids='{}')THEN RAISE EXCEPTION 'GROUP_FACTS_ACCESS_DENIED' USING ERRCODE='42501';END IF;
 END LOOP;
 -- Remove only the erased SUBJECT stage, never another student's actor attribution.
 DELETE FROM public.uc_group_education_requests WHERE row_kind='source_detail'AND request_id=p_user;
 DELETE FROM public.uc_group_education_requests q WHERE q.row_kind IN('command','source_parent')AND position(p_user::text IN to_jsonb(q)::text)>0;
 FOREACH t IN ARRAY ARRAY['uc_group_education_states','uc_group_education_events','uc_group_calendar_versions','uc_group_roster_snapshots','uc_group_education_requests']LOOP
  id_column:=CASE WHEN t='uc_group_education_states'THEN'group_id'ELSE'id'END;
  FOR r IN EXECUTE format('SELECT to_jsonb(x)old_row FROM public.%I x WHERE position($1 IN to_jsonb(x)::text)>0 %s ORDER BY %I',t,CASE WHEN t='uc_group_education_requests'THEN'AND row_kind<>''erase_context'''ELSE''END,id_column)USING p_user::text LOOP
   old_row:=r.old_row;value:=public.uc_group_education_redact(old_row,p_user,false,false,enrollment_ids,snapshot_ids);
   IF t='uc_group_education_states'AND(value->'source_rows'IS DISTINCT FROM old_row->'source_rows'OR value->'program_proof'IS DISTINCT FROM old_row->'program_proof')THEN value:=value||jsonb_build_object('source_redacted',true);
   ELSIF t='uc_group_education_events'AND(old_row->>'subject_user_id'=p_user::text OR value->'source_snapshot'IS DISTINCT FROM old_row->'source_snapshot'OR value->'previous_row'IS DISTINCT FROM old_row->'previous_row'OR value->'next_row'IS DISTINCT FROM old_row->'next_row'OR value->'payload'IS DISTINCT FROM old_row->'payload')THEN value:=value||jsonb_build_object('redacted',true);
   ELSIF t='uc_group_calendar_versions'AND(value->'lessons'IS DISTINCT FROM old_row->'lessons'OR value->'content'IS DISTINCT FROM old_row->'content'OR value->'teacher_proofs'IS DISTINCT FROM old_row->'teacher_proofs')THEN value:=value||jsonb_build_object('redacted',true);
   ELSIF t='uc_group_roster_snapshots'AND(value->'roster_rows'IS DISTINCT FROM old_row->'roster_rows'OR value->'source_input'IS DISTINCT FROM old_row->'source_input'OR value->'program_proof'IS DISTINCT FROM old_row->'program_proof')THEN value:=value||jsonb_build_object('redacted',true);END IF;
   IF value IS DISTINCT FROM old_row THEN
    SELECT string_agg(quote_ident(attname),','ORDER BY attnum)INTO columns FROM pg_attribute WHERE attrelid=('public.'||t)::regclass AND attnum>0 AND NOT attisdropped;
    EXECUTE format('UPDATE public.%I SET(%s)=(SELECT %s FROM jsonb_populate_record(NULL::public.%I,$1))WHERE %I=$2',t,columns,columns,t,id_column)USING value,(old_row->>id_column)::uuid;
   END IF;
  END LOOP;
 END LOOP;
 -- Recompute live byte/count caches once from current post-redaction staging.
 -- Receipt/global admission counters are deliberately never refunded.
 WITH caches AS MATERIALIZED(
  SELECT q.id,count(d.id)::integer n,CASE WHEN count(d.id)=0 THEN 2 ELSE sum(octet_length((d.context->'detail')::text)+42)END bytes
  FROM public.uc_group_education_requests q LEFT JOIN public.uc_group_education_requests d ON d.row_kind='source_detail'AND d.group_id=q.group_id AND d.backend_pid=q.backend_pid AND d.full_transaction_id=q.full_transaction_id
  WHERE q.row_kind='source_pending'AND q.group_id IN(SELECT(x->>'group_id')::uuid FROM jsonb_array_elements(scopes)x)GROUP BY q.id
 )UPDATE public.uc_group_education_requests q SET context=q.context||jsonb_build_object('live_detail_count',z.n,'detail_map_serialized_bytes',z.bytes)FROM caches z WHERE q.id=z.id AND(q.context->'live_detail_count',q.context->'detail_map_serialized_bytes')IS DISTINCT FROM(to_jsonb(z.n),to_jsonb(z.bytes));
 IF NOT operational THEN DELETE FROM public.uc_group_education_requests WHERE row_kind='erase_context'AND backend_pid=pg_backend_pid()AND full_transaction_id=pg_current_xact_id()::text AND context=jsonb_build_object('schema_version',1,'p_user',p_user,'cleanup_job_id',job)AND subject_ids=ARRAY[p_user]AND actor_ids='{}'AND teacher_ids='{}';END IF;
 -- Current trusted erase_context intentionally survives until source cleanup
 -- sees all operational subject rows gone. Inventory counts it: no false done.
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'GROUP_FACTS_SOURCE_CHANGED' USING ERRCODE='40001';
END;$function$

CREATE OR REPLACE FUNCTION public.uc_erase_identification_data(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE record_id uuid;BEGIN
 -- Called only from the receipt-validated original erase wrapper after its lock,
 -- current plan/file checks and exact revoked-subject context. Never lock others.
 IF auth.role() IS DISTINCT FROM 'service_role' OR auth.uid() IS NOT NULL OR current_setting('sintagma.account_deletion_erase_user',true) IS DISTINCT FROM p_user::text
 OR NOT EXISTS(SELECT 1 FROM public.account_deletion_revocations WHERE user_id=p_user) THEN RAISE EXCEPTION 'IDENTIFICATION_ACCESS_DENIED' USING ERRCODE='42501';END IF;
 -- Cross-reviewed erasures share a deterministic parent-row order before any
 -- own deletion/foreign attribution update. No unrelated advisory lock is taken.
 FOR record_id IN SELECT r.id FROM public.uc_identification_records r WHERE r.user_id=p_user OR r.decided_by=p_user
 OR EXISTS(SELECT 1 FROM public.uc_identification_events e WHERE e.identification_id=r.id AND e.actor_id=p_user)
 OR EXISTS(SELECT 1 FROM public.uc_identification_requests q WHERE q.identification_id=r.id AND q.actor_id=p_user) ORDER BY r.id LOOP
  PERFORM 1 FROM public.uc_identification_records WHERE id=record_id FOR UPDATE;
 END LOOP;
 INSERT INTO public.uc_identification_write_contexts(kind,user_id,actor_id)VALUES('subject_erase',p_user,p_user),('reviewer_erase',p_user,p_user);
 DELETE FROM public.uc_identification_requests WHERE actor_id=p_user OR identification_id IN(SELECT id FROM public.uc_identification_records WHERE user_id=p_user);
 DELETE FROM public.uc_identification_events WHERE user_id=p_user;
 DELETE FROM public.uc_identification_sources WHERE user_id=p_user;
 DELETE FROM public.uc_identification_records WHERE user_id=p_user;
 UPDATE public.uc_identification_records SET decided_by=NULL WHERE decided_by=p_user;
 UPDATE public.uc_identification_events SET actor_id=NULL WHERE actor_id=p_user;
END;$function$

CREATE OR REPLACE FUNCTION public.uc_group_education_personal_counts(p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE t text;n bigint;result jsonb:='[]';BEGIN
 IF p_user IS NULL THEN RETURN result;END IF;
 FOREACH t IN ARRAY ARRAY['uc_group_education_states','uc_group_education_events','uc_group_calendar_versions','uc_group_roster_snapshots','uc_group_education_requests']LOOP
  EXECUTE format('SELECT count(*)FROM public.%I x WHERE position($1 IN to_jsonb(x)::text)>0',t)INTO n USING p_user::text;
  IF n>0 THEN result:=result||jsonb_build_array(jsonb_build_object('table',t,'column','private_source_and_attribution','count',n));END IF;
 END LOOP;RETURN result;
END;$function$

CREATE OR REPLACE FUNCTION public.uc_learning_erase_user(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('sintagma.account_deletion_erase_user',true) IS DISTINCT FROM p_user::text OR NOT EXISTS(SELECT 1 FROM public.account_deletion_revocations WHERE user_id=p_user) THEN PERFORM public.uc_learning_error('ACCESS_DENIED');END IF;
 DELETE FROM public.uc_learning_outcome_requests WHERE participant_ids @> ARRAY[p_user];
 DELETE FROM public.uc_learning_attestation_decisions WHERE user_id=p_user;
 DELETE FROM public.uc_learning_machine_results WHERE user_id=p_user;
 DELETE FROM public.uc_learning_attempt_contexts WHERE user_id=p_user;
 DELETE FROM public.uc_learning_outcome_states WHERE user_id=p_user;
 -- Approved rules remain a nonpersonal immutable reference. The erased copy is
 -- no longer usable as criteria, and no human name/text/UUID survives inside it.
 UPDATE public.uc_learning_criteria_versions SET redacted=true,definition='{}',created_by=NULL,reviewer_id=NULL,approved_by=NULL,participant_ids='{}' WHERE participant_ids @> ARRAY[p_user];
 UPDATE public.uc_learning_attestation_decisions SET redacted=true,actor_id=NULL,staff_reason='Атрибуция и личный текст удалены.',learner_summary='Сохранён итог без личного текста удалённого сотрудника.',authority_snapshot='{}',source_proof='{}',participant_ids=array_remove(participant_ids,p_user) WHERE participant_ids @> ARRAY[p_user];
 IF public.uc_learning_personal_counts(p_user)<>'[]'::jsonb THEN PERFORM public.uc_learning_error('DEPENDENCY_UNAVAILABLE');END IF;
END;$function$

CREATE OR REPLACE FUNCTION public.uc_learning_validate_criteria(p_org uuid, p_course uuid, p_definition jsonb, p_complete boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x jsonb;m jsonb;modules jsonb:='[]';ids uuid[]:='{}';lessons uuid[];n integer:=0;u uuid;BEGIN
 IF NOT public.uc_learning_shape(p_definition,ARRAY['schema_version','main','requirements','reviewer_id','independent_review_required','eligible_decider_ids','recognition_component_ids','recognition_file_version_ids','review_note'])
 OR p_definition->'schema_version' IS DISTINCT FROM '1'::jsonb
 OR jsonb_typeof(p_definition->'requirements') IS DISTINCT FROM 'array' OR jsonb_array_length(p_definition->'requirements')>19
 OR jsonb_typeof(p_definition->'independent_review_required') IS DISTINCT FROM 'boolean'
 OR NOT public.uc_learning_ids(p_definition->'eligible_decider_ids',0,20)
 OR NOT public.uc_learning_ids(p_definition->'recognition_component_ids',0,20)
 OR NOT public.uc_learning_ids(p_definition->'recognition_file_version_ids',0,5)
 OR NOT public.uc_learning_text(p_definition->'review_note',2000)
 OR NOT(p_definition->'reviewer_id'='null'::jsonb OR public.uc_learning_uuid(p_definition->'reviewer_id')) THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
 m:=p_definition->'main';
 IF m<>'null'::jsonb THEN
  IF NOT public.uc_learning_validate_test(m) AND NOT coalesce(public.uc_learning_shape(m,ARRAY['kind','component_id','label']) AND m->>'kind'='human_assessment' AND public.uc_learning_uuid(m->'component_id') AND public.uc_learning_text(m->'label',500),false) THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
  ids:=ARRAY[(m->>'component_id')::uuid];
 END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(p_definition->'requirements') LOOP
  IF NOT public.uc_learning_validate_test(x) AND NOT coalesce(public.uc_learning_shape(x,ARRAY['kind','component_id','module_id']) AND x->>'kind'='module_completion' AND public.uc_learning_uuid(x->'component_id') AND public.uc_learning_uuid(x->'module_id'),false) THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
  IF (x->>'component_id')::uuid=ANY(ids) THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;ids:=ids||(x->>'component_id')::uuid;
 END LOOP;
 IF NOT p_complete THEN RETURN modules;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_definition->'recognition_component_ids') AS elem(value) WHERE NOT(elem.value::uuid=ANY(ids))) OR (jsonb_array_length(p_definition->'recognition_component_ids')=0)<>(jsonb_array_length(p_definition->'recognition_file_version_ids')=0) THEN PERFORM public.uc_learning_error('INVALID_INPUT');END IF;
 IF m='null'::jsonb OR p_definition->'reviewer_id'='null'::jsonb OR jsonb_array_length(p_definition->'eligible_decider_ids')=0 THEN PERFORM public.uc_learning_error('PREREQUISITE_MISSING');END IF;
 IF NOT public.uc_learning_staff((p_definition->>'reviewer_id')::uuid,p_org,NULL,true) THEN PERFORM public.uc_learning_error('PREREQUISITE_MISSING');END IF;
 FOR u IN SELECT value::text::uuid FROM jsonb_array_elements_text(p_definition->'eligible_decider_ids') LOOP
  IF NOT(public.uc_learning_staff(u,p_org,NULL,true) OR EXISTS(SELECT 1 FROM public.student_groups g WHERE g.organization_id=p_org AND g.course_id=p_course AND public.uc_learning_staff(u,p_org,g.id,true))) THEN PERFORM public.uc_learning_error('PREREQUISITE_MISSING');END IF;
 END LOOP;
 FOR u IN SELECT value::text::uuid FROM jsonb_array_elements_text(p_definition->'recognition_file_version_ids') LOOP
  IF NOT public.uc_program_active_file_proof(p_org,u) THEN PERFORM public.uc_learning_error('SOURCE_UNAVAILABLE');END IF;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(jsonb_build_array(m)||(p_definition->'requirements')) LOOP
  IF x->>'kind'='test' THEN
   IF NOT EXISTS(SELECT 1 FROM public.lessons l WHERE l.id=(x->>'lesson_id')::uuid AND l.course_id=p_course AND l.type='test') THEN PERFORM public.uc_learning_error('PREREQUISITE_MISSING');END IF;
  ELSIF x->>'kind'='module_completion' THEN
   IF NOT EXISTS(SELECT 1 FROM public.course_modules WHERE id=(x->>'module_id')::uuid AND course_id=p_course) THEN PERFORM public.uc_learning_error('PREREQUISITE_MISSING');END IF;
   SELECT array_agg(id ORDER BY id) INTO lessons FROM public.lessons WHERE module_id=(x->>'module_id')::uuid AND course_id=p_course;
   IF coalesce(cardinality(lessons),0)=0 THEN PERFORM public.uc_learning_error('PREREQUISITE_MISSING');END IF;
   n:=n+cardinality(lessons);IF n>250 THEN PERFORM public.uc_learning_error('LIMIT_EXCEEDED');END IF;
   modules:=modules||jsonb_build_array(jsonb_build_object('component_id',x->'component_id','module_id',x->'module_id','lesson_ids',to_jsonb(lessons)));
  END IF;
 END LOOP;
 -- Preserve the existing final-photo selector; never silently change its lesson.
 IF m->>'kind'='test' AND EXISTS(SELECT 1 FROM public.courses c WHERE c.id=p_course AND coalesce((to_jsonb(c)->>'require_final_test_photo')::boolean,false)) AND NOT public._final_test_photo_required((m->>'lesson_id')::uuid) THEN PERFORM public.uc_learning_error('PHOTO_POLICY_MISMATCH');END IF;
 RETURN modules;
END;$function$

CREATE OR REPLACE FUNCTION public.uc_session_erase_user(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('sintagma.account_deletion_erase_user',true) IS DISTINCT FROM p_user::text OR NOT EXISTS(SELECT 1 FROM public.account_deletion_revocations WHERE user_id=p_user) THEN PERFORM public.uc_session_error('ACCESS_DENIED');END IF;
 DELETE FROM public.uc_conducted_session_requests WHERE participant_ids @> ARRAY[p_user];
 UPDATE public.uc_conducted_session_versions SET attendance=public.uc_session_redact(attendance,p_user),source_proof=public.uc_session_redact(source_proof,p_user),authority_snapshot='{}',reason='Личные сведения удалены.',actor_id=CASE WHEN actor_id=p_user THEN NULL ELSE actor_id END,teacher_user_id=CASE WHEN teacher_user_id=p_user THEN NULL ELSE teacher_user_id END,participant_ids=array_remove(participant_ids,p_user),redacted=true WHERE participant_ids @> ARRAY[p_user];
 UPDATE public.uc_session_document_drafts SET source_proof=public.uc_session_redact(source_proof,p_user),reason='Личные сведения удалены.',actor_id=CASE WHEN actor_id=p_user THEN NULL ELSE actor_id END,participant_ids=array_remove(participant_ids,p_user),redacted=true WHERE participant_ids @> ARRAY[p_user];
 -- Hashes remain historical commitments, explicitly invalid for further use.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(public.uc_session_personal_counts(p_user))x WHERE (x->>'count')::bigint<>0) THEN PERFORM public.uc_session_error('SOURCE_UNAVAILABLE');END IF;
END;$function$

CREATE OR REPLACE FUNCTION public.storage_try_uuid(_value text)
 RETURNS uuid
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
BEGIN
  IF _value IS NULL THEN RETURN NULL; END IF;
  RETURN _value::uuid;
EXCEPTION WHEN others THEN
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.uc_document_registry_data(p_org uuid, p_group uuid, p_data jsonb, p_check_context boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE src jsonb;sender jsonb;recipient jsonb;ctx jsonb;origin jsonb:=p_data->'origin';legacy jsonb;people uuid[]:='{}';part jsonb;typ text:=p_data->>'document_type';BEGIN
 IF NOT public.uc_custom_journal_shape(p_data,ARRAY['direction','document_type','title','document_date','declared_document_number','source','sender','recipient','subject','context','origin','notes'])OR NOT coalesce(p_data->>'direction'IN('incoming','outgoing'),false)
 OR NOT coalesce(typ IN('contract','enrollment_order','expulsion_order','certificate','diploma','qualification','protocol','invoice','act','other'),false)OR NOT public.uc_document_registry_text(p_data->'title',500)OR NOT public.uc_copy_registry_date(p_data->'document_date')
 OR NOT(p_data->'declared_document_number'='null'::jsonb OR public.uc_document_registry_text(p_data->'declared_document_number',120,true))OR NOT public.uc_document_registry_text(p_data->'notes',4000,true)THEN PERFORM public.uc_document_registry_error('INVALID_INPUT');END IF;
 src:=public.uc_document_registry_source(p_org,p_data->'source',true,false);sender:=public.uc_document_registry_party(p_org,p_group,p_data->'sender');recipient:=public.uc_document_registry_party(p_org,p_group,p_data->'recipient');ctx:=public.uc_document_registry_context(p_org,p_group,p_data->'subject',p_data->'context',p_check_context);
 IF(p_data->>'direction'='incoming'AND p_data->'recipient'<>jsonb_build_object('kind','organization','organization_id',p_org))OR(p_data->>'direction'='outgoing'AND p_data->'sender'<>jsonb_build_object('kind','organization','organization_id',p_org))THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;
 IF p_data->>'direction'='outgoing'AND typ IN('enrollment_order','expulsion_order','certificate','diploma','qualification')AND(p_data->'subject'->>'kind'IS DISTINCT FROM'student'OR p_data->'context'->>'kind'NOT IN('enrollment','enrollment_contract'))THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;
 IF p_data->>'direction'='outgoing'AND p_data->'recipient'->>'kind'='student'AND ctx->'binding'->>'user_id'IS DISTINCT FROM p_data->'recipient'->>'user_id'THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;
 IF ctx->'binding'->>'contract_company_id'IS NOT NULL AND(p_data->'sender'->>'kind'='company'AND p_data->'sender'->>'company_id'<>ctx->'binding'->>'contract_company_id'OR p_data->'recipient'->>'kind'='company'AND p_data->'recipient'->>'company_id'<>ctx->'binding'->>'contract_company_id')THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;
 IF public.uc_custom_journal_shape(origin,ARRAY['kind'])AND origin->>'kind'='org_document'THEN NULL;
 ELSIF public.uc_custom_journal_shape(origin,ARRAY['kind','incoming_document_id'])AND origin->>'kind'='incoming_document'AND public.uc_custom_journal_uuid(origin->'incoming_document_id')THEN
  IF p_data->>'direction'<>'incoming'OR NOT EXISTS(SELECT 1 FROM public.incoming_documents i WHERE i.id=(origin->>'incoming_document_id')::uuid AND i.organization_id=p_org AND i.deleted_at IS NULL AND(i.related_company_id IS NULL OR p_data->'sender'=jsonb_build_object('kind','company','company_id',i.related_company_id)))THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;
 ELSIF public.uc_custom_journal_shape(origin,ARRAY['kind','legacy_id','legacy_binding_hash','relationship_reason'])AND origin->>'kind'='legacy_issuance_log'AND public.uc_custom_journal_uuid(origin->'legacy_id')AND coalesce(origin->>'legacy_binding_hash','')~'^[a-f0-9]{64}$'AND public.uc_document_registry_text(origin->'relationship_reason',2000)THEN
  legacy:=public.uc_document_registry_legacy(p_org,p_group,(origin->>'legacy_id')::uuid);IF legacy->>'legacy_binding_hash'<>origin->>'legacy_binding_hash'THEN PERFORM public.uc_document_registry_error('CONTEXT_CHANGED');END IF;
  IF legacy->>'enrollment_id'IS NOT NULL AND legacy->>'enrollment_id'IS DISTINCT FROM ctx->'binding'->>'enrollment_id'THEN PERFORM public.uc_document_registry_error('CONTEXT_MISMATCH');END IF;
 ELSE PERFORM public.uc_document_registry_error('INVALID_INPUT');END IF;
 FOR part IN SELECT value FROM jsonb_array_elements(jsonb_build_array(src,sender,recipient,ctx))LOOP people:=people||ARRAY(SELECT x::uuid FROM jsonb_array_elements_text(part->'participants')x);END LOOP;
 SELECT coalesce(array_agg(DISTINCT x ORDER BY x),'{}')INTO people FROM unnest(people)x WHERE x IS NOT NULL;
 RETURN jsonb_build_object('participants',to_jsonb(people),'groups',ctx->'groups','context_binding',ctx->'binding','source_label',src->'label','sender_label',sender->'label','recipient_label',recipient->'label','subject_label',CASE WHEN p_data->'subject'->>'kind'='student'THEN public.uc_copy_registry_label((p_data->'subject'->>'user_id')::uuid)ELSE NULL END,'context_label',ctx->'label','legacy_claim',legacy->'claim');END;$function$

CREATE OR REPLACE FUNCTION public.uc_group_education_redact(p_value jsonb, p_user uuid, p_force boolean DEFAULT false, p_subject_scope boolean DEFAULT false, p_enrollment_ids uuid[] DEFAULT '{}'::uuid[], p_snapshot_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;k text;v jsonb;subject boolean;teacher boolean;actor boolean;author boolean;inherited boolean;attribution boolean;
BEGIN
 IF p_value IS NULL OR p_user IS NULL THEN RETURN p_value;END IF;
 IF jsonb_typeof(p_value)='array'THEN SELECT coalesce(jsonb_agg(public.uc_group_education_redact(x,p_user,p_force,p_subject_scope,p_enrollment_ids,p_snapshot_ids)),'[]')INTO result FROM jsonb_array_elements(p_value)x;RETURN result;
 ELSIF jsonb_typeof(p_value)<>'object'THEN RETURN p_value;END IF;
 subject:=coalesce(p_value->>'user_id'=p_user::text OR p_value->>'subject_user_id'=p_user::text,false);
 inherited:=p_subject_scope AND NOT EXISTS(SELECT 1 FROM jsonb_each(p_value)e WHERE e.key IN('user_id','subject_user_id','actor_id','staff_user_id','teacher_user_id')AND jsonb_typeof(e.value)='string'AND e.value<>to_jsonb(p_user));subject:=subject OR inherited;
 teacher:=coalesce(p_value->>'teacher_user_id'=p_user::text,false);
 actor:=EXISTS(SELECT 1 FROM jsonb_each(p_value)e WHERE e.key IN('actor_id','last_actor_id','reviewer_id','staff_user_id')AND e.value=to_jsonb(p_user));
 author:=EXISTS(SELECT 1 FROM jsonb_each(p_value)e WHERE e.key IN('recorded_by','published_by','created_by')AND e.value=to_jsonb(p_user));
 attribution:=actor OR(coalesce(p_force,false)AND NOT EXISTS(SELECT 1 FROM jsonb_each(p_value)e WHERE e.key IN('actor_id','last_actor_id','user_id','subject_user_id','teacher_user_id','staff_user_id')AND jsonb_typeof(e.value)='string'AND e.value<>to_jsonb(p_user)));
 result:='{}';FOR k,v IN SELECT * FROM jsonb_each(p_value)LOOP
  IF k=p_user::text THEN CONTINUE;
  ELSIF k IN('user_id','subject_user_id','actor_id','last_actor_id','recorded_by','published_by','created_by','reviewer_id','staff_user_id','teacher_user_id')AND v=to_jsonb(p_user)THEN v:='null';
  ELSIF k IN('subject_ids','actor_ids','teacher_ids','student_user_ids')AND jsonb_typeof(v)='array'THEN SELECT coalesce(jsonb_agg(x),'[]')INTO v FROM jsonb_array_elements(v)x WHERE x IS DISTINCT FROM to_jsonb(p_user);
  ELSIF k='enrollment_id'AND(subject OR v=ANY(SELECT to_jsonb(x)FROM unnest(p_enrollment_ids)x))THEN v:='null';
  ELSIF k='program_enrollment_snapshot_id'AND(subject OR v=ANY(SELECT to_jsonb(x)FROM unnest(p_snapshot_ids)x))THEN v:='null';
  ELSIF k='enrollment_snapshot_ids'AND jsonb_typeof(v)='array'THEN SELECT coalesce(jsonb_agg(x),'[]')INTO v FROM jsonb_array_elements(v)x WHERE NOT(x=ANY(SELECT to_jsonb(y)FROM unnest(p_snapshot_ids)y));
  ELSIF (subject OR teacher)AND k IN('subject_label','teacher_label','full_name','label','label_source','label_observed_at','teacher_label_source','teacher_label_observed_at','teacher_source_hash')THEN v:='null';
  ELSIF (subject OR teacher)AND k IN('label_state','teacher_label_state')THEN v:=to_jsonb('redacted'::text);
  ELSIF (attribution OR subject OR teacher)AND k IN('staff_id','org_staff_id','staff_label')THEN v:='null';
  ELSIF (actor OR author OR attribution OR subject OR teacher)AND k IN('reason','correction_reason')AND v<>'null'THEN v:='null';
  ELSIF subject AND k='id'AND(p_value?'role'OR p_value?'sections_access'OR p_value?'full_name')THEN v:='null';
  ELSIF jsonb_typeof(v)='string'AND position(p_user::text IN(v#>>'{}'))>0 AND k IN('reason','correction_reason','subject_label','teacher_label','full_name','staff_label','label')THEN v:='null';
  ELSE v:=public.uc_group_education_redact(v,p_user,attribution,subject,p_enrollment_ids,p_snapshot_ids);END IF;
  result:=result||jsonb_build_object(k,v);
 END LOOP;RETURN result;
END;$function$

CREATE OR REPLACE FUNCTION public.uc_session_redact(p_value jsonb, p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;item jsonb;k text;BEGIN
 IF p_value IS NULL THEN RETURN NULL;END IF;
 IF jsonb_typeof(p_value)='object' THEN
  -- Free text and observed labels of the erased subject cannot survive inside
  -- a retained hash/reference. Other students' rows and all revisions remain.
  IF p_value->>'user_id'=p_user::text OR p_value->>'subject_user_id'=p_user::text THEN RETURN jsonb_build_object('redacted',true,'status',p_value->'status');END IF;
  result:='{}';FOR k,item IN SELECT * FROM jsonb_each(p_value) LOOP
   IF k IN('reason','staff_reason','learner_summary','teacher_label','group_snapshot','facts_snapshot') THEN CONTINUE;END IF;
   result:=result||jsonb_build_object(k,public.uc_session_redact(item,p_user));
  END LOOP;RETURN result;
 ELSIF jsonb_typeof(p_value)='array' THEN SELECT coalesce(jsonb_agg(public.uc_session_redact(x,p_user)),'[]') INTO result FROM jsonb_array_elements(p_value)x;RETURN result;
 ELSIF p_value=to_jsonb(p_user::text) THEN RETURN 'null';ELSE RETURN p_value;END IF;
END;$function$

CREATE OR REPLACE FUNCTION public.purge_recycle_bin_30d()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count INTEGER := 0;
  v_tmp INTEGER;
BEGIN
  DELETE FROM public.education_document_records WHERE deleted_at < now() - INTERVAL '30 days';
  GET DIAGNOSTICS v_tmp = ROW_COUNT; v_count := v_count + v_tmp;
  DELETE FROM public.org_documents WHERE deleted_at < now() - INTERVAL '30 days';
  GET DIAGNOSTICS v_tmp = ROW_COUNT; v_count := v_count + v_tmp;
  DELETE FROM public.company_documents WHERE deleted_at < now() - INTERVAL '30 days';
  GET DIAGNOSTICS v_tmp = ROW_COUNT; v_count := v_count + v_tmp;
  DELETE FROM public.document_signatures WHERE deleted_at < now() - INTERVAL '30 days';
  GET DIAGNOSTICS v_tmp = ROW_COUNT; v_count := v_count + v_tmp;
  DELETE FROM public.data_subject_requests WHERE deleted_at < now() - INTERVAL '30 days';
  GET DIAGNOSTICS v_tmp = ROW_COUNT; v_count := v_count + v_tmp;
  DELETE FROM public.incoming_documents WHERE deleted_at < now() - INTERVAL '30 days';
  GET DIAGNOSTICS v_tmp = ROW_COUNT; v_count := v_count + v_tmp;
  DELETE FROM public.document_issuance_log WHERE deleted_at < now() - INTERVAL '30 days';
  GET DIAGNOSTICS v_tmp = ROW_COUNT; v_count := v_count + v_tmp;
  DELETE FROM public.commercial_proposals WHERE deleted_at < now() - INTERVAL '30 days';
  GET DIAGNOSTICS v_tmp = ROW_COUNT; v_count := v_count + v_tmp;
  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.uc_guard_staff_document_grants()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_old_sign boolean:=false; v_old_issue boolean:=false; v_new_sign boolean; v_new_issue boolean;
BEGIN
 IF auth.role()='service_role' AND auth.uid() IS NULL THEN RETURN NEW; END IF;
 IF auth.uid() IS NULL OR NOT public.account_deletion_access_allowed()
  OR NOT public.uc_platform_document_action_allowed(auth.uid(),'write')
  OR NOT public.can_access_organization(NEW.organization_id,'staff.write')
  OR NOT public.uc_document_scope_allowed(NEW.organization_id,NULL,NULL) THEN
  RAISE EXCEPTION 'Staff permission management denied' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(coalesce(NEW.sections_access,'[]'))<>'array' THEN RAISE EXCEPTION 'Unreviewed grant format' USING ERRCODE='22023'; END IF;
 IF TG_OP='UPDATE' AND (OLD.organization_id,OLD.user_id) IS NOT DISTINCT FROM (NEW.organization_id,NEW.user_id) THEN
  v_old_sign:='documents.sign'=ANY(public.org_role_default_permissions(OLD.role)) OR coalesce(OLD.sections_access,'[]') ? 'documents.sign';
  v_old_issue:='documents.issue'=ANY(public.org_role_default_permissions(OLD.role)) OR coalesce(OLD.sections_access,'[]') ? 'documents.issue';
 END IF;
 v_new_sign:='documents.sign'=ANY(public.org_role_default_permissions(NEW.role)) OR coalesce(NEW.sections_access,'[]') ? 'documents.sign';
 v_new_issue:='documents.issue'=ANY(public.org_role_default_permissions(NEW.role)) OR coalesce(NEW.sections_access,'[]') ? 'documents.issue';
 IF v_new_sign AND NOT v_old_sign AND NOT public.uc_document_action_allowed(NEW.organization_id,'sign',NULL,NULL) THEN
  RAISE EXCEPTION 'Cannot delegate document sign permission' USING ERRCODE='42501'; END IF;
 IF v_new_issue AND NOT v_old_issue AND NOT public.uc_document_action_allowed(NEW.organization_id,'issue',NULL,NULL) THEN
  RAISE EXCEPTION 'Cannot delegate document issue permission' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END;$function$

CREATE OR REPLACE FUNCTION public.uc_guard_student_frdo_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE n jsonb;o jsonb;c public.uc_student_frdo_write_contexts;v_org uuid;v_user uuid;
BEGIN
 IF TG_OP='DELETE' THEN
  -- Retain the existing trusted account-erasure route, not a general service DELETE.
  IF auth.role()='service_role' AND auth.uid() IS NULL
   AND current_setting('sintagma.account_deletion_erase_user',true)=OLD.user_id::text
   AND EXISTS(SELECT 1 FROM public.account_deletion_revocations WHERE user_id=OLD.user_id) THEN RETURN OLD;END IF;
  IF public.uc_student_frdo_delete_allowed(OLD.organization_id,OLD.user_id) THEN RETURN OLD;END IF;
  RAISE EXCEPTION 'frdo_write_access_denied' USING ERRCODE='42501';
 END IF;
 IF TG_OP='UPDATE' THEN
  IF(NEW.id,NEW.user_id,NEW.organization_id,NEW.created_at) IS DISTINCT FROM(OLD.id,OLD.user_id,OLD.organization_id,OLD.created_at)
  THEN RAISE EXCEPTION 'frdo_identity_is_immutable' USING ERRCODE='42501';END IF;
  o:=to_jsonb(OLD);
 END IF;
 n:=to_jsonb(NEW);v_org:=NEW.organization_id;v_user:=NEW.user_id;
 IF public.can_write_student_frdo_data(v_org,v_user) THEN RETURN NEW;END IF;
 IF auth.role()='service_role' AND auth.uid() IS NULL AND public.uc_student_frdo_pair_valid(v_org,v_user) THEN
  SELECT * INTO c FROM public.uc_student_frdo_write_contexts WHERE transaction_id=txid_current() AND backend_pid=pg_backend_pid() AND organization_id=v_org AND user_id=v_user ORDER BY created_at DESC,id DESC LIMIT 1;
  IF FOUND THEN
   IF c.kind='registration_details' AND public.uc_student_frdo_actor_can_write(c.actor_id,v_org,v_user,false)
    AND public.uc_student_frdo_fields_match(n,o,ARRAY['snils','birth_date']) THEN RETURN NEW;END IF;
   IF c.kind='profile_name_sync' AND TG_OP='UPDATE' AND public.uc_student_frdo_fields_match(n,o,ARRAY['last_name','first_name','middle_name']) THEN RETURN NEW;END IF;
  ELSIF public.uc_student_frdo_registration_stub(n) AND public.uc_student_frdo_fields_match(n,o,ARRAY['last_name','first_name','middle_name','gender'])
   AND(TG_OP='INSERT' OR NOT EXISTS(SELECT 1 FROM unnest(ARRAY['last_name','first_name','middle_name','gender']) key WHERE nullif(btrim(o->>key),'') IS NOT NULL AND(o->>key) IS DISTINCT FROM(n->>key))) THEN
   -- Existing register-student service caller: names/gender derived from its
   -- exact current student profile only; preserve existing manual name/gender
   -- overrides and never accept passport, education or review facts.
   RETURN NEW;
  END IF;
 END IF;
 RAISE EXCEPTION 'frdo_write_access_denied' USING ERRCODE='42501';
END;$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$
